import { sql } from "drizzle-orm";
import { pgTable, text, varchar, integer, timestamp, boolean, json, serial, numeric } from "drizzle-orm/pg-core";
import { createInsertSchema } from "drizzle-zod";
import { z } from "zod";

// User Roles enum
export const userRoles = ['superadmin', 'admin', 'user'] as const;
export type UserRole = typeof userRoles[number];

// Users table with role levels
export const users = pgTable("users", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  email: text("email").notNull().unique(), // Email is now required and unique
  password: text("password").notNull(), // Will store bcrypt hash
  role: text("role").notNull().default('user'), // superadmin, admin, user
  name: text("name"),
  lastLogin: timestamp("last_login"),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow()
});

// Companies/Organizations
export const companies = pgTable("companies", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  name: text("name").notNull(),
  createdBy: varchar("created_by").references(() => users.id),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow()
});

// OPSP/Roadmap main data
export const roadmaps = pgTable("roadmaps", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  companyId: varchar("company_id").notNull().references(() => companies.id),
  companyName: text("company_name").notNull(),

  // Foundation
  corePurpose: text("core_purpose"),
  corePurposeTitle: text("core_purpose_title").default("Core Purpose"),
  mission: text("mission"),
  missionTitle: text("mission_title").default("Mission"),
  brandPromise: text("brand_promise"),
  brandPromiseTitle: text("brand_promise_title").default("Brand Promise"),
  coreCustomer: text("core_customer"),
  coreCustomerTitle: text("core_customer_title").default("Core Customer"),
  coreValues: json("core_values").$type<Array<{id: string, name: string, description: string}>>(),
  coreValuesTitle: text("core_values_title").default("Core Values"),
  strategicAnchors: json("strategic_anchors").$type<Array<{id: string, text: string}>>(),
  strategicAnchorsTitle: text("strategic_anchors_title").default("Strategic Anchors"),

  // Three Year
  bhag: text("bhag"),
  threeHagStatement: text("three_hag_statement"),
  threeHagDate: text("three_hag_date"),
  knownFor: text("known_for"),

  // One Year
  onePhraseStrategy: text("one_phrase_strategy"),
  oneYearGoal: text("one_year_goal"),
  oneYearDate: text("one_year_date"),
  criticalNumbers: json("critical_numbers").$type<Record<string, {label: string, value: string}>>(),

  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow()
});

// Priorities table
export const priorities = pgTable("priorities", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  companyId: varchar("company_id").notNull().references(() => companies.id),
  title: text("title").notNull(),
  description: text("description"),
  owner: text("owner"),
  dueDate: text("due_date"),
  status: text("status").notNull().default('not-started'), // not-started, in-progress, completed, blocked
  progress: integer("progress").default(0),
  evidence: text("evidence"),
  type: text("type").notNull().default('priority'), // priority or capability
  displayOrder: integer("display_order").default(0), // Order for display in UI
  executiveChampion: text("executive_champion"), // Executive Champion name
  successStatement: text("success_statement"), // Success statement for the priority/capability
  createdBy: varchar("created_by").references(() => users.id),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow()
});

// Sub-priorities
export const subPriorities = pgTable("sub_priorities", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  priorityId: varchar("priority_id").notNull().references(() => priorities.id).notNull(),
  title: text("title").notNull(),
  completed: boolean("completed").default(false),
  createdAt: timestamp("created_at").defaultNow()
});

// SWOT Analysis
export const swotAnalysis = pgTable("swot_analysis", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  companyId: varchar("company_id").notNull().references(() => companies.id),
  strengths: json("strengths").$type<Array<{id: string, text: string}>>(),
  weaknesses: json("weaknesses").$type<Array<{id: string, text: string}>>(),
  opportunities: json("opportunities").$type<Array<{id: string, text: string}>>(),
  threats: json("threats").$type<Array<{id: string, text: string}>>(),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow()
});

// Rocks (Quarterly priorities linked to priorities/capabilities)
export const rocks = pgTable("rocks", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  companyId: varchar("company_id").notNull().references(() => companies.id),
  priorityId: varchar("priority_id").references(() => priorities.id), // Link to priority or capability
  text: text("text").notNull(),
  quarter: text("quarter").notNull(), // Q1, Q2, Q3, Q4
  year: integer("year").notNull(),
  category: text("category"), // Category within quarter
  status: text("status").notNull().default('not_started'), // not_started, on_track, at_risk, complete, missed
  progress: integer("progress").default(0),
  assigneeId: varchar("assignee_id").references(() => users.id),
  assigneeName: text("assignee_name"),
  // New enhanced fields
  executiveSponsor: text("executive_sponsor"), // Executive Sponsor name
  responsible: text("responsible"), // Responsible person name
  accountable: text("accountable"), // Accountable person name
  startDate: text("start_date"), // Start Date
  projectManagement: boolean("project_management").default(false), // Project Management checkbox
  bloomGrowthVisibility: boolean("bloom_growth_visibility").default(false), // BloomGrowth Visibility checkbox
  visionStatement: text("vision_statement"), // Vision statement for the Rock
  priority: boolean("priority").default(false), // High priority flag to move rock to top
  createdBy: varchar("created_by").references(() => users.id),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow()
});

// Metrics/KPIs
export const metrics = pgTable("metrics", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  companyId: varchar("company_id").notNull().references(() => companies.id),
  name: text("name").notNull(),
  category: text("category"),
  current: numeric("current", { precision: 10, scale: 2 }),
  target: numeric("target", { precision: 10, scale: 2 }),
  unit: text("unit"),
  trend: text("trend"), // up, down, stable
  status: text("status"), // on-track, at-risk, off-track
  owner: text("owner"),
  frequency: text("frequency"), // daily, weekly, monthly, quarterly
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow()
});

// Team Members (for assignment)
export const teamMembers = pgTable("team_members", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  companyId: varchar("company_id").notNull().references(() => companies.id),
  userId: varchar("user_id").references(() => users.id),
  name: text("name").notNull(),
  email: text("email"),
  role: text("role"),
  createdAt: timestamp("created_at").defaultNow()
});

// Agile Growth Checklist - 7 Attributes (multi-user support)
export const agileChecklistItems = pgTable("agile_checklist_items", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  companyId: varchar("company_id").notNull().references(() => companies.id),
  userId: varchar("user_id").notNull().references(() => users.id), // Each user has their own responses
  category: text("category").notNull(), // leadership, talent, strategy, execution, cash, customer, systems
  itemId: text("item_id").notNull(), // l1, l2, etc
  text: text("text").notNull(),
  score: integer("score").default(0), // Score from 1-5, 0 means not scored yet
  scoredAt: timestamp("scored_at"),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow()
}, (table) => ({
  // Unique constraint: each user can have one response per item per company
  uniqueUserItem: sql`UNIQUE(${table.companyId}, ${table.userId}, ${table.itemId})`
}));

// Just Get It Done - Action items list
export const justGetItDoneItems = pgTable("just_get_it_done_items", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  companyId: varchar("company_id").notNull().references(() => companies.id),
  text: text("text").notNull(),
  completed: boolean("completed").default(false),
  completedAt: timestamp("completed_at"),
  createdBy: varchar("created_by").references(() => users.id),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow()
});

// Roadmap Layouts - stores card positioning and sizing preferences
export const roadmapLayouts = pgTable("roadmap_layouts", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  companyId: varchar("company_id").notNull().references(() => companies.id).unique(),
  sectionLayouts: json("section_layouts").$type<{
    foundation?: Array<{cardId: string, width: number, order: number}>,
    threeYear?: Array<{cardId: string, width: number, order: number}>,
    oneYear?: Array<{cardId: string, width: number, order: number}>
  }>(),
  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow()
});

// Insert schemas
export const insertUserSchema = createInsertSchema(users).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
  lastLogin: true
});

export const insertCompanySchema = createInsertSchema(companies).omit({
  id: true,
  createdAt: true,
  updatedAt: true
});

export const insertRoadmapSchema = createInsertSchema(roadmaps).omit({
  id: true,
  createdAt: true,
  updatedAt: true
});

export const insertPrioritySchema = createInsertSchema(priorities).omit({
  id: true,
  createdAt: true,
  updatedAt: true
});

export const insertSubPrioritySchema = createInsertSchema(subPriorities).omit({
  id: true,
  createdAt: true
});

export const insertSwotSchema = createInsertSchema(swotAnalysis).omit({
  id: true,
  createdAt: true,
  updatedAt: true
});

export const insertRockSchema = createInsertSchema(rocks).omit({
  id: true,
  createdAt: true,
  updatedAt: true
});

export const insertMetricSchema = createInsertSchema(metrics).omit({
  id: true,
  createdAt: true,
  updatedAt: true
});

export const insertTeamMemberSchema = createInsertSchema(teamMembers).omit({
  id: true,
  createdAt: true
});

export const insertAgileChecklistItemSchema = createInsertSchema(agileChecklistItems).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
  scoredAt: true
});

export const insertJustGetItDoneItemSchema = createInsertSchema(justGetItDoneItems).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
  completedAt: true
});

export const insertRoadmapLayoutSchema = createInsertSchema(roadmapLayouts).omit({
  id: true,
  createdAt: true,
  updatedAt: true
});

// Type exports
export type InsertUser = z.infer<typeof insertUserSchema>;
export type User = typeof users.$inferSelect;

export type InsertCompany = z.infer<typeof insertCompanySchema>;
export type Company = typeof companies.$inferSelect;

export type InsertRoadmap = z.infer<typeof insertRoadmapSchema>;
export type Roadmap = typeof roadmaps.$inferSelect;

export type InsertPriority = z.infer<typeof insertPrioritySchema>;
export type Priority = typeof priorities.$inferSelect;

export type InsertSubPriority = z.infer<typeof insertSubPrioritySchema>;
export type SubPriority = typeof subPriorities.$inferSelect;

export type InsertSwot = z.infer<typeof insertSwotSchema>;
export type Swot = typeof swotAnalysis.$inferSelect;

export type InsertRock = z.infer<typeof insertRockSchema>;
export type Rock = typeof rocks.$inferSelect;

export type InsertMetric = z.infer<typeof insertMetricSchema>;
export type Metric = typeof metrics.$inferSelect;

export type InsertTeamMember = z.infer<typeof insertTeamMemberSchema>;
export type TeamMember = typeof teamMembers.$inferSelect;

export type InsertAgileChecklistItem = z.infer<typeof insertAgileChecklistItemSchema>;
export type AgileChecklistItem = typeof agileChecklistItems.$inferSelect;

export type InsertJustGetItDoneItem = z.infer<typeof insertJustGetItDoneItemSchema>;
export type JustGetItDoneItem = typeof justGetItDoneItems.$inferSelect;

export type InsertRoadmapLayout = z.infer<typeof insertRoadmapLayoutSchema>;
export type RoadmapLayout = typeof roadmapLayouts.$inferSelect;

