                                            <SelectValue placeholder="Year" />
                                          </SelectTrigger>
                                          <SelectContent>
                                            <SelectItem value="2025">2025</SelectItem>
                                            <SelectItem value="2026">2026</SelectItem>
                                          </SelectContent>
                                        </Select>
                                      </div>
                                      <div className="flex items-center space-x-2">
                                        <input
                                          type="checkbox"
                                          checked={newRockForm.priority}
                                          onChange={(e) => setNewRockForm({ ...newRockForm, priority: e.target.checked })}
                                          className="h-4 w-4 rounded border-input"
                                          data-testid={`checkbox-new-rock-priority-${priority.id}`}
                                        />
                                        <label className="text-sm text-muted-foreground">High Priority (Move to Top)</label>
                                      </div>
                                      <div className="flex gap-2">
                                        <Button
                                          variant="default"
                                          size="sm"
                                          onClick={() => handleAddRock(priority.id)}
                                          data-testid={`button-save-new-rock-${priority.id}`}
                                        >
                                          <CheckIcon className="h-3 w-3 mr-1" />
                                          Add
                                        </Button>
                                        <Button
                                          variant="ghost"
                                          size="sm"
                                          onClick={() => {
                                            setAddingRockTo(null);
                                            setNewRockForm({ text: "", assigneeId: "", assigneeName: "", quarter: "Q1", year: 2025, priority: false });
                                          }}
                                          data-testid={`button-cancel-new-rock-${priority.id}`}
                                        >
                                          <XIcon className="h-3 w-3 mr-1" />
                                          Cancel
                                        </Button>
                                      </div>
                                    </div>
                                  </div>
                                )}
                              </div>
                            )}
                          </div>
                        )}
                      </CardContent>
                    </Card>
                  ))
                )}
              </div>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

