import { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { apiRequest } from '@/lib/queryClient';
import { useLocation } from 'wouter';

export interface User {
  id: string;
  email: string;
  name?: string;
  role: 'superadmin' | 'admin' | 'user';
  createdAt?: string;
  updatedAt?: string;
}

interface AuthContextType {
  user: User | null;
  loading: boolean;
  login: (email: string, password: string) => Promise<void>;
  register: (email: string, password: string, name: string) => Promise<void>;
  logout: () => void;
  checkAuth: () => Promise<void>;
  isAuthenticated: boolean;
  hasRole: (requiredRole: 'superadmin' | 'admin' | 'user') => boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [, setLocation] = useLocation();

  // Check if user is authenticated on mount
  useEffect(() => {
    checkAuth();
  }, []);

  const checkAuth = async () => {
    try {
      const response = await fetch('/api/auth/me', {
        credentials: 'include', // Important: include cookies
      });

      if (response.ok) {
        const data = await response.json();
        setUser(data.user);
      } else {
        setUser(null);
      }
    } catch (error) {
      console.error('Auth check failed:', error);
      setUser(null);
    } finally {
      setLoading(false);
    }
  };

  const login = async (email: string, password: string) => {
    const response = await apiRequest('/api/auth/login', 'POST', { email, password });

    if (response.success) {
      setUser(response.user);
      // Cookie is set automatically by the server
    } else {
      throw new Error(response.error || 'Login failed');
    }
  };

  const register = async (email: string, password: string, name: string) => {
    const response = await apiRequest('/api/auth/register', 'POST', { 
      email, 
      password, 
      name,
      role: 'user' // Default role
    });

    if (response.success) {
      setUser(response.user);
      // Cookie is set automatically by the server
    } else {
      throw new Error(response.error || 'Registration failed');
    }
  };

  const logout = async () => {
    try {
      await apiRequest('/api/auth/logout', 'POST', {});
    } catch (error) {
      console.error('Logout failed:', error);
    }
    setUser(null);
    setLocation('/auth');
  };

  const hasRole = (requiredRole: 'superadmin' | 'admin' | 'user'): boolean => {
    if (!user) return false;

    const roleHierarchy = {
      'superadmin': 3,
      'admin': 2,
      'user': 1
    };

    const userLevel = roleHierarchy[user.role] || 0;
    const requiredLevel = roleHierarchy[requiredRole] || 0;

    return userLevel >= requiredLevel;
  };

  const value = {
    user,
    loading,
    login,
    register,
    logout,
    checkAuth,
    isAuthenticated: !!user,
    hasRole,
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}

