import { 
  type User, type InsertUser,
  type Company, type InsertCompany,
  type Roadmap, type InsertRoadmap,
  type RoadmapLayout, type InsertRoadmapLayout,
  type Priority, type InsertPriority,
  type SubPriority, type InsertSubPriority,
  type Swot, type InsertSwot,
  type Rock, type InsertRock,
  type Metric, type InsertMetric,
  type TeamMember, type InsertTeamMember,
  type AgileChecklistItem, type InsertAgileChecklistItem,
  type JustGetItDoneItem, type InsertJustGetItDoneItem,
  users, companies, roadmaps, roadmapLayouts, priorities, subPriorities,
  swotAnalysis, rocks, metrics, teamMembers, agileChecklistItems, justGetItDoneItems
} from "@shared/schema";
import { db } from "./db";
import { eq, and, sql } from "drizzle-orm";

export interface IStorage {
  // User operations
  getUser(id: string): Promise<User | undefined>;
  getUsers(): Promise<User[]>;
  getUserByEmail(email: string): Promise<User | undefined>;
  createUser(user: InsertUser): Promise<User>;
  updateUserRole(userId: string, role: string): Promise<void>;
  updateUserLastLogin(userId: string): Promise<void>;
  updateUser(userId: string, userData: Partial<InsertUser>): Promise<void>;

  // Company operations
  createCompany(company: InsertCompany): Promise<Company>;
  getCompany(id: string): Promise<Company | undefined>;
  getCompanies(): Promise<Company[]>;
  updateCompany(id: string, company: Partial<InsertCompany>): Promise<void>;

  // Roadmap operations
  createRoadmap(roadmap: InsertRoadmap): Promise<Roadmap>;
  getRoadmapByCompany(companyId: string): Promise<Roadmap | undefined>;
  updateRoadmap(id: string, roadmap: Partial<InsertRoadmap>): Promise<void>;
  updateRoadmapByCompany(companyId: string, roadmap: Partial<InsertRoadmap>): Promise<void>;

  // Roadmap Layout operations
  getRoadmapLayoutByCompany(companyId: string): Promise<RoadmapLayout | undefined>;
  upsertRoadmapLayout(companyId: string, layout: Partial<InsertRoadmapLayout>): Promise<RoadmapLayout>;

  // Priority operations
  createPriority(priority: InsertPriority): Promise<Priority>;
  getPriority(id: string): Promise<Priority | undefined>;
  getPrioritiesByCompany(companyId: string, type?: string): Promise<Priority[]>;
  updatePriority(id: string, priority: Partial<InsertPriority>): Promise<void>;
  updatePrioritiesOrder(updates: {id: string, displayOrder: number}[]): Promise<void>;
  deletePriority(id: string): Promise<void>;

  // Sub-priority operations
  createSubPriority(subPriority: InsertSubPriority): Promise<SubPriority>;
  getSubPrioritiesByPriority(priorityId: string): Promise<SubPriority[]>;
  updateSubPriority(id: string, completed: boolean): Promise<void>;
  deleteSubPriority(id: string): Promise<void>;

  // SWOT operations
  createSwot(swot: InsertSwot): Promise<Swot>;
  getSwotByCompany(companyId: string): Promise<Swot | undefined>;
  updateSwot(id: string, swot: Partial<InsertSwot>): Promise<void>;

  // Rock operations
  createRock(rock: InsertRock): Promise<Rock>;
  getRock(id: string): Promise<Rock | undefined>;
  getRocksByCompany(companyId: string): Promise<Rock[]>;
  getRocksByPriority(priorityId: string): Promise<Rock[]>;
  getRocksByAssignee(assigneeId: string): Promise<Rock[]>;
  updateRock(id: string, rock: Partial<InsertRock>): Promise<void>;
  deleteRock(id: string): Promise<void>;

  // Metric operations
  createMetric(metric: InsertMetric): Promise<Metric>;
  getMetric(id: string): Promise<Metric | undefined>;
  getMetricsByCompany(companyId: string): Promise<Metric[]>;
  updateMetric(id: string, metric: Partial<InsertMetric>): Promise<void>;
  deleteMetric(id: string): Promise<void>;

  // Team Member operations
  createTeamMember(member: InsertTeamMember): Promise<TeamMember>;
  getTeamMembersByCompany(companyId: string): Promise<TeamMember[]>;
  updateTeamMember(id: string, member: Partial<InsertTeamMember>): Promise<void>;
  deleteTeamMember(id: string): Promise<void>;

  // Agile Checklist operations
  getChecklistItemsByCompany(companyId: string): Promise<AgileChecklistItem[]>;
  getChecklistItemsByUser(companyId: string, userId: string): Promise<AgileChecklistItem[]>;
  getChecklistItemsByCategory(companyId: string, category: string): Promise<AgileChecklistItem[]>;
  updateChecklistItem(companyId: string, userId: string, itemId: string, score: number): Promise<void>;
  bulkInitializeChecklistForUser(companyId: string, userId: string, items: Array<{ category: string, itemId: string, text: string }>): Promise<void>;
  getChecklistAveragesByCompany(companyId: string): Promise<{ category: string, averageScore: number, totalUsers: number, checkedUsers: number }[]>;
  getChecklistOverallAverage(companyId: string): Promise<{ overallAverage: number, totalUsers: number, totalItemsChecked: number, totalPossibleItems: number }>;

  // Just Get It Done operations
  createJustGetItDoneItem(item: InsertJustGetItDoneItem): Promise<JustGetItDoneItem>;
  getJustGetItDoneItemsByCompany(companyId: string): Promise<JustGetItDoneItem[]>;
  updateJustGetItDoneItem(id: string, item: Partial<InsertJustGetItDoneItem>): Promise<void>;
  deleteJustGetItDoneItem(id: string): Promise<void>;

  // Rollup operations (aggregated views)
  getRoadmapWithPriorities(companyId: string): Promise<any>;
  getRocksRollup(companyId: string): Promise<any>;
  getPriorityWithRocks(priorityId: string): Promise<any>;
}

export class DbStorage implements IStorage {
  // User operations
  async getUser(id: string): Promise<User | undefined> {
    const [user] = await db.select().from(users).where(eq(users.id, id));
    return user;
  }

  async getUsers(): Promise<User[]> {
    return await db.select().from(users);
  }

  async getUserByEmail(email: string): Promise<User | undefined> {
    const [user] = await db.select().from(users).where(eq(users.email, email));
    return user;
  }

  async createUser(insertUser: InsertUser): Promise<User> {
    const [user] = await db.insert(users).values(insertUser).returning();
    return user;
  }

  async updateUserRole(userId: string, role: string): Promise<void> {
    await db.update(users).set({ role, updatedAt: new Date() }).where(eq(users.id, userId));
  }

  async updateUserLastLogin(userId: string): Promise<void> {
    await db.update(users).set({ lastLogin: new Date(), updatedAt: new Date() }).where(eq(users.id, userId));
  }

  async updateUser(userId: string, userData: Partial<InsertUser>): Promise<void> {
    await db.update(users).set({ ...userData, updatedAt: new Date() }).where(eq(users.id, userId));
  }

  // Company operations
  async createCompany(company: InsertCompany): Promise<Company> {
    const [result] = await db.insert(companies).values(company).returning();
    return result;
  }

  async getCompany(id: string): Promise<Company | undefined> {
    const [company] = await db.select().from(companies).where(eq(companies.id, id));
    return company;
  }

  async getCompanies(): Promise<Company[]> {
    return await db.select().from(companies);
  }

  async updateCompany(id: string, company: Partial<InsertCompany>): Promise<void> {
    await db.update(companies).set({ ...company, updatedAt: new Date() }).where(eq(companies.id, id));
  }

  // Roadmap operations
  async createRoadmap(roadmap: InsertRoadmap): Promise<Roadmap> {
    const [result] = await db.insert(roadmaps).values(roadmap as any).returning();
    return result;
  }

  async getRoadmapByCompany(companyId: string): Promise<Roadmap | undefined> {
    const [roadmap] = await db.select().from(roadmaps).where(eq(roadmaps.companyId, companyId));
    return roadmap;
  }

  async updateRoadmap(id: string, roadmap: Partial<InsertRoadmap>): Promise<void> {
    const updateData: any = { ...roadmap, updatedAt: new Date() };
    await db.update(roadmaps).set(updateData).where(eq(roadmaps.id, id));
  }

  async updateRoadmapByCompany(companyId: string, roadmap: Partial<InsertRoadmap>): Promise<void> {
    const updateData: any = { ...roadmap, updatedAt: new Date() };
    await db.update(roadmaps).set(updateData).where(eq(roadmaps.companyId, companyId));
  }

  // Roadmap Layout operations
  async getRoadmapLayoutByCompany(companyId: string): Promise<RoadmapLayout | undefined> {
    const [layout] = await db.select().from(roadmapLayouts).where(eq(roadmapLayouts.companyId, companyId));
    return layout;
  }

  async upsertRoadmapLayout(companyId: string, layout: Partial<InsertRoadmapLayout>): Promise<RoadmapLayout> {
    const existing = await this.getRoadmapLayoutByCompany(companyId);

    if (existing) {
      // Update existing layout
      const updateData: any = { ...layout, updatedAt: new Date() };
      await db.update(roadmapLayouts).set(updateData).where(eq(roadmapLayouts.companyId, companyId));
      const [updated] = await db.select().from(roadmapLayouts).where(eq(roadmapLayouts.companyId, companyId));
      return updated;
    } else {
      // Create new layout
      const [created] = await db.insert(roadmapLayouts).values({
        companyId,
        ...layout
      } as any).returning();
      return created;
    }
  }

  // Priority operations
  async createPriority(priority: InsertPriority): Promise<Priority> {
    const [result] = await db.insert(priorities).values(priority).returning();
    return result;
  }

  async getPriority(id: string): Promise<Priority | undefined> {
    const [priority] = await db.select().from(priorities).where(eq(priorities.id, id));
    return priority;
  }

  async getPrioritiesByCompany(companyId: string, type?: string): Promise<Priority[]> {
    if (type) {
      return await db.select().from(priorities)
        .where(and(eq(priorities.companyId, companyId), eq(priorities.type, type)))
        .orderBy(priorities.displayOrder);
    }
    return await db.select().from(priorities)
      .where(eq(priorities.companyId, companyId))
      .orderBy(priorities.displayOrder);
  }

  async updatePriority(id: string, priority: Partial<InsertPriority>): Promise<void> {
    await db.update(priorities).set({ ...priority, updatedAt: new Date() }).where(eq(priorities.id, id));
  }

  async updatePrioritiesOrder(updates: {id: string, displayOrder: number}[]): Promise<void> {
    // Batch update display orders
    await Promise.all(
      updates.map(({ id, displayOrder }) =>
        db.update(priorities)
          .set({ displayOrder, updatedAt: new Date() })
          .where(eq(priorities.id, id))
      )
    );
  }

  async deletePriority(id: string): Promise<void> {
    await db.delete(rocks).where(eq(rocks.priorityId, id));
    await db.delete(subPriorities).where(eq(subPriorities.priorityId, id));
    await db.delete(priorities).where(eq(priorities.id, id));
  }

  // Sub-priority operations
  async createSubPriority(subPriority: InsertSubPriority): Promise<SubPriority> {
    const [result] = await db.insert(subPriorities).values(subPriority).returning();
    return result;
  }

  async getSubPrioritiesByPriority(priorityId: string): Promise<SubPriority[]> {
    return await db.select().from(subPriorities).where(eq(subPriorities.priorityId, priorityId));
  }

  async updateSubPriority(id: string, completed: boolean): Promise<void> {
    await db.update(subPriorities).set({ completed }).where(eq(subPriorities.id, id));
  }

  async deleteSubPriority(id: string): Promise<void> {
    await db.delete(subPriorities).where(eq(subPriorities.id, id));
  }

  // SWOT operations
  async createSwot(swot: InsertSwot): Promise<Swot> {
    const [result] = await db.insert(swotAnalysis).values(swot as any).returning();
    return result;
  }

  async getSwotByCompany(companyId: string): Promise<Swot | undefined> {
    const [swot] = await db.select().from(swotAnalysis).where(eq(swotAnalysis.companyId, companyId));
    return swot;
  }

  async updateSwot(id: string, swot: Partial<InsertSwot>): Promise<void> {
    const updateData: any = { ...swot, updatedAt: new Date() };
    await db.update(swotAnalysis).set(updateData).where(eq(swotAnalysis.id, id));
  }

  // Rock operations
  async createRock(rock: InsertRock): Promise<Rock> {
    const [result] = await db.insert(rocks).values(rock).returning();
    return result;
  }

  async getRock(id: string): Promise<Rock | undefined> {
    const [rock] = await db.select().from(rocks).where(eq(rocks.id, id));
    return rock;
  }

  async getRocksByCompany(companyId: string): Promise<Rock[]> {
    const rockList = await db.select().from(rocks).where(eq(rocks.companyId, companyId));
    // Sort rocks - priority rocks first
    return rockList.sort((a, b) => {
      if (a.priority && !b.priority) return -1;
      if (!a.priority && b.priority) return 1;
      return 0;
    });
  }

  async getRocksByPriority(priorityId: string): Promise<Rock[]> {
    const rockList = await db.select().from(rocks).where(eq(rocks.priorityId, priorityId));
    // Sort rocks - priority rocks first
    return rockList.sort((a, b) => {
      if (a.priority && !b.priority) return -1;
      if (!a.priority && b.priority) return 1;
      return 0;
    });
  }

  async getRocksByAssignee(assigneeId: string): Promise<Rock[]> {
    return await db.select().from(rocks).where(eq(rocks.assigneeId, assigneeId));
  }

  async updateRock(id: string, rock: Partial<InsertRock>): Promise<void> {
    await db.update(rocks).set({ ...rock, updatedAt: new Date() }).where(eq(rocks.id, id));
  }

  async deleteRock(id: string): Promise<void> {
    await db.delete(rocks).where(eq(rocks.id, id));
  }

  // Metric operations
  async createMetric(metric: InsertMetric): Promise<Metric> {
    const [result] = await db.insert(metrics).values(metric).returning();
    return result;
  }

  async getMetric(id: string): Promise<Metric | undefined> {
    const [metric] = await db.select().from(metrics).where(eq(metrics.id, id));
    return metric;
  }

  async getMetricsByCompany(companyId: string): Promise<Metric[]> {
    return await db.select().from(metrics).where(eq(metrics.companyId, companyId));
  }

  async updateMetric(id: string, metric: Partial<InsertMetric>): Promise<void> {
    await db.update(metrics).set({ ...metric, updatedAt: new Date() }).where(eq(metrics.id, id));
  }

  async deleteMetric(id: string): Promise<void> {
    await db.delete(metrics).where(eq(metrics.id, id));
  }

  // Team Member operations
  async createTeamMember(member: InsertTeamMember): Promise<TeamMember> {
    const [result] = await db.insert(teamMembers).values(member).returning();
    return result;
  }

  async getTeamMembersByCompany(companyId: string): Promise<TeamMember[]> {
    return await db.select().from(teamMembers).where(eq(teamMembers.companyId, companyId));
  }

  async updateTeamMember(id: string, member: Partial<InsertTeamMember>): Promise<void> {
    await db.update(teamMembers).set(member).where(eq(teamMembers.id, id));
  }

  async deleteTeamMember(id: string): Promise<void> {
    await db.delete(teamMembers).where(eq(teamMembers.id, id));
  }

  // Agile Checklist operations
  async getChecklistItemsByCompany(companyId: string): Promise<AgileChecklistItem[]> {
    return await db.select().from(agileChecklistItems).where(eq(agileChecklistItems.companyId, companyId));
  }

  async getChecklistItemsByUser(companyId: string, userId: string): Promise<AgileChecklistItem[]> {
    return await db.select().from(agileChecklistItems)
      .where(and(
        eq(agileChecklistItems.companyId, companyId),
        eq(agileChecklistItems.userId, userId)
      ));
  }

  async getChecklistItemsByCategory(companyId: string, category: string): Promise<AgileChecklistItem[]> {
    return await db.select().from(agileChecklistItems)
      .where(and(
        eq(agileChecklistItems.companyId, companyId),
        eq(agileChecklistItems.category, category)
      ));
  }

  async updateChecklistItem(companyId: string, userId: string, itemId: string, score: number): Promise<void> {
    const existing = await db.select().from(agileChecklistItems)
      .where(and(
        eq(agileChecklistItems.companyId, companyId),
        eq(agileChecklistItems.userId, userId),
        eq(agileChecklistItems.itemId, itemId)
      ));

    if (existing.length > 0) {
      await db.update(agileChecklistItems)
        .set({ 
          score, 
          scoredAt: score > 0 ? new Date() : null,
          updatedAt: new Date() 
        })
        .where(and(
          eq(agileChecklistItems.companyId, companyId),
          eq(agileChecklistItems.userId, userId),
          eq(agileChecklistItems.itemId, itemId)
        ));
    } else {
      // Item doesn't exist for this user, create it
      // We need to get the text from an existing item or from the default items
      const existingAnyUser = await db.select().from(agileChecklistItems)
        .where(and(
          eq(agileChecklistItems.companyId, companyId),
          eq(agileChecklistItems.itemId, itemId)
        ))
        .limit(1);

      if (existingAnyUser.length > 0) {
        await db.insert(agileChecklistItems).values({
          companyId,
          userId,
          category: existingAnyUser[0].category,
          itemId,
          text: existingAnyUser[0].text,
          score,
          scoredAt: score > 0 ? new Date() : null
        });
      }
    }
  }

  async bulkInitializeChecklistForUser(companyId: string, userId: string, items: Array<{ category: string, itemId: string, text: string }>): Promise<void> {
    // Check if checklist already exists for this user
    const existing = await this.getChecklistItemsByUser(companyId, userId);
    if (existing.length > 0) {
      return; // Already initialized for this user
    }

    // Bulk insert all checklist items for this user using upsert to handle race conditions
    const checklistItems = items.map(item => ({
      companyId,
      userId,
      category: item.category,
      itemId: item.itemId,
      text: item.text,
      score: 0 // 0 means not scored yet
    }));

    // Use individual inserts with ON CONFLICT to handle race conditions
    for (const item of checklistItems) {
      try {
        await db.insert(agileChecklistItems).values(item).onConflictDoNothing();
      } catch (error: any) {
        // Ignore duplicate key errors - item already exists
        if (!error.message?.includes('duplicate key') && !error.message?.includes('unique constraint')) {
          throw error;
        }
      }
    }
  }

  async getChecklistAveragesByCompany(companyId: string): Promise<{ category: string, averageScore: number, totalUsers: number, checkedUsers: number }[]> {
    // Get all users who have checklist items for this company
    // Score is 0-5, where 0 means not scored yet
    const result = await db.execute(sql`
      SELECT 
        category,
        COUNT(DISTINCT user_id) as total_users,
        COUNT(DISTINCT CASE WHEN score > 0 THEN user_id END) as checked_users,
        COALESCE(AVG(CASE WHEN score > 0 THEN score / 5.0 ELSE 0.0 END), 0) as average_score
      FROM agile_checklist_items 
      WHERE company_id = ${companyId}
      GROUP BY category
    `);

    return result.rows.map((row: any) => ({
      category: row.category,
      averageScore: parseFloat(row.average_score),
      totalUsers: parseInt(row.total_users),
      checkedUsers: parseInt(row.checked_users)
    }));
  }

  async getChecklistOverallAverage(companyId: string): Promise<{ overallAverage: number, totalUsers: number, totalItemsChecked: number, totalPossibleItems: number }> {
    // Score is 0-5, where 0 means not scored yet
    const result = await db.execute(sql`
      SELECT 
        COUNT(DISTINCT user_id) as total_users,
        COUNT(CASE WHEN score > 0 THEN 1 END) as total_items_checked,
        COUNT(*) as total_possible_items,
        COALESCE(AVG(CASE WHEN score > 0 THEN score / 5.0 ELSE 0.0 END), 0) as overall_average
      FROM agile_checklist_items 
      WHERE company_id = ${companyId}
    `);

    const row = result.rows[0] as any;
    return {
      overallAverage: parseFloat(row.overall_average),
      totalUsers: parseInt(row.total_users),
      totalItemsChecked: parseInt(row.total_items_checked),
      totalPossibleItems: parseInt(row.total_possible_items)
    };
  }

  // Just Get It Done operations
  async createJustGetItDoneItem(item: InsertJustGetItDoneItem): Promise<JustGetItDoneItem> {
    const [result] = await db.insert(justGetItDoneItems).values(item).returning();
    return result;
  }

  async getJustGetItDoneItemsByCompany(companyId: string): Promise<JustGetItDoneItem[]> {
    return await db.select().from(justGetItDoneItems).where(eq(justGetItDoneItems.companyId, companyId));
  }

  async updateJustGetItDoneItem(id: string, item: Partial<InsertJustGetItDoneItem>): Promise<void> {
    const updateData: any = { ...item, updatedAt: new Date() };
    if (item.completed) {
      updateData.completedAt = new Date();
    } else if (item.completed === false) {
      updateData.completedAt = null;
    }
    await db.update(justGetItDoneItems).set(updateData).where(eq(justGetItDoneItems.id, id));
  }

  async deleteJustGetItDoneItem(id: string): Promise<void> {
    await db.delete(justGetItDoneItems).where(eq(justGetItDoneItems.id, id));
  }

  // Rollup operations
  async getRoadmapWithPriorities(companyId: string): Promise<any> {
    const roadmap = await this.getRoadmapByCompany(companyId);
    const priorityList = await this.getPrioritiesByCompany(companyId, 'priority');
    const capabilities = await this.getPrioritiesByCompany(companyId, 'capability');
    const swot = await this.getSwotByCompany(companyId);
    const rockList = await this.getRocksByCompany(companyId);
    const metricList = await this.getMetricsByCompany(companyId);

    // Attach rocks to priorities
    const prioritiesWithRocks = await Promise.all(priorityList.map(async (priority) => {
      const priorityRocks = rockList.filter(rock => rock.priorityId === priority.id);
      const subPriorityList = await this.getSubPrioritiesByPriority(priority.id);
      return {
        ...priority,
        rocks: priorityRocks,
        subPriorities: subPriorityList
      };
    }));

    const capabilitiesWithRocks = await Promise.all(capabilities.map(async (capability) => {
      const capabilityRocks = rockList.filter(rock => rock.priorityId === capability.id);
      const subPriorityList = await this.getSubPrioritiesByPriority(capability.id);
      return {
        ...capability,
        rocks: capabilityRocks,
        subPriorities: subPriorityList
      };
    }));

    return {
      roadmap,
      priorities: prioritiesWithRocks,
      capabilities: capabilitiesWithRocks,
      swot,
      rocks: rockList,
      metrics: metricList
    };
  }

  async getRocksRollup(companyId: string): Promise<any> {
    const rockList = await this.getRocksByCompany(companyId);
    const priorityList = await this.getPrioritiesByCompany(companyId);

    // Group rocks by quarter
    const rocksByQuarter = rockList.reduce((acc: any, rock: Rock) => {
      const key = `${rock.year}-${rock.quarter}`;
      if (!acc[key]) {
        acc[key] = [];
      }

      // Find the associated priority/capability
      const priority = priorityList.find(p => p.id === rock.priorityId);

      acc[key].push({
        ...rock,
        priorityTitle: priority?.title,
        priorityType: priority?.type
      });

      return acc;
    }, {});

    // Sort rocks within each quarter - priority rocks first
    for (const quarter in rocksByQuarter) {
      rocksByQuarter[quarter].sort((a: any, b: any) => {
        // Priority rocks come first
        if (a.priority && !b.priority) return -1;
        if (!a.priority && b.priority) return 1;
        return 0;
      });
    }

    return rocksByQuarter;
  }

  async getPriorityWithRocks(priorityId: string): Promise<any> {
    const priority = await this.getPriority(priorityId);
    if (!priority) return null;

    const priorityRocks = await this.getRocksByPriority(priorityId);
    const subPriorityList = await this.getSubPrioritiesByPriority(priorityId);

    return {
      ...priority,
      rocks: priorityRocks,
      subPriorities: subPriorityList
    };
  }
}

// Export the storage instance - use DbStorage for database operations
export const storage = new DbStorage();

