import { useState, useCallback, useMemo } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { useQuery, useMutation } from "@tanstack/react-query";
import { queryClient, apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import { 
  RocketIcon,
  TargetIcon,
  HeartIcon,
  ShieldIcon,
  UsersIcon,
  PlusIcon,
  PencilIcon,
  XIcon,
  CheckIcon,
  TrashIcon,
  BuildingIcon
} from "lucide-react";
import {
  DndContext,
  closestCenter,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  DragEndEvent,
} from '@dnd-kit/core';
import {
  arrayMove,
  SortableContext,
  sortableKeyboardCoordinates,
  verticalListSortingStrategy,
  useSortable,
} from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';

// Sortable Strategic Anchor Item Component
interface SortableStrategicAnchorProps {
  item: { id: string; text: string };
  editingField: string | null;
  editValue: string;
  editDescription: string;
  setEditValue: (value: string) => void;
  setEditDescription: (value: string) => void;
  handleEditListItem: (fieldPath: string, itemId: string, newValue: string, newDescription?: string) => Promise<void>;
  handleEdit: (fieldPath: string, currentValue: string) => void;
  setEditingField: (field: string | null) => void;
  handleCancel: () => void;
  handleDeleteItem: (fieldPath: string, itemId: string) => Promise<void>;
}

function SortableStrategicAnchor({ 
  item, 
  editingField, 
  editValue, 
  editDescription,
  setEditValue,
  setEditDescription,
  handleEditListItem,
  handleEdit,
  setEditingField,
  handleCancel,
  handleDeleteItem 
}: SortableStrategicAnchorProps) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id: item.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1,
  };

  return (
    <div 
      ref={setNodeRef} 
      style={style}
      className="group border border-cyan-500/20 rounded-lg p-3 bg-slate-800/30"
      data-testid={`strategic-anchor-${item.id}`}
    >
      {editingField === `strategicAnchors.${item.id}` ? (
        <div className="space-y-2">
          <Input
            value={editValue}
            onChange={(e) => setEditValue(e.target.value)}
            placeholder="Text"
            className="bg-slate-800/50 border-cyan-500/30 text-slate-300"
            autoFocus
          />
          <div className="flex gap-2">
            <Button
              size="sm"
              variant="ghost"
              onClick={() => {
                handleEditListItem('strategicAnchors', item.id, editValue);
                setEditingField(null);
                setEditValue("");
              }}
              className="text-green-400 hover:text-green-300"
              data-testid={`button-save-item-${item.id}`}
            >
              <CheckIcon className="h-4 w-4 mr-1" />
              Save
            </Button>
            <Button
              size="sm"
              variant="ghost"
              onClick={handleCancel}
              className="text-red-400 hover:text-red-300"
              data-testid={`button-cancel-item-${item.id}`}
            >
              <XIcon className="h-4 w-4 mr-1" />
              Cancel
            </Button>
          </div>
        </div>
      ) : (
        <div className="flex items-start justify-between gap-2">
          <div 
            {...attributes} 
            {...listeners}
            className="cursor-grab active:cursor-grabbing text-cyan-400/50 hover:text-cyan-400 transition-colors pt-1"
            data-testid={`drag-handle-${item.id}`}
          >
            <GripVerticalIcon className="h-4 w-4" />
          </div>
          <div className="flex-1">
            <h4 className="font-medium text-cyan-300">{item.text}</h4>
          </div>
          <div className="opacity-0 group-hover:opacity-100 transition-opacity flex gap-1">
            <Button
              size="icon"
              variant="ghost"
              onClick={() => {
                handleEdit(`strategicAnchors.${item.id}`, item.text);
              }}
              className="h-6 w-6 text-cyan-400 hover:text-cyan-300"
              data-testid={`button-edit-item-${item.id}`}
            >
              <PencilIcon className="h-3 w-3" />
            </Button>
            <Button
              size="icon"
              variant="ghost"
              onClick={() => handleDeleteItem('strategicAnchors', item.id)}
              className="h-6 w-6 text-red-400 hover:text-red-300"
              data-testid={`button-delete-item-${item.id}`}
            >
              <TrashIcon className="h-3 w-3" />
            </Button>
          </div>
        </div>
      )}
    </div>
  );
}

// Types
interface CoreValue {
  id: string;
  name: string;
  description: string;
}

interface StrategicAnchor {
  id: string;
  text: string;
}

interface FoundationData {
  corePurpose: string;
  mission: string;
  coreValues: CoreValue[];
  strategicAnchors: StrategicAnchor[];
  coreCustomer: string;
  brandPromise: string;
}

interface RoadmapResponse {
  roadmap: {
    corePurpose?: string;
    mission?: string;
    brandPromise?: string;
    coreCustomer?: string;
    coreValues?: CoreValue[];
    strategicAnchors?: StrategicAnchor[];
  };
}

const DEFAULT_COMPANY_ID = "200c32ef-28fe-4fa7-995d-96386671e89e";

// Helper to generate unique IDs
const generateId = () => `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

// Helper to get empty foundation data
const getEmptyFoundationData = (): FoundationData => ({
  corePurpose: "",
  mission: "",
  coreValues: [],
  strategicAnchors: [],
  coreCustomer: "",
  brandPromise: ""
});

export default function Foundation() {
  const { toast } = useToast();

  // Fetch roadmap data
  const { data: roadmapFromDB, isLoading: roadmapLoading, error: roadmapError } = useQuery<RoadmapResponse>({
    queryKey: ['/api/roadmap', DEFAULT_COMPANY_ID],
    queryFn: async () => {
      const response = await fetch(`/api/roadmap/${DEFAULT_COMPANY_ID}`);
      if (!response.ok) throw new Error('Failed to fetch roadmap');
      return response.json();
    }
  });

  // Extract foundation data from API response with memoization
  const foundationData = useMemo<FoundationData>(() => {
    if (!roadmapFromDB?.roadmap) {
      return getEmptyFoundationData();
    }

    const roadmap = roadmapFromDB.roadmap;
    return {
      corePurpose: roadmap.corePurpose || "",
      mission: roadmap.mission || "",
      brandPromise: roadmap.brandPromise || "",
      coreCustomer: roadmap.coreCustomer || "",
      coreValues: roadmap.coreValues || [],
      strategicAnchors: roadmap.strategicAnchors || []
    };
  }, [roadmapFromDB]);

  // Mutation to update roadmap data in database
  const updateRoadmapMutation = useMutation({
    mutationFn: async (data: FoundationData) => {
      return apiRequest(`/api/roadmap/${DEFAULT_COMPANY_ID}`, 'PUT', data);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/roadmap', DEFAULT_COMPANY_ID] });
      toast({
        title: "Success",
        description: "Foundation data has been saved",
      });
    },
    onError: (error: Error) => {
      toast({
        title: "Error",
        description: error.message || "Failed to save foundation data",
        variant: "destructive",
      });
    }
  });

  // State for managing editing
  const [editingField, setEditingField] = useState<string | null>(null);
  const [editValue, setEditValue] = useState("");
  const [editDescription, setEditDescription] = useState("");
  const [addingItem, setAddingItem] = useState<string | null>(null);
  const [newItemValue, setNewItemValue] = useState("");
  const [newItemDescription, setNewItemDescription] = useState("");

  // Reset all edit states
  const resetEditState = useCallback(() => {
    setEditingField(null);
    setEditValue("");
    setEditDescription("");
    setAddingItem(null);
    setNewItemValue("");
    setNewItemDescription("");
  }, []);

  // Handle simple field editing
  const handleEdit = useCallback((fieldPath: string, currentValue: string) => {
    setEditingField(fieldPath);
    setEditValue(currentValue);
  }, []);

  const handleSave = useCallback(async (fieldPath: keyof FoundationData) => {
    const updatedData = {
      ...foundationData,
      [fieldPath]: editValue
    };

    try {
      await updateRoadmapMutation.mutateAsync(updatedData as FoundationData);
      resetEditState();
    } catch (error) {
      // Error handling is done in mutation onError
    }
  }, [foundationData, editValue, updateRoadmapMutation, resetEditState]);

  // Generic handler for list item operations
  const updateListField = useCallback((
    fieldPath: 'coreValues' | 'strategicAnchors',
    updater: (items: CoreValue[] | StrategicAnchor[]) => CoreValue[] | StrategicAnchor[]
  ) => {
    const currentItems = foundationData[fieldPath];
    const updatedItems = updater(currentItems);

    const updatedData = {
      ...foundationData,
      ...(fieldPath === 'coreValues' 
        ? { coreValues: updatedItems as CoreValue[] }
        : { strategicAnchors: updatedItems as StrategicAnchor[] })
    };

    return updateRoadmapMutation.mutateAsync(updatedData);
  }, [foundationData, updateRoadmapMutation]);

  // Render editable title
  const renderEditableTitle = (icon: React.ReactNode, titleField: string, titleValue: string) => {
    const isEditing = editingField === titleField;

    return (
      <div className="flex items-center gap-2 text-lg text-cyan-300 group">
        {icon}
        {isEditing ? (
          <div className="flex items-center gap-2 flex-1">
            <Input
              value={editValue}
              onChange={(e) => setEditValue(e.target.value)}
              className="h-7 text-sm bg-cyan-950/30 border-cyan-500/30 text-cyan-100"
              autoFocus
              data-testid={`input-${titleField}`}
            />
            <Button
              size="sm"
              variant="ghost"
              onClick={() => handleSave(titleField)}
              className="h-7 w-7 p-0 text-green-400 hover:text-green-300"
              data-testid={`button-save-${titleField}`}
            >
              <CheckIcon className="h-4 w-4" />
            </Button>
            <Button
              size="sm"
              variant="ghost"
              onClick={handleCancel}
              className="h-7 w-7 p-0 text-red-400 hover:text-red-300"
              data-testid={`button-cancel-${titleField}`}
            >
              <XIcon className="h-4 w-4" />
            </Button>
          </div>
        ) : (
          <>
            <span>{titleValue}</span>
            <Button
              size="sm"
              variant="ghost"
              onClick={() => handleEdit(titleField, titleValue)}
              className="h-6 w-6 p-0 opacity-0 group-hover:opacity-100 transition-opacity text-cyan-400 hover:text-cyan-300"
              data-testid={`button-edit-${titleField}`}
            >
              <PencilIcon className="h-3 w-3" />
            </Button>
          </>
        )}
      </div>
    );
  };

  // Handle list item editing
  const handleEditListItem = useCallback(async (
    fieldPath: 'coreValues' | 'strategicAnchors',
    itemId: string,
    newValue: string,
    newDescription?: string
  ) => {
    if (fieldPath === 'coreValues') {
      await updateListField(fieldPath, (items) =>
        (items as CoreValue[]).map((item) =>
          item.id === itemId
            ? { ...item, name: newValue, description: newDescription || item.description }
            : item
        )
      );
    } else if (fieldPath === 'strategicAnchors') {
      await updateListField(fieldPath, (items) =>
        (items as StrategicAnchor[]).map((item) =>
          item.id === itemId ? { ...item, text: newValue } : item
        )
      );
    }
  }, [updateListField]);

  // Handle adding new list items
  const handleAddItem = useCallback((fieldPath: 'coreValues' | 'strategicAnchors') => {
    setAddingItem(fieldPath);
    setNewItemValue("");
    setNewItemDescription("");
  }, []);

  const handleSaveNewItem = useCallback(async (fieldPath: 'coreValues' | 'strategicAnchors') => {
    if (!newItemValue.trim()) return;

    if (fieldPath === 'coreValues') {
      const newItem: CoreValue = {
        id: generateId(),
        name: newItemValue,
        description: newItemDescription
      };

      await updateListField(fieldPath, (items) => [...(items as CoreValue[]), newItem]);
    } else if (fieldPath === 'strategicAnchors') {
      const newItem: StrategicAnchor = {
        id: generateId(),
        text: newItemValue
      };

      await updateListField(fieldPath, (items) => [...(items as StrategicAnchor[]), newItem]);
    }

    resetEditState();
  }, [newItemValue, newItemDescription, updateListField, resetEditState]);

  // Handle deleting list items
  const handleDeleteItem = useCallback(async (
    fieldPath: 'coreValues' | 'strategicAnchors',
    itemId: string
  ) => {
    if (fieldPath === 'coreValues') {
      await updateListField(fieldPath, (items) =>
        (items as CoreValue[]).filter((item) => item.id !== itemId)
      );
    } else {
      await updateListField(fieldPath, (items) =>
        (items as StrategicAnchor[]).filter((item) => item.id !== itemId)
      );
    }
  }, [updateListField]);

  // Render editable field - memoized to prevent unnecessary re-renders
  const renderEditableField = useCallback((fieldPath: keyof FoundationData, value: string, multiline = false) => {
    const isEditing = editingField === fieldPath;
    const displayValue = value || (multiline ? "Click to add..." : "Click to add...");

    if (isEditing) {
      return (
        <div className="flex gap-2 items-start">
          {multiline ? (
            <Textarea
              value={editValue}
              onChange={(e) => setEditValue(e.target.value)}
              className="flex-1 bg-slate-800/50 border-cyan-500/30 text-slate-300"
              autoFocus
              rows={3}
              placeholder="Enter text..."
            />
          ) : (
            <Input
              value={editValue}
              onChange={(e) => setEditValue(e.target.value)}
              className="flex-1 bg-slate-800/50 border-cyan-500/30 text-slate-300"
              autoFocus
              placeholder="Enter text..."
            />
          )}
          <Button
            size="icon"
            variant="ghost"
            onClick={() => handleSave(fieldPath)}
            className="h-8 w-8 text-green-400 hover:text-green-300"
            disabled={updateRoadmapMutation.isPending}
            data-testid={`button-save-${fieldPath}`}
          >
            <CheckIcon className="h-4 w-4" />
          </Button>
          <Button
            size="icon"
            variant="ghost"
            onClick={resetEditState}
            className="h-8 w-8 text-red-400 hover:text-red-300"
            disabled={updateRoadmapMutation.isPending}
            data-testid={`button-cancel-${fieldPath}`}
          >
            <XIcon className="h-4 w-4" />
          </Button>
        </div>
      );
    }

    return (
      <div className="flex gap-2 items-start group">
        <p className={`flex-1 ${multiline ? 'text-sm leading-relaxed' : 'text-lg font-medium'} text-slate-300 ${!value ? 'opacity-50 italic' : ''}`}>
          {displayValue}
        </p>
        <Button
          size="icon"
          variant="ghost"
          onClick={() => handleEdit(fieldPath, value)}
          className="h-6 w-6 text-cyan-400 hover:text-cyan-300 opacity-0 group-hover:opacity-100 transition-opacity"
          data-testid={`button-edit-${fieldPath}`}
        >
          <PencilIcon className="h-3 w-3" />
        </Button>
      </div>
    );
  }, [editingField, editValue, handleEdit, handleSave, resetEditState, updateRoadmapMutation.isPending]);

  // Render editable list - memoized
  const renderEditableList = useCallback((
    fieldPath: 'coreValues' | 'strategicAnchors',
    items: CoreValue[] | StrategicAnchor[],
    hasDescription = false
  ) => {
    return (
      <div className="space-y-3">
        {items.length === 0 && !addingItem && (
          <p className="text-sm text-slate-400 italic text-center py-4">
            No items yet. Click "Add New Item" to get started.
          </p>
        )}

        {items.map((item) => {
          const itemId = `${fieldPath}.${item.id}`;
          const isEditing = editingField === itemId;
          const itemName = 'name' in item ? item.name : item.text;

          return (
            <div key={item.id} className="group border border-cyan-500/20 rounded-lg p-3 bg-slate-800/30">
              {isEditing ? (
                <div className="space-y-2">
                  <Input
                    value={editValue}
                    onChange={(e) => setEditValue(e.target.value)}
                    placeholder={hasDescription ? "Name" : "Text"}
                    className="bg-slate-800/50 border-cyan-500/30 text-slate-300"
                    autoFocus
                  />
                  {hasDescription && (
                    <Textarea
                      value={editDescription}
                      onChange={(e) => setEditDescription(e.target.value)}
                      placeholder="Description"
                      className="bg-slate-800/50 border-cyan-500/30 text-slate-300"
                      rows={3}
                    />
                  )}
                  <div className="flex gap-2">
                    <Button
                      size="sm"
                      variant="ghost"
                      onClick={() => {
                        handleEditListItem(fieldPath, item.id, editValue, hasDescription ? editDescription : undefined);
                        resetEditState();
                      }}
                      className="text-green-400 hover:text-green-300"
                      disabled={updateRoadmapMutation.isPending}
                      data-testid={`button-save-item-${item.id}`}
                    >
                      <CheckIcon className="h-4 w-4 mr-1" />
                      Save
                    </Button>
                    <Button
                      size="sm"
                      variant="ghost"
                      onClick={resetEditState}
                      className="text-red-400 hover:text-red-300"
                      disabled={updateRoadmapMutation.isPending}
                      data-testid={`button-cancel-item-${item.id}`}
                    >
                      <XIcon className="h-4 w-4 mr-1" />
                      Cancel
                    </Button>
                  </div>
                </div>
              ) : (
                <>
                  <div className="flex items-start justify-between">
                    <div className="flex-1">
                      <h4 className="font-medium text-cyan-300 mb-1">{itemName}</h4>
                      {hasDescription && 'description' in item && item.description && (
                        <p className="text-sm text-slate-400 leading-relaxed">{item.description}</p>
                      )}
                    </div>
                    <div className="opacity-0 group-hover:opacity-100 transition-opacity flex gap-1">
                      <Button
                        size="icon"
                        variant="ghost"
                        onClick={() => {
                          handleEdit(itemId, itemName);
                          if (hasDescription && 'description' in item) {
                            setEditDescription(item.description || "");
                          }
                        }}
                        className="h-6 w-6 text-cyan-400 hover:text-cyan-300"
                        data-testid={`button-edit-item-${item.id}`}
                      >
                        <PencilIcon className="h-3 w-3" />
                      </Button>
                      <Button
                        size="icon"
                        variant="ghost"
                        onClick={() => handleDeleteItem(fieldPath, item.id)}
                        className="h-6 w-6 text-red-400 hover:text-red-300"
                        disabled={updateRoadmapMutation.isPending}
                        data-testid={`button-delete-item-${item.id}`}
                      >
                        <TrashIcon className="h-3 w-3" />
                      </Button>
                    </div>
                  </div>
                </>
              )}
            </div>
          );
        })}

        {/* Add new item */}
        {addingItem === fieldPath ? (
          <div className="border border-cyan-500/30 rounded-lg p-3 bg-slate-800/50">
            <div className="space-y-2">
              <Input
                value={newItemValue}
                onChange={(e) => setNewItemValue(e.target.value)}
                placeholder={hasDescription ? "Name" : "Text"}
                className="bg-slate-800/50 border-cyan-500/30 text-slate-300"
                autoFocus
              />
              {hasDescription && (
                <Textarea
                  value={newItemDescription}
                  onChange={(e) => setNewItemDescription(e.target.value)}
                  placeholder="Description"
                  className="bg-slate-800/50 border-cyan-500/30 text-slate-300"
                  rows={3}
                />
              )}
              <div className="flex gap-2">
                <Button
                  size="sm"
                  onClick={() => handleSaveNewItem(fieldPath)}
                  className="bg-cyan-500/20 text-cyan-300 hover:bg-cyan-500/30"
                  disabled={updateRoadmapMutation.isPending || !newItemValue.trim()}
                  data-testid={`button-save-new-${fieldPath}`}
                >
                  <CheckIcon className="h-4 w-4 mr-1" />
                  Add
                </Button>
                <Button
                  size="sm"
                  variant="ghost"
                  onClick={resetEditState}
                  className="text-red-400 hover:text-red-300"
                  disabled={updateRoadmapMutation.isPending}
                  data-testid={`button-cancel-new-${fieldPath}`}
                >
                  <XIcon className="h-4 w-4 mr-1" />
                  Cancel
                </Button>
              </div>
            </div>
          </div>
        ) : (
          <Button
            variant="outline"
            onClick={() => handleAddItem(fieldPath)}
            className="w-full border-dashed border-cyan-500/30 text-cyan-400 hover:bg-cyan-500/10"
            data-testid={`button-add-${fieldPath}`}
          >
            <PlusIcon className="h-4 w-4 mr-2" />
            Add New Item
          </Button>
        )}
      </div>
    );
  }, [
    addingItem,
    editingField,
    editValue,
    editDescription,
    newItemValue,
    newItemDescription,
    handleEdit,
    handleEditListItem,
    handleAddItem,
    handleSaveNewItem,
    handleDeleteItem,
    resetEditState,
    updateRoadmapMutation.isPending
  ]);

  if (roadmapLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-center">
          <BuildingIcon className="w-8 h-8 animate-pulse text-cyan-400 mx-auto mb-2" />
          <p className="text-cyan-400/60">Loading foundation data...</p>
        </div>
      </div>
    );
  }

  if (roadmapError) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-center">
          <p className="text-red-400 mb-2">Failed to load foundation data</p>
          <p className="text-sm text-slate-400">{roadmapError instanceof Error ? roadmapError.message : 'Unknown error'}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Page Header */}
      <div className="border-b border-cyan-500/20 pb-4">
        <div className="flex items-center gap-3 mb-2">
          <BuildingIcon className="w-6 h-6 text-cyan-400" />
          <h1 className="text-2xl font-bold text-cyan-300">Foundation</h1>
        </div>
        <p className="text-sm text-cyan-400/60">
          Define your organization's core identity and fundamental principles
        </p>
      </div>

      {/* Foundation Cards */}
      <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
        {/* Core Purpose */}
        <Card className="bg-card/50 border-cyan-500/20">
          <CardHeader className="pb-3">
            <CardTitle>
              {renderEditableTitle(
                <RocketIcon className="w-5 h-5" />,
                "corePurposeTitle",
                foundationData.corePurposeTitle
              )}
            </CardTitle>
          </CardHeader>
          <CardContent>
            {renderEditableField("corePurpose", foundationData.corePurpose, true)}
          </CardContent>
        </Card>

        {/* Mission */}
        <Card className="bg-card/50 border-cyan-500/20">
          <CardHeader className="pb-3">
            <CardTitle>
              {renderEditableTitle(
                <TargetIcon className="w-5 h-5" />,
                "missionTitle",
                foundationData.missionTitle
              )}
            </CardTitle>
          </CardHeader>
          <CardContent>
            {renderEditableField("mission", foundationData.mission, true)}
          </CardContent>
        </Card>

        {/* Brand Promise */}
        <Card className="bg-card/50 border-cyan-500/20">
          <CardHeader className="pb-3">
            <CardTitle>
              {renderEditableTitle(
                <ShieldIcon className="w-5 h-5" />,
                "brandPromiseTitle",
                foundationData.brandPromiseTitle
              )}
            </CardTitle>
          </CardHeader>
          <CardContent>
            {renderEditableField("brandPromise", foundationData.brandPromise)}
          </CardContent>
        </Card>

        {/* Core Customer */}
        <Card className="bg-card/50 border-cyan-500/20">
          <CardHeader className="pb-3">
            <CardTitle>
              {renderEditableTitle(
                <UsersIcon className="w-5 h-5" />,
                "coreCustomerTitle",
                foundationData.coreCustomerTitle
              )}
            </CardTitle>
          </CardHeader>
          <CardContent>
            {renderEditableField("coreCustomer", foundationData.coreCustomer, true)}
          </CardContent>
        </Card>

        {/* Core Values */}
        <Card className="bg-card/50 border-cyan-500/20 lg:col-span-3">
          <CardHeader className="pb-3">
            <CardTitle>
              {renderEditableTitle(
                <HeartIcon className="w-5 h-5" />,
                "coreValuesTitle",
                foundationData.coreValuesTitle
              )}
            </CardTitle>
          </CardHeader>
          <CardContent>
            {renderEditableList("coreValues", foundationData.coreValues, true)}
          </CardContent>
        </Card>

        {/* Strategic Anchors */}
        <Card className="bg-card/50 border-cyan-500/20 lg:col-span-3">
          <CardHeader className="pb-3">
            <CardTitle>
              {renderEditableTitle(
                <TargetIcon className="w-5 h-5" />,
                "strategicAnchorsTitle",
                foundationData.strategicAnchorsTitle
              )}
            </CardTitle>
          </CardHeader>
          <CardContent>
            <DndContext 
              sensors={sensors}
              collisionDetection={closestCenter}
              onDragEnd={handleDragEnd}
            >
              <SortableContext 
                items={foundationData.strategicAnchors.map(item => item.id)}
                strategy={verticalListSortingStrategy}
              >
                <div className="space-y-3">
                  {foundationData.strategicAnchors.map((item) => (
                    <SortableStrategicAnchor
                      key={item.id}
                      item={item}
                      editingField={editingField}
                      editValue={editValue}
                      editDescription={editDescription}
                      setEditValue={setEditValue}
                      setEditDescription={setEditDescription}
                      handleEditListItem={handleEditListItem}
                      handleEdit={handleEdit}
                      setEditingField={setEditingField}
                      handleCancel={handleCancel}
                      handleDeleteItem={handleDeleteItem}
                    />
                  ))}

                  {/* Add new item */}
                  {addingItem === 'strategicAnchors' ? (
                    <div className="border border-cyan-500/30 rounded-lg p-3 bg-slate-800/50">
                      <div className="space-y-2">
                        <Input
                          value={newItemValue}
                          onChange={(e) => setNewItemValue(e.target.value)}
                          placeholder="Text"
                          className="bg-slate-800/50 border-cyan-500/30 text-slate-300"
                          autoFocus
                        />
                        <div className="flex gap-2">
                          <Button
                            size="sm"
                            onClick={() => handleSaveNewItem('strategicAnchors')}
                            className="bg-cyan-500/20 text-cyan-300 hover:bg-cyan-500/30"
                            data-testid="button-save-new-strategicAnchors"
                          >
                            <CheckIcon className="h-4 w-4 mr-1" />
                            Add
                          </Button>
                          <Button
                            size="sm"
                            variant="ghost"
                            onClick={handleCancel}
                            className="text-red-400 hover:text-red-300"
                            data-testid="button-cancel-new-strategicAnchors"
                          >
                            <XIcon className="h-4 w-4 mr-1" />
                            Cancel
                          </Button>
                        </div>
                      </div>
                    </div>
                  ) : (
                    <Button
                      variant="outline"
                      onClick={() => handleAddItem('strategicAnchors')}
                      className="w-full border-dashed border-cyan-500/30 text-cyan-400 hover:bg-cyan-500/10"
                      data-testid="button-add-strategicAnchors"
                    >
                      <PlusIcon className="h-4 w-4 mr-2" />
                      Add New Item
                    </Button>
                  )}
                </div>
              </SortableContext>
            </DndContext>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

