import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

const badgeVariants = cva(
  // Whitespace-nowrap: Badges should never wrap.
  "whitespace-nowrap inline-flex items-center rounded-md border px-2.5 py-0.5 text-xs font-semibold transition-colors focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2" +
  " hover-elevate " ,
  {
    variants: {
      variant: {
        default:
          "border-transparent bg-primary text-primary-foreground shadow-xs",
        secondary: "border-transparent bg-secondary text-secondary-foreground",
        destructive:
          "border-transparent bg-destructive text-destructive-foreground shadow-xs",

        outline: " border [border-color:var(--badge-outline)] shadow-xs",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  },
)

export interface BadgeProps
  extends React.HTMLAttributes<HTMLDivElement>,
    VariantProps<typeof badgeVariants> {}

function Badge({ className, variant, ...props }: BadgeProps) {
  return (
    <div className={cn(badgeVariants({ variant }), className)} {...props} />
  );
}

export { Badge, badgeVariants }

client/src/components/RocksPage.tsx.content:
import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Checkbox } from "@/components/ui/checkbox";
import { useQuery, useMutation } from "@tanstack/react-query";
import { queryClient, apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import { type Rock, type InsertRock } from "@shared/schema";
import { 
  TargetIcon,
  CheckCircleIcon,
  CircleIcon,
  PlusIcon,
  XIcon,
  CheckIcon,
  PencilIcon,
  TrashIcon,
  CalendarIcon,
  LayoutGridIcon,
  KanbanSquareIcon,
  GripVerticalIcon,
  ListIcon,
  Grid3X3Icon,
  EyeIcon
} from "lucide-react";

interface RocksPageProps {
  currentUserId?: string;
  currentUserName?: string;
}

export default function RocksPage({ currentUserId = '1', currentUserName = 'Current User' }: RocksPageProps) {
  const { toast } = useToast();
  const DEFAULT_COMPANY_ID = "200c32ef-28fe-4fa7-995d-96386671e89e";

  // Fetch rocks from database
  const { data: myRocks = [], isLoading } = useQuery({
    queryKey: ['/api/rocks', DEFAULT_COMPANY_ID],
    queryFn: async () => {
      const response = await fetch(`/api/rocks?companyId=${DEFAULT_COMPANY_ID}`);
      if (!response.ok) throw new Error('Failed to fetch rocks');
      return response.json();
    }
  });

  const [viewMode, setViewMode] = useState<'quarter' | 'status'>('status');
  const [displayMode, setDisplayMode] = useState<'list' | 'grid' | 'kanban'>('list');
  const [editingRock, setEditingRock] = useState<string | null>(null);
  const [editForm, setEditForm] = useState({
    text: "",
    progress: 0,
    executiveSponsor: "",
    responsible: "",
    accountable: "",
    startDate: "",
    projectManagement: false,
    bloomGrowthVisibility: false,
    visionStatement: ""
  });
  const [addingRock, setAddingRock] = useState(false);
  const [newRockForm, setNewRockForm] = useState({
    text: "",
    quarter: "Q1",
    category: "capabilities",
    executiveSponsor: "",
    responsible: "",
    accountable: "",
    startDate: "",
    projectManagement: false,
    bloomGrowthVisibility: false,
    visionStatement: ""
  });
  const [draggedRock, setDraggedRock] = useState<Rock | null>(null);
  const [dragOverColumn, setDragOverColumn] = useState<string | null>(null);

  // Create rock mutation
  const createMutation = useMutation({
    mutationFn: async (data: any) => {
      return apiRequest('/api/rocks', 'POST', data);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/rocks', DEFAULT_COMPANY_ID] });
      queryClient.invalidateQueries({ queryKey: ['/api/priorities', DEFAULT_COMPANY_ID] });
      queryClient.invalidateQueries({ queryKey: ['/api/rocks/rollup', DEFAULT_COMPANY_ID] });
      setAddingRock(false);
      setNewRockForm({
        text: "", quarter: "Q1", category: "capabilities", executiveSponsor: "",
        responsible: "", accountable: "", startDate: "", projectManagement: false,
        bloomGrowthVisibility: false, visionStatement: ""
      });
      toast({
        title: "Rock created",
        description: "The rock has been successfully created.",
      });
    }
  });

  // Update rock mutation
  const updateMutation = useMutation({
    mutationFn: async ({ id, data }: any) => {
      return apiRequest(`/api/rocks/${id}`, 'PUT', data);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/rocks', DEFAULT_COMPANY_ID] });
      queryClient.invalidateQueries({ queryKey: ['/api/priorities', DEFAULT_COMPANY_ID] });
      queryClient.invalidateQueries({ queryKey: ['/api/rocks/rollup', DEFAULT_COMPANY_ID] });
      setEditingRock(null);
      toast({
        title: "Rock updated",
        description: "The rock has been successfully updated.",
      });
    }
  });

  // Delete rock mutation
  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      return apiRequest(`/api/rocks/${id}`, 'DELETE');
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/rocks', DEFAULT_COMPANY_ID] });
      queryClient.invalidateQueries({ queryKey: ['/api/priorities', DEFAULT_COMPANY_ID] });
      queryClient.invalidateQueries({ queryKey: ['/api/rocks/rollup', DEFAULT_COMPANY_ID] });
      toast({
        title: "Rock deleted",
        description: "The rock has been successfully deleted.",
      });
    }
  });

  const handleEditRock = (rock: Rock) => {
    setEditingRock(rock.id);
    setEditForm({
      text: rock.text,
      progress: rock.progress || 0,
      executiveSponsor: rock.executiveSponsor || "",
      responsible: rock.responsible || "",
      accountable: rock.accountable || "",
      startDate: rock.startDate || "",
      projectManagement: rock.projectManagement || false,
      bloomGrowthVisibility: rock.bloomGrowthVisibility || false,
      visionStatement: rock.visionStatement || ""
    });
  };

  const handleSaveEdit = (rockId: string) => {
    updateMutation.mutate({ id: rockId, data: editForm });
  };

  const handleDeleteRock = (rockId: string) => {
    deleteMutation.mutate(rockId);
  };

  const handleAddRock = () => {
    if (!newRockForm.text.trim()) return;

    createMutation.mutate({
      ...newRockForm,
      companyId: DEFAULT_COMPANY_ID,
      status: 'not_started',
      progress: 0,
      year: new Date().getFullYear()
    });
  };

  const handleDragStart = (e: React.DragEvent, rock: Rock) => {
    setDraggedRock(rock);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragOver = (e: React.DragEvent, column: string) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    setDragOverColumn(column);
  };

  const handleDragLeave = () => {
    setDragOverColumn(null);
  };

  const handleDrop = (e: React.DragEvent, targetStatus?: Rock['status'], targetQuarter?: string) => {
    e.preventDefault();
    setDragOverColumn(null);

    if (!draggedRock) return;

    const updates: any = {};

    if (targetStatus) {
      updates.status = targetStatus;
      // Auto-set progress to 100% when moved to complete
      if (targetStatus === 'complete') {
        updates.progress = 100;
      }
    }

    if (targetQuarter) {
      updates.quarter = targetQuarter;
    }

    // Update the rock in the database
    if (Object.keys(updates).length > 0) {
      updateMutation.mutate({ id: draggedRock.id, data: updates });
    }

    setDraggedRock(null);
  };

  const getCategoryColor = (category: string) => {
    switch(category) {
      case 'capabilities':
        return 'bg-purple-500/20 text-purple-300 border-purple-500/30';
      case 'priorities':
        return 'bg-blue-500/20 text-blue-300 border-blue-500/30';
      case 'department':
        return 'bg-green-500/20 text-green-300 border-green-500/30';
      default:
        return 'bg-cyan-500/20 text-cyan-300 border-cyan-500/30';
    }
  };

  const getStatusColor = (status: Rock['status']) => {
    switch(status) {
      case 'not_started':
        return 'border-slate-500/30';
      case 'ready':
        return 'border-yellow-500/30';
      case 'in_progress':
        return 'border-blue-500/30';
      case 'complete':
        return 'border-green-500/30';
      default:
        return 'border-cyan-500/30';
    }
  };

  const renderRockCard = (rock: Rock, isDraggable: boolean = true) => {
    const isGridMode = displayMode === 'grid';
    const isKanbanMode = displayMode === 'kanban';

    return (
      <div
        key={rock.id}
        draggable={isDraggable && editingRock !== rock.id}
        onDragStart={(e) => handleDragStart(e, rock)}
        className={`group bg-slate-800/30 rounded-md border ${getStatusColor(rock.status)} hover:border-cyan-500/50 transition-all ${
          isKanbanMode ? 'cursor-move' : ''
        } ${
          isGridMode ? 'p-4' : 'p-3'
        }`}
      >
        <div className={`flex ${isGridMode ? 'flex-col' : 'items-start'} gap-2`}>
          {isDraggable && isKanbanMode && (
            <GripVerticalIcon className="h-4 w-4 text-cyan-400/40 mt-0.5 opacity-0 group-hover:opacity-100 transition-opacity" />
          )}
          <div className="flex-1">
            <div className={`flex items-center gap-2 ${isGridMode ? 'mb-2' : 'mb-1'}`}>
              <Badge className={`${getCategoryColor(rock.category)} ${isGridMode ? 'text-xs' : ''}`}>
                {rock.category}
              </Badge>
              <span className="text-xs text-cyan-400/60">{rock.quarter}</span>
            </div>
          {editingRock === rock.id ? (
            <div className="space-y-2">
              <Input
                value={editForm.text}
                onChange={(e) => setEditForm({ ...editForm, text: e.target.value })}
                placeholder="Rock description..."
                className="h-7 bg-slate-800/50 border-cyan-500/30 text-slate-300 text-sm"
                autoFocus
                data-testid={`input-edit-rock-text-${rock.id}`}
              />
              <Textarea
                value={editForm.visionStatement}
                onChange={(e) => setEditForm({ ...editForm, visionStatement: e.target.value })}
                placeholder="Rock description..."
                className="min-h-[60px] bg-slate-800/50 border-cyan-500/30 text-slate-300 text-xs"
                data-testid={`input-edit-rock-vision-${rock.id}`}
              />
              <div className="grid grid-cols-2 gap-2">
                <Input
                  value={editForm.executiveSponsor}
                  onChange={(e) => setEditForm({ ...editForm, executiveSponsor: e.target.value })}
                  placeholder="Executive Sponsor"
                  className="h-7 bg-slate-800/50 border-cyan-500/30 text-slate-300 text-xs"
                  data-testid={`input-edit-rock-sponsor-${rock.id}`}
                />
                <Input
                  value={editForm.responsible}
                  onChange={(e) => setEditForm({ ...editForm, responsible: e.target.value })}
                  placeholder="Responsible"
                  className="h-7 bg-slate-800/50 border-cyan-500/30 text-slate-300 text-xs"
                  data-testid={`input-edit-rock-responsible-${rock.id}`}
                />
                <Input
                  value={editForm.accountable}
                  onChange={(e) => setEditForm({ ...editForm, accountable: e.target.value })}
                  placeholder="Accountable"
                  className="h-7 bg-slate-800/50 border-cyan-500/30 text-slate-300 text-xs"
                  data-testid={`input-edit-rock-accountable-${rock.id}`}
                />
                <Input
                  type="date"
                  value={editForm.startDate}
                  onChange={(e) => setEditForm({ ...editForm, startDate: e.target.value })}
                  className="h-7 bg-slate-800/50 border-cyan-500/30 text-slate-300 text-xs"
                  data-testid={`input-edit-rock-date-${rock.id}`}
                />
              </div>
              <div className="flex items-center gap-4 text-xs">
                <label className="flex items-center gap-1.5 text-cyan-400/80">
                  <Checkbox
                    checked={editForm.projectManagement}
                    onCheckedChange={(checked) => setEditForm({ ...editForm, projectManagement: checked as boolean })}
                    data-testid={`checkbox-edit-rock-pm-${rock.id}`}
                  />
                  <span>Project Management</span>
                </label>
                <label className="flex items-center gap-1.5 text-cyan-400/80">
                  <Checkbox
                    checked={editForm.bloomGrowthVisibility}
                    onCheckedChange={(checked) => setEditForm({ ...editForm, bloomGrowthVisibility: checked as boolean })}
                    data-testid={`checkbox-edit-rock-bloom-${rock.id}`}
                  />
                  <span>BloomGrowth Visibility</span>
                </label>
              </div>
              <div className="flex items-center gap-2">
                <span className="text-xs text-cyan-400/60">Progress:</span>
                <Input
                  type="number"
                  min="0"
                  max="100"
                  value={editForm.progress}
                  onChange={(e) => setEditForm({ ...editForm, progress: Math.min(100, Math.max(0, parseInt(e.target.value) || 0)) })}
                  className="h-6 w-20 bg-slate-800/50 border-cyan-500/30 text-slate-300 text-xs"
                  data-testid={`input-edit-rock-progress-${rock.id}`}
                />
                <span className="text-xs text-cyan-400/60">%</span>
                <div className="flex gap-1 ml-auto">
                  <Button
                    size="icon"
                    variant="ghost"
                    onClick={() => handleSaveEdit(rock.id)}
                    className="h-6 w-6 text-green-400"
                    data-testid={`button-save-rock-${rock.id}`}
                  >
                    <CheckIcon className="h-3 w-3" />
                  </Button>
                  <Button
                    size="icon"
                    variant="ghost"
                    onClick={() => setEditingRock(null)}
                    className="h-6 w-6 text-red-400"
                    data-testid={`button-cancel-rock-${rock.id}`}
                  >
                    <XIcon className="h-3 w-3" />
                  </Button>
                </div>
              </div>
            </div>
          ) : (
            <>
              <p className={`${isGridMode ? 'text-sm' : 'text-xs'} text-slate-300 ${rock.status === 'complete' ? 'line-through opacity-60' : ''} ${
                isGridMode ? 'line-clamp-3' : 'line-clamp-2'
              }`}>
                {rock.text}
              </p>
              {rock.assigneeName && (
                <p className="text-xs text-slate-400 mt-1">
                  • {rock.assigneeName}
                </p>
              )}
              <div className="mt-2">
                <div className="flex items-center justify-between mb-1">
                  <span className="text-xs text-cyan-400/60">Progress</span>
                  <span className="text-xs text-cyan-400">{rock.progress}%</span>
                </div>
                <div className="h-1 bg-slate-700 rounded-full overflow-hidden">
                  <div 
                    className={`h-full transition-all ${rock.status === 'complete' ? 'bg-green-400' : 'bg-cyan-400'}`}
                    style={{ width: `${rock.progress}%` }}
                  />
                </div>
              </div>
            </>
          )}
        </div>
        {editingRock !== rock.id && (
          <div className="opacity-0 group-hover:opacity-100 transition-opacity flex gap-0.5">
            <Button
              size="icon"
              variant="ghost"
              onClick={() => handleEditRock(rock)}
              className="h-5 w-5 text-cyan-400 hover:text-cyan-300"
              data-testid={`button-edit-${rock.id}`}
            >
              <PencilIcon className="h-3 w-3" />
            </Button>
            <Button
              size="icon"
              variant="ghost"
              onClick={() => handleDeleteRock(rock.id)}
              className="h-5 w-5 text-red-400 hover:text-red-300"
              data-testid={`button-delete-${rock.id}`}
            >
              <TrashIcon className="h-3 w-3" />
            </Button>
          </div>
        )}
      </div>
    </div>
    );
  };

  const renderStatusView = () => {
    const statuses: { key: Rock['status']; label: string; color: string }[] = [
      { key: 'not_started', label: 'Backlog', color: 'bg-slate-800/50' },
      { key: 'ready', label: 'Ready', color: 'bg-yellow-900/20' },
      { key: 'in_progress', label: 'In Progress', color: 'bg-blue-900/20' },
      { key: 'complete', label: 'Complete', color: 'bg-green-900/20' }
    ];

    return (
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-4">
        {statuses.map(status => {
          const rocks = myRocks.filter(r => r.status === status.key);

          return (
            <div
              key={status.key}
              className={`${status.color} rounded-lg border ${dragOverColumn === status.key ? 'border-cyan-400' : 'border-cyan-500/20'} transition-colors`}
              onDragOver={(e) => handleDragOver(e, status.key)}
              onDragLeave={handleDragLeave}
              onDrop={(e) => handleDrop(e, status.key)}
            >
              <div className="p-4 border-b border-cyan-500/20">
                <div className="flex items-center justify-between">
                  <h3 className="text-sm font-semibold text-cyan-300">{status.label}</h3>
                  <Badge className="bg-cyan-500/20 text-cyan-300 border-cyan-500/30">
                    {rocks.length}
                  </Badge>
                </div>
              </div>
              <div className={`p-4 ${displayMode === 'grid' ? 'grid grid-cols-1 md:grid-cols-2 gap-3' : 'space-y-3'} min-h-[200px]`}>
                {rocks.length > 0 ? (
                  rocks.map(rock => renderRockCard(rock))
                ) : (
                  <p className="text-xs text-slate-400 italic text-center py-8">
                    Drop rocks here
                  </p>
                )}
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  const renderQuarterView = () => {
    const quarters = ['Q1', 'Q2', 'Q3', 'Q4'];

    return (
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-4">
        {quarters.map(quarter => {
          const rocks = myRocks.filter(r => r.quarter === quarter);

          return (
            <div
              key={quarter}
              className={`bg-slate-800/30 rounded-lg border ${dragOverColumn === quarter ? 'border-cyan-400' : 'border-cyan-500/20'} transition-colors`}
              onDragOver={(e) => handleDragOver(e, quarter)}
              onDragLeave={handleDragLeave}
              onDrop={(e) => handleDrop(e, undefined, quarter)}
            >
              <div className="p-4 border-b border-cyan-500/20">
                <div className="flex items-center justify-between">
                  <h3 className="text-sm font-semibold text-cyan-300 flex items-center gap-2">
                    <CalendarIcon className="h-4 w-4" />
                    {quarter}
                  </h3>
                  <Badge className="bg-cyan-500/20 text-cyan-300 border-cyan-500/30">
                    {rocks.length}
                  </Badge>
                </div>
              </div>
              <div className={`p-4 ${displayMode === 'grid' ? 'grid grid-cols-1 md:grid-cols-2 gap-3' : 'space-y-3'} min-h-[200px]`}>
                {rocks.length > 0 ? (
                  rocks.map(rock => renderRockCard(rock))
                ) : (
                  <p className="text-xs text-slate-400 italic text-center py-8">
                    Drop rocks here
                  </p>
                )}
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  return (
    <div className="p-6 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-cyan-300 flex items-center gap-2">
            <TargetIcon className="h-6 w-6" />
            My Rocks
          </h1>
          <p className="text-sm text-cyan-400/60 mt-1">
            Track and manage your quarterly rocks and priorities
          </p>
        </div>
        <div className="flex items-center gap-2">
          <div className="flex bg-slate-800/50 rounded-md p-1">
            <Button
              size="sm"
              variant={viewMode === 'status' ? 'default' : 'ghost'}
              onClick={() => setViewMode('status')}
              className="text-xs"
              data-testid="button-view-status"
            >
              <KanbanSquareIcon className="h-3 w-3 mr-1" />
              Status
            </Button>
            <Button
              size="sm"
              variant={viewMode === 'quarter' ? 'default' : 'ghost'}
              onClick={() => setViewMode('quarter')}
              className="text-xs"
              data-testid="button-view-quarter"
            >
              <LayoutGridIcon className="h-3 w-3 mr-1" />
              Quarter
            </Button>
          </div>
          <div className="flex bg-slate-800/50 rounded-md p-1">
            <Button
              size="sm"
              variant={displayMode === 'list' ? 'default' : 'ghost'}
              onClick={() => setDisplayMode('list')}
              className="text-xs"
              data-testid="button-display-list"
            >
              <ListIcon className="h-3 w-3 mr-1" />
              List
            </Button>
            <Button
              size="sm"
              variant={displayMode === 'grid' ? 'default' : 'ghost'}
              onClick={() => setDisplayMode('grid')}
              className="text-xs"
              data-testid="button-display-grid"
            >
              <Grid3X3Icon className="h-3 w-3 mr-1" />
              Grid
            </Button>
            <Button
              size="sm"
              variant={displayMode === 'kanban' ? 'default' : 'ghost'}
              onClick={() => setDisplayMode('kanban')}
              className="text-xs"
              data-testid="button-display-kanban"
            >
              <EyeIcon className="h-3 w-3 mr-1" />
              Kanban
            </Button>
          </div>
          <Button
            onClick={() => setAddingRock(true)}
            className="bg-cyan-500/20 text-cyan-300 hover:bg-cyan-500/30 border border-cyan-500/30"
            data-testid="button-add-rock"
          >
            <PlusIcon className="h-4 w-4 mr-2" />
            Add Rock
          </Button>
        </div>
      </div>

      {/* Add Rock Form */}
      {addingRock && (
        <Card className="bg-card/50 border-cyan-500/20 backdrop-blur-sm">
          <CardHeader className="bg-slate-800/50 border-b border-cyan-500/20">
            <CardTitle className="text-sm text-cyan-300">Add New Rock</CardTitle>
          </CardHeader>
          <CardContent className="pt-4 space-y-4">
            <Input
              value={newRockForm.text}
              onChange={(e) => setNewRockForm({ ...newRockForm, text: e.target.value })}
              placeholder="Describe your rock..."
              className="bg-slate-800/50 border-cyan-500/30 text-slate-300"
              autoFocus
              data-testid="input-add-rock-text"
            />
            <Textarea
              value={newRockForm.visionStatement}
              onChange={(e) => setNewRockForm({ ...newRockForm, visionStatement: e.target.value })}
              placeholder="Rock description..."
              className="min-h-[60px] bg-slate-800/50 border-cyan-500/30 text-slate-300"
              data-testid="input-add-rock-vision"
            />
            <div className="grid grid-cols-2 gap-4">
              <select
                value={newRockForm.quarter}
                onChange={(e) => setNewRockForm({ ...newRockForm, quarter: e.target.value })}
                className="h-9 bg-slate-800/50 border border-cyan-500/30 text-slate-300 rounded px-3"
                data-testid="select-add-rock-quarter"
              >
                <option value="Q1">Q1</option>
                <option value="Q2">Q2</option>
                <option value="Q3">Q3</option>
                <option value="Q4">Q4</option>
              </select>
              <select
                value={newRockForm.category}
                onChange={(e) => setNewRockForm({ ...newRockForm, category: e.target.value })}
                className="h-9 bg-slate-800/50 border border-cyan-500/30 text-slate-300 rounded px-3"
                data-testid="select-add-rock-category"
              >
                <option value="capabilities">Capabilities</option>
                <option value="priorities">Priorities</option>
                <option value="department">Department</option>
              </select>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <Input
                value={newRockForm.executiveSponsor}
                onChange={(e) => setNewRockForm({ ...newRockForm, executiveSponsor: e.target.value })}
                placeholder="Executive Sponsor"
                className="bg-slate-800/50 border-cyan-500/30 text-slate-300"
                data-testid="input-add-rock-sponsor"
              />
              <Input
                value={newRockForm.responsible}
                onChange={(e) => setNewRockForm({ ...newRockForm, responsible: e.target.value })}
                placeholder="Responsible"
                className="bg-slate-800/50 border-cyan-500/30 text-slate-300"
                data-testid="input-add-rock-responsible"
              />
              <Input
                value={newRockForm.accountable}
                onChange={(e) => setNewRockForm({ ...newRockForm, accountable: e.target.value })}
                placeholder="Accountable"
                className="bg-slate-800/50 border-cyan-500/30 text-slate-300"
                data-testid="input-add-rock-accountable"
              />
              <Input
                type="date"
                value={newRockForm.startDate}
                onChange={(e) => setNewRockForm({ ...newRockForm, startDate: e.target.value })}
                placeholder="Start Date"
                className="bg-slate-800/50 border-cyan-500/30 text-slate-300"
                data-testid="input-add-rock-date"
              />
            </div>
            <div className="flex items-center gap-6">
              <label className="flex items-center gap-2 text-sm text-cyan-400/80">
                <Checkbox
                  checked={newRockForm.projectManagement}
                  onCheckedChange={(checked) => setNewRockForm({ ...newRockForm, projectManagement: checked as boolean })}
                  data-testid="checkbox-add-rock-pm"
                />
                <span>Project Management</span>
              </label>
              <label className="flex items-center gap-2 text-sm text-cyan-400/80">
                <Checkbox
                  checked={newRockForm.bloomGrowthVisibility}
                  onCheckedChange={(checked) => setNewRockForm({ ...newRockForm, bloomGrowthVisibility: checked as boolean })}
                  data-testid="checkbox-add-rock-bloom"
                />
                <span>BloomGrowth Visibility</span>
              </label>
            </div>
            <div className="flex gap-2 justify-end">
              <Button
                variant="ghost"
                onClick={() => {
                  setAddingRock(false);
                  setNewRockForm({
                    text: "", quarter: "Q1", category: "capabilities", executiveSponsor: "",
                    responsible: "", accountable: "", startDate: "", projectManagement: false,
                    bloomGrowthVisibility: false, visionStatement: ""
                  });
                }}
                className="text-red-400 hover:text-red-300"
                data-testid="button-cancel-add-rock"
              >
                Cancel
              </Button>
              <Button
                onClick={handleAddRock}
                className="bg-green-500/20 text-green-300 hover:bg-green-500/30 border border-green-500/30"
                data-testid="button-save-add-rock"
              >
                <CheckIcon className="h-4 w-4 mr-2" />
                Save Rock
              </Button>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Main Content */}
      {viewMode === 'status' ? renderStatusView() : renderQuarterView()}

      {/* Summary Stats */}
      <Card className="bg-card/50 border-cyan-500/20 backdrop-blur-sm">
        <CardHeader className="bg-slate-800/50 border-b border-cyan-500/20">
          <CardTitle className="text-sm text-cyan-300">Rock Statistics</CardTitle>
        </CardHeader>
        <CardContent className="pt-4">
          <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
            <div className="text-center">
              <p className="text-2xl font-bold text-cyan-300">{myRocks.length}</p>
              <p className="text-xs text-cyan-400/60">Total Rocks</p>
            </div>
            <div className="text-center">
              <p className="text-2xl font-bold text-slate-300">
                {myRocks.filter(r => r.status === 'backlog').length}
              </p>
              <p className="text-xs text-cyan-400/60">Backlog</p>
            </div>
            <div className="text-center">
              <p className="text-2xl font-bold text-yellow-300">
                {myRocks.filter(r => r.status === 'ready').length}
              </p>
              <p className="text-xs text-cyan-400/60">Ready</p>
            </div>
            <div className="text-center">
              <p className="text-2xl font-bold text-blue-300">
                {myRocks.filter(r => r.status === 'in_progress').length}
              </p>
              <p className="text-xs text-cyan-400/60">In Progress</p>
            </div>
            <div className="text-center">
              <p className="text-2xl font-bold text-green-300">
                {myRocks.filter(r => r.status === 'complete').length}
              </p>
              <p className="text-xs text-cyan-400/60">Complete</p>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

client/src/components/AuthCard.tsx.content:
import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Search, Computer, LogOutIcon, UserIcon, SettingsIcon } from "lucide-react";

interface User {
  id: string;
  name: string;
  email: string;
  avatar?: string;
  role: 'Admin' | 'Owner' | 'Editor' | 'Viewer' | 'Coach';
  organization: string;
}

interface AuthCardProps {
  user: User | null;
  onSignIn: (provider: 'google' | 'microsoft') => void;
  onSignOut: () => void;
}

export default function AuthCard({ user, onSignIn, onSignOut }: AuthCardProps) {
  const [isLoading, setIsLoading] = useState<'google' | 'microsoft' | null>(null);

  const handleSignIn = async (provider: 'google' | 'microsoft') => {
    setIsLoading(provider);
    try {
      await onSignIn(provider);
    } finally {
      setIsLoading(null);
    }
  };

  const getRoleColor = (role: User['role']) => {
    const colors = {
      Admin: 'bg-red-100 text-red-800 dark:bg-red-800 dark:text-red-100',
      Owner: 'bg-purple-100 text-purple-800 dark:bg-purple-800 dark:text-purple-100',
      Editor: 'bg-blue-100 text-blue-800 dark:bg-blue-800 dark:text-blue-100',
      Viewer: 'bg-gray-100 text-gray-800 dark:bg-gray-800 dark:text-gray-100',
      Coach: 'bg-green-100 text-green-800 dark:bg-green-800 dark:text-green-100'
    };
    return colors[role];
  };

  if (user) {
    return (
      <Card className="w-full max-w-md" data-testid="card-user-profile">
        <CardHeader className="pb-4">
          <div className="flex items-center gap-3">
            <Avatar className="h-12 w-12">
              <AvatarImage src={user.avatar} alt={user.name} />
              <AvatarFallback>
                <UserIcon className="h-6 w-6" />
              </AvatarFallback>
            </Avatar>
            <div className="flex-1">
              <CardTitle className="text-lg">{user.name}</CardTitle>
              <p className="text-sm text-muted-foreground">{user.email}</p>
            </div>
          </div>
        </CardHeader>

        <CardContent className="space-y-4">
          <div className="flex items-center justify-between">
            <span className="text-sm font-medium">Role</span>
            <Badge className={getRoleColor(user.role)} data-testid="badge-user-role">
              {user.role}
            </Badge>
          </div>

          <div className="flex items-center justify-between">
            <span className="text-sm font-medium">Organization</span>
            <span className="text-sm text-muted-foreground">{user.organization}</span>
          </div>

          <div className="flex gap-2 pt-4 border-t">
            <Button 
              variant="outline" 
              size="sm" 
              className="flex-1"
              data-testid="button-settings"
            >
              <SettingsIcon className="w-4 h-4 mr-2" />
              Settings
            </Button>
            <Button 
              variant="outline" 
              size="sm"
              onClick={onSignOut}
              data-testid="button-sign-out"
            >
              <LogOutIcon className="w-4 h-4 mr-2" />
              Sign Out
            </Button>
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className="w-full max-w-md" data-testid="card-auth">
      <CardHeader className="text-center">
        <CardTitle className="text-2xl">Welcome to OPSP</CardTitle>
        <p className="text-muted-foreground">
          Sign in to access your strategic planning workspace
        </p>
      </CardHeader>

      <CardContent className="space-y-4">
        <Button
          onClick={() => handleSignIn('google')}
          disabled={isLoading !== null}
          className="w-full"
          variant="outline"
          data-testid="button-sign-in-google"
        >
          {isLoading === 'google' ? (
            <div className="w-4 h-4 border-2 border-current border-t-transparent rounded-full animate-spin mr-2" />
          ) : (
            <Search className="w-4 h-4 mr-2" />
          )}
          Continue with Google
        </Button>

        <Button
          onClick={() => handleSignIn('microsoft')}
          disabled={isLoading !== null}
          className="w-full"
          variant="outline"
          data-testid="button-sign-in-microsoft"
        >
          {isLoading === 'microsoft' ? (
            <div className="w-4 h-4 border-2 border-current border-t-transparent rounded-full animate-spin mr-2" />
          ) : (
            <Computer className="w-4 h-4 mr-2" />
          )}
          Continue with Microsoft
        </Button>

        <div className="text-center text-xs text-muted-foreground pt-4">
          By continuing, you agree to our Terms of Service and Privacy Policy
        </div>
      </CardContent>
    </Card>
  );
}

// Simple icon components since we need them for the auth providers
function GoogleIcon({ className }: { className?: string }) {
  return (
    <svg className={className} viewBox="0 0 24 24" fill="currentColor">
      <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z" />
      <path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" />
      <path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z" />
      <path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" />
    </svg>
  );
}

function MicrosoftIcon({ className }: { className?: string }) {
  return (
    <svg className={className} viewBox="0 0 24 24" fill="currentColor">
      <path d="M11.4 24H0V12.6h11.4V24zM24 24H12.6V12.6H24V24zM11.4 11.4H0V0h11.4v11.4zM24 11.4H12.6V0H24v11.4z" />
    </svg>
  );
}

