import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { TrendingUpIcon, TargetIcon, EditIcon, SaveIcon, XIcon } from "lucide-react";

interface LerPowerSectionProps {
  lerData: {
    grossProfit: number;
    laborCost: number;
    ratio: number;
  };
  powerOfOne: {
    lever: string;
    goal: string;
  };
  onLerUpdate: (data: any) => void;
  onPowerUpdate: (data: any) => void;
}

export default function LerPowerSection({ 
  lerData, 
  powerOfOne, 
  onLerUpdate, 
  onPowerUpdate 
}: LerPowerSectionProps) {
  const [isEditingLer, setIsEditingLer] = useState(false);
  const [isEditingPower, setIsEditingPower] = useState(false);
  const [tempLer, setTempLer] = useState(lerData);
  const [tempPower, setTempPower] = useState(powerOfOne);

  const calculateLer = (grossProfit: number, laborCost: number) => {
    if (laborCost === 0) return 0;
    return Number((grossProfit / laborCost).toFixed(2));
  };

  const saveLer = () => {
    const ratio = calculateLer(tempLer.grossProfit, tempLer.laborCost);
    onLerUpdate({ ...tempLer, ratio });
    setIsEditingLer(false);
  };

  const savePower = () => {
    onPowerUpdate(tempPower);
    setIsEditingPower(false);
  };

  const getLerColor = (ratio: number) => {
    if (ratio >= 3) return "text-green-400";
    if (ratio >= 2) return "text-yellow-400";
    return "text-red-400";
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
      <Card className="bg-card/50 border-cyan-500/20 backdrop-blur-sm hover:border-cyan-400/40 transition-all duration-300">
        <CardHeader>
          <div className="flex items-center justify-between">
            <CardTitle className="text-cyan-300">Labor Efficiency Ratio (LER)</CardTitle>
            {isEditingLer ? (
              <div className="flex gap-2">
                <Button 
                  size="sm" 
                  variant="ghost" 
                  onClick={saveLer}
                  className="text-cyan-400 hover:text-cyan-300"
                  data-testid="button-save-ler"
                >
                  <SaveIcon className="w-4 h-4" />
                </Button>
                <Button 
                  size="sm" 
                  variant="ghost" 
                  onClick={() => {
                    setTempLer(lerData);
                    setIsEditingLer(false);
                  }}
                  className="text-cyan-400 hover:text-cyan-300"
                  data-testid="button-cancel-ler"
                >
                  <XIcon className="w-4 h-4" />
                </Button>
              </div>
            ) : (
              <Button 
                size="sm" 
                variant="ghost" 
                onClick={() => setIsEditingLer(true)}
                className="text-cyan-400 hover:text-cyan-300"
                data-testid="button-edit-ler"
              >
                <EditIcon className="w-4 h-4" />
              </Button>
            )}
          </div>
        </CardHeader>
        <CardContent className="space-y-4">
          {isEditingLer ? (
            <div className="space-y-3">
              <div>
                <label className="text-xs text-cyan-300/60 mb-1 block">Gross Profit</label>
                <Input
                  type="number"
                  value={tempLer.grossProfit}
                  onChange={(e) => setTempLer({ ...tempLer, grossProfit: Number(e.target.value) })}
                  className="bg-background/50 border-cyan-500/30 text-cyan-100"
                  data-testid="input-gross-profit"
                />
              </div>
              <div>
                <label className="text-xs text-cyan-300/60 mb-1 block">Labor Cost</label>
                <Input
                  type="number"
                  value={tempLer.laborCost}
                  onChange={(e) => setTempLer({ ...tempLer, laborCost: Number(e.target.value) })}
                  className="bg-background/50 border-cyan-500/30 text-cyan-100"
                  data-testid="input-labor-cost"
                />
              </div>
            </div>
          ) : (
            <>
              <div className="flex items-center justify-between">
                <span className="text-sm text-cyan-300/60">Ratio</span>
                <div className="flex items-center gap-2">
                  <span className={`text-2xl font-bold ${getLerColor(lerData.ratio)}`}>
                    {lerData.ratio}
                  </span>
                  <TrendingUpIcon className={`w-5 h-5 ${getLerColor(lerData.ratio)}`} />
                </div>
              </div>
              <div className="space-y-2 pt-2 border-t border-cyan-500/20">
                <div className="flex justify-between text-sm">
                  <span className="text-cyan-300/60">Gross Profit</span>
                  <span className="text-cyan-100">${lerData.grossProfit.toLocaleString()}</span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-cyan-300/60">Labor Cost</span>
                  <span className="text-cyan-100">${lerData.laborCost.toLocaleString()}</span>
                </div>
              </div>
              <div className="mt-4">
                <div className="text-xs text-cyan-300/40 italic">
                  Formula: Gross Profit ÷ Labor Cost
                </div>
              </div>
            </>
          )}
        </CardContent>
      </Card>

      <Card className="bg-card/50 border-cyan-500/20 backdrop-blur-sm hover:border-cyan-400/40 transition-all duration-300">
        <CardHeader>
          <div className="flex items-center justify-between">
            <CardTitle className="text-cyan-300">Power of One Focus</CardTitle>
            {isEditingPower ? (
              <div className="flex gap-2">
                <Button 
                  size="sm" 
                  variant="ghost" 
                  onClick={savePower}
                  className="text-cyan-400 hover:text-cyan-300"
                  data-testid="button-save-power"
                >
                  <SaveIcon className="w-4 h-4" />
                </Button>
                <Button 
                  size="sm" 
                  variant="ghost" 
                  onClick={() => {
                    setTempPower(powerOfOne);
                    setIsEditingPower(false);
                  }}
                  className="text-cyan-400 hover:text-cyan-300"
                  data-testid="button-cancel-power"
                >
                  <XIcon className="w-4 h-4" />
                </Button>
              </div>
            ) : (
              <Button 
                size="sm" 
                variant="ghost" 
                onClick={() => setIsEditingPower(true)}
                className="text-cyan-400 hover:text-cyan-300"
                data-testid="button-edit-power"
              >
                <EditIcon className="w-4 h-4" />
              </Button>
            )}
          </div>
        </CardHeader>
        <CardContent className="space-y-4">
          {isEditingPower ? (
            <div className="space-y-3">
              <div>
                <label className="text-xs text-cyan-300/60 mb-1 block">Lever</label>
                <Input
                  value={tempPower.lever}
                  onChange={(e) => setTempPower({ ...tempPower, lever: e.target.value })}
                  placeholder="Key lever to focus on"
                  className="bg-background/50 border-cyan-500/30 text-cyan-100"
                  data-testid="input-power-lever"
                />
              </div>
              <div>
                <label className="text-xs text-cyan-300/60 mb-1 block">Goal</label>
                <Input
                  value={tempPower.goal}
                  onChange={(e) => setTempPower({ ...tempPower, goal: e.target.value })}
                  placeholder="Target goal"
                  className="bg-background/50 border-cyan-500/30 text-cyan-100"
                  data-testid="input-power-goal"
                />
              </div>
            </div>
          ) : (
            <>
              <div className="space-y-3">
                <div className="flex items-start gap-3">
                  <div className="mt-1">
                    <TargetIcon className="w-4 h-4 text-cyan-400" />
                  </div>
                  <div className="flex-1">
                    <div className="text-xs text-cyan-300/60 mb-1">Lever</div>
                    <div className="text-sm text-cyan-100">
                      {powerOfOne.lever || <span className="italic text-cyan-300/40">Not set</span>}
                    </div>
                  </div>
                </div>
                <div className="flex items-start gap-3">
                  <div className="mt-1">
                    <Badge className="bg-cyan-500/20 text-cyan-300 border-cyan-500/30">Goal</Badge>
                  </div>
                  <div className="flex-1">
                    <div className="text-sm text-cyan-100">
                      {powerOfOne.goal || <span className="italic text-cyan-300/40">Not set</span>}
                    </div>
                  </div>
                </div>
              </div>
              <div className="mt-4 pt-4 border-t border-cyan-500/20">
                <div className="text-xs text-cyan-300/40 italic">
                  Focus on one key metric that drives significant impact
                </div>
              </div>
            </>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

