client/src/pages/IndividualRocks.tsx.content:
import { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useQuery, useMutation } from "@tanstack/react-query";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import { UserIcon, CheckIcon, XIcon, FlameIcon, ChevronRightIcon, ChevronDownIcon } from "lucide-react";
import { ActionMenu } from "@/components/ui/ActionMenu";

const DEFAULT_COMPANY_ID = "200c32ef-28fe-4fa7-995d-96386671e89e";

export default function IndividualRocks() {
  const { toast } = useToast();

  // Get current user
  const { data: currentUser } = useQuery({
    queryKey: ['/api/users/me'],
    queryFn: async () => {
      const response = await fetch('/api/users/me');
      if (!response.ok) {
        // If no current user endpoint, fallback to getting first user
        const allUsersResponse = await fetch('/api/users');
        if (allUsersResponse.ok) {
          const users = await allUsersResponse.json();
          // Use the first user as default for demo purposes
          return users[0] || { id: null, name: 'Unknown User' };
        }
        throw new Error('Failed to get current user');
      }
      return response.json();
    }
  });

  // Get all rocks
  const { data: allRocks = [], isLoading } = useQuery<any[]>({
    queryKey: ['/api/rocks', DEFAULT_COMPANY_ID],
    enabled: !!currentUser
  });

  // Get all users for reassignment
  const { data: users = [] } = useQuery<any[]>({
    queryKey: ['/api/users']
  });

  // Update rock mutation
  const updateRockMutation = useMutation({
    mutationFn: async ({ id, data }: any) => {
      return apiRequest(`/api/rocks/${id}`, 'PUT', data);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/rocks', DEFAULT_COMPANY_ID] });
      setEditingRock(null);
      toast({
        title: "Rock updated",
        description: "The rock has been successfully updated.",
      });
    }
  });

  // Filter rocks for current user
  const myRocks = allRocks.filter((rock: any) => 
    rock.assigneeId === currentUser?.id || rock.assigneeName === currentUser?.name
  );

  // Group rocks by quarter
  const rocksByQuarter = myRocks.reduce((acc: any, rock: any) => {
    const quarter = rock.quarter || 'Q1';
    if (!acc[quarter]) acc[quarter] = [];
    acc[quarter].push(rock);
    return acc;
  }, {});

  // Sort quarters and prioritize high priority rocks
  const quarters = ['Q1', 'Q2', 'Q3', 'Q4'];
  quarters.forEach(q => {
    if (rocksByQuarter[q]) {
      rocksByQuarter[q].sort((a: any, b: any) => {
        // Priority rocks first
        if (a.priority && !b.priority) return -1;
        if (!a.priority && b.priority) return 1;
        return 0;
      });
    }
  });

  // State for editing
  const [editingRock, setEditingRock] = useState<string | null>(null);
  const [editForm, setEditForm] = useState({
    text: "",
    quarter: "Q1",
    year: 2025,
    priority: false,
    assigneeId: ""
  });

  // State for quarter expansion
  const [expandedQuarters, setExpandedQuarters] = useState<{ [key: string]: boolean }>({
    Q1: true,
    Q2: true,
    Q3: true,
    Q4: true
  });

  // Handle rock editing
  const handleEditRock = (rock: any) => {
    setEditingRock(rock.id);
    setEditForm({
      text: rock.text || rock.title,
      quarter: rock.quarter || "Q1",
      year: rock.year || 2025,
      priority: rock.priority || false,
      assigneeId: rock.assigneeId || currentUser?.id || ""
    });
  };

  const handleSaveRock = () => {
    const assignee = users.find((u: any) => u.id === editForm.assigneeId);

    updateRockMutation.mutate({
      id: editingRock,
      data: {
        text: editForm.text,
        quarter: editForm.quarter,
        year: editForm.year,
        assigneeId: editForm.assigneeId,
        assigneeName: assignee?.name || null,
        priority: editForm.priority
      }
    });
  };

  const handleCancelEdit = () => {
    setEditingRock(null);
    setEditForm({ text: "", quarter: "Q1", year: 2025, priority: false, assigneeId: "" });
  };

  const toggleQuarter = (quarter: string) => {
    setExpandedQuarters(prev => ({
      ...prev,
      [quarter]: !prev[quarter]
    }));
  };

  if (isLoading) {
    return (
      <div className="flex justify-center items-center h-64">
        <div className="text-slate-500">Loading rocks...</div>
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6 max-w-7xl mx-auto">
      <Card className="bg-card/50 border-cyan-500/20">
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-xl text-cyan-300">
            <UserIcon className="w-6 h-6" />
            My Rocks - {currentUser?.name || 'Unknown User'}
          </CardTitle>
          <div className="text-sm text-slate-400">
            Total rocks assigned to you: {myRocks.length}
          </div>
        </CardHeader>
        <CardContent className="space-y-4">
          {quarters.map(quarter => {
            const quarterRocks = rocksByQuarter[quarter] || [];
            if (quarterRocks.length === 0) return null;

            return (
              <div key={quarter} className="border border-cyan-500/20 rounded-lg bg-slate-800/30">
                <div
                  className="flex items-center justify-between p-4 cursor-pointer hover:bg-cyan-500/5 transition-colors"
                  onClick={() => toggleQuarter(quarter)}
                >
                  <div className="flex items-center gap-3">
                    <FlameIcon className="w-5 h-5 text-cyan-400" />
                    <span className="font-semibold text-lg text-cyan-300">{quarter}</span>
                    <Badge className="bg-slate-700/50 text-slate-300">
                      {quarterRocks.length} rock{quarterRocks.length !== 1 ? 's' : ''}
                    </Badge>
                  </div>
                  {expandedQuarters[quarter] ? (
                    <ChevronDownIcon className="w-5 h-5 text-cyan-400" />
                  ) : (
                    <ChevronRightIcon className="w-5 h-5 text-cyan-400" />
                  )}
                </div>

                {expandedQuarters[quarter] && (
                  <div className="p-4 pt-0 space-y-3">
                    {quarterRocks.map((rock: any) => (
                      <div key={rock.id} className="bg-slate-700/30 rounded-lg p-4">
                        {editingRock === rock.id ? (
                          <div className="space-y-3">
                            <Input
                              value={editForm.text}
                              onChange={(e) => setEditForm({ ...editForm, text: e.target.value })}
                              placeholder="Rock description"
                              className="bg-slate-800/50 border-cyan-500/30 text-slate-300"
                              data-testid={`input-edit-rock-text-${rock.id}`}
                            />

                            <div className="grid grid-cols-2 gap-3">
                              <Select
                                value={editForm.quarter}
                                onValueChange={(value) => setEditForm({ ...editForm, quarter: value })}
                              >
                                <SelectTrigger className="bg-slate-800/50 border-cyan-500/30 text-slate-300" data-testid={`select-edit-rock-quarter-${rock.id}`}>
                                  <SelectValue placeholder="Quarter" />
                                </SelectTrigger>
                                <SelectContent>
                                  <SelectItem value="Q1">Q1</SelectItem>
                                  <SelectItem value="Q2">Q2</SelectItem>
                                  <SelectItem value="Q3">Q3</SelectItem>
                                  <SelectItem value="Q4">Q4</SelectItem>
                                </SelectContent>
                              </Select>

                              <Select
                                value={editForm.year.toString()}
                                onValueChange={(value) => setEditForm({ ...editForm, year: parseInt(value) })}
                              >
                                <SelectTrigger className="bg-slate-800/50 border-cyan-500/30 text-slate-300" data-testid={`select-edit-rock-year-${rock.id}`}>
                                  <SelectValue placeholder="Year" />
                                </SelectTrigger>
                                <SelectContent>
                                  <SelectItem value="2025">2025</SelectItem>
                                  <SelectItem value="2026">2026</SelectItem>
                                  <SelectItem value="2027">2027</SelectItem>
                                </SelectContent>
                              </Select>
                            </div>

                            <Select
                              value={editForm.assigneeId || "unassigned"}
                              onValueChange={(value) => setEditForm({ ...editForm, assigneeId: value === "unassigned" ? "" : value })}
                            >
                              <SelectTrigger className="bg-slate-800/50 border-cyan-500/30 text-slate-300" data-testid={`select-edit-rock-assignee-${rock.id}`}>
                                <SelectValue placeholder="Reassign to" />
                              </SelectTrigger>
                              <SelectContent>
                                <SelectItem value="unassigned">Unassigned</SelectItem>
                                {users.map((user: any) => (
                                  <SelectItem key={user.id} value={user.id}>
                                    {user.name || user.email}
                                  </SelectItem>
                                ))}
                              </SelectContent>
                            </Select>

                            <div className="flex items-center space-x-2">
                              <input
                                type="checkbox"
                                checked={editForm.priority}
                                onChange={(e) => setEditForm({ ...editForm, priority: e.target.checked })}
                                className="h-4 w-4 rounded border-input"
                                data-testid={`checkbox-edit-rock-priority-${rock.id}`}
                              />
                              <label className="text-sm text-slate-400">High Priority</label>
                            </div>

                            <div className="flex gap-2">
                              <Button
                                size="sm"
                                onClick={handleSaveRock}
                                className="bg-cyan-500/20 text-cyan-300 hover:bg-cyan-500/30"
                                data-testid={`button-save-rock-${rock.id}`}
                              >
                                <CheckIcon className="h-4 w-4 mr-1" />
                                Save
                              </Button>
                              <Button
                                size="sm"
                                variant="ghost"
                                onClick={handleCancelEdit}
                                className="text-red-400 hover:text-red-300"
                                data-testid={`button-cancel-edit-rock-${rock.id}`}
                              >
                                <XIcon className="h-4 w-4 mr-1" />
                                Cancel
                              </Button>
                            </div>
                          </div>
                        ) : (
                          <>
                            <div className="flex items-start justify-between">
                              <div className="flex-1">
                                <div className="flex items-center gap-2 mb-2">
                                  {rock.priority && (
                                    <Badge variant="destructive" className="text-xs">
                                      HIGH PRIORITY
                                    </Badge>
                                  )}
                                  <h4 className="text-slate-200 font-medium">{rock.text || rock.title}</h4>
                                </div>

                                {rock.capabilityTitle && (
                                  <div className="text-sm text-slate-400 mb-1">
                                    <span className="text-cyan-400">Capability:</span> {rock.capabilityTitle}
                                  </div>
                                )}

                                {rock.priorityTitle && (
                                  <div className="text-sm text-slate-400">
                                    <span className="text-cyan-400">Priority:</span> {rock.priorityTitle}
                                  </div>
                                )}
                              </div>

                              <ActionMenu
                                onEdit={() => handleEditRock(rock)}
                                onDelete={() => deleteRockMutation.mutate(rock.id)}
                                testId={`action-menu-rock-${rock.id}`}
                                className="text-cyan-400 hover:text-cyan-300"
                              />
                            </div>
                          </>
                        )}
                      </div>
                    ))}
                  </div>
                )}
              </div>
            );
          })}

          {myRocks.length === 0 && (
            <div className="text-center py-8">
              <p className="text-slate-500 text-lg">No rocks assigned to you yet.</p>
              <p className="text-slate-600 text-sm mt-2">Check back later or ask your manager to assign rocks to you.</p>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

