import type { Express, Request, Response } from "express";
import { createServer, type Server } from "http";
import { storage } from "./storage";
import { insertRoadmapSchema, insertRoadmapLayoutSchema, insertPrioritySchema, insertSwotSchema, insertRockSchema, insertMetricSchema, insertTeamMemberSchema, insertSubPrioritySchema, insertCompanySchema, insertUserSchema, insertJustGetItDoneItemSchema } from "@shared/schema";
import { validateEmailDomain, hashPassword, verifyPassword, generateToken, getUserFromToken } from "./auth";

export async function registerRoutes(app: Express): Promise<Server> {
  // Mock current company ID - In production this would come from session/auth
  const DEFAULT_COMPANY_ID = "default-company";

  // Authentication endpoints
  app.post("/api/auth/register", async (req, res) => {
    try {
      const { email, password, name, role = 'user' } = req.body;

      // Validate email domain
      if (!validateEmailDomain(email)) {
        return res.status(400).json({ 
          error: "Email must be from @smallgiantsonline.com domain" 
        });
      }

      // Check if user already exists
      const existingUser = await storage.getUserByEmail(email);
      if (existingUser) {
        return res.status(409).json({ error: "User with this email already exists" });
      }

      // Hash password and create user
      const hashedPassword = await hashPassword(password);
      const user = await storage.createUser({
        email,
        password: hashedPassword,
        name,
        role
      });

      // Generate token
      const token = generateToken(user);

      // Set token as HTTP-only cookie
      res.cookie('auth_token', token, {
        httpOnly: true,
        secure: process.env.NODE_ENV === 'production',
        sameSite: 'lax',
        maxAge: 7 * 24 * 60 * 60 * 1000 // 7 days
      });

      // Remove password from response
      const { password: _, ...userWithoutPassword } = user;

      res.json({ 
        success: true, 
        user: userWithoutPassword
      });
    } catch (error: any) {
      console.error("Registration error:", error);
      res.status(500).json({ error: error.message });
    }
  });

  app.post("/api/auth/login", async (req, res) => {
    try {
      const { email, password } = req.body;

      // Validate email domain
      if (!validateEmailDomain(email)) {
        return res.status(400).json({ 
          error: "Email must be from @smallgiantsonline.com domain" 
        });
      }

      // Find user
      const user = await storage.getUserByEmail(email);
      if (!user) {
        return res.status(401).json({ error: "Invalid email or password" });
      }

      // Verify password
      const isValidPassword = await verifyPassword(password, user.password);
      if (!isValidPassword) {
        return res.status(401).json({ error: "Invalid email or password" });
      }

      // Update last login
      await storage.updateUserLastLogin(user.id);

      // Generate token
      const token = generateToken(user);

      // Set token as HTTP-only cookie
      res.cookie('auth_token', token, {
        httpOnly: true,
        secure: process.env.NODE_ENV === 'production',
        sameSite: 'lax',
        maxAge: 7 * 24 * 60 * 60 * 1000 // 7 days
      });

      // Remove password from response
      const { password: _, ...userWithoutPassword } = user;

      res.json({ 
        success: true, 
        user: userWithoutPassword
      });
    } catch (error: any) {
      console.error("Login error:", error);
      res.status(500).json({ error: error.message });
    }
  });

  app.post("/api/auth/logout", async (req, res) => {
    // Clear the auth cookie
    res.clearCookie('auth_token');
    res.json({ success: true, message: "Logged out successfully" });
  });

  app.get("/api/auth/me", async (req, res) => {
    try {
      // Get token from cookie or authorization header
      let token = req.cookies?.auth_token;

      if (!token) {
        const authHeader = req.headers.authorization;
        if (authHeader && authHeader.startsWith('Bearer ')) {
          token = authHeader.substring(7);
        }
      }

      if (!token) {
        return res.status(401).json({ error: "No authentication token provided" });
      }

      const user = await getUserFromToken(token);

      if (!user) {
        return res.status(401).json({ error: "Invalid or expired token" });
      }

      // Remove password from response
      const { password: _, ...userWithoutPassword } = user;

      res.json({ success: true, user: userWithoutPassword });
    } catch (error: any) {
      console.error("Auth check error:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // Update user information
  app.put("/api/users/:userId", async (req, res) => {
    try {
      // Get token from cookie or authorization header
      let token = req.cookies?.auth_token;

      if (!token) {
        const authHeader = req.headers.authorization;
        if (authHeader && authHeader.startsWith('Bearer ')) {
          token = authHeader.substring(7);
        }
      }

      if (!token) {
        return res.status(401).json({ error: "No authentication token provided" });
      }

      const currentUser = await getUserFromToken(token);

      if (!currentUser) {
        return res.status(401).json({ error: "Invalid or expired token" });
      }

      const { userId } = req.params;

      // Users can only update their own information
      if (currentUser.id !== userId) {
        return res.status(403).json({ error: "You can only update your own information" });
      }

      const { name } = req.body;

      // Only allow updating name for now
      if (name !== undefined) {
        await storage.updateUser(userId, { name });
      }

      // Fetch updated user
      const updatedUser = await storage.getUser(userId);
      if (!updatedUser) {
        return res.status(404).json({ error: "User not found" });
      }

      // Remove password from response
      const { password: _, ...userWithoutPassword } = updatedUser;

      res.json({ success: true, user: userWithoutPassword });
    } catch (error: any) {
      console.error("Update user error:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // Admin endpoints
  app.get("/api/admin/users", async (req, res) => {
    try {
      const authHeader = req.headers.authorization;
      if (!authHeader || !authHeader.startsWith('Bearer ')) {
        return res.status(401).json({ error: "No authentication token provided" });
      }

      const token = authHeader.substring(7);
      const currentUser = await getUserFromToken(token);

      if (!currentUser) {
        return res.status(401).json({ error: "Invalid or expired token" });
      }

      // Check if user has admin privileges
      if (currentUser.role !== 'admin' && currentUser.role !== 'superadmin') {
        return res.status(403).json({ error: "Insufficient permissions" });
      }

      // Get all users
      const users = await storage.getUsers();

      // Remove passwords from response
      const sanitizedUsers = users.map(({ password, ...user }) => user);

      res.json(sanitizedUsers);
    } catch (error: any) {
      console.error("Get users error:", error);
      res.status(500).json({ error: error.message });
    }
  });

  app.put("/api/admin/users/:userId/role", async (req, res) => {
    try {
      const authHeader = req.headers.authorization;
      if (!authHeader || !authHeader.startsWith('Bearer ')) {
        return res.status(401).json({ error: "No authentication token provided" });
      }

      const token = authHeader.substring(7);
      const currentUser = await getUserFromToken(token);

      if (!currentUser) {
        return res.status(401).json({ error: "Invalid or expired token" });
      }

      const { userId } = req.params;
      const { role } = req.body;

      // Validate role
      if (!['superadmin', 'admin', 'user'].includes(role)) {
        return res.status(400).json({ error: "Invalid role" });
      }

      // Prevent users from changing their own role
      if (userId === currentUser.id) {
        return res.status(400).json({ error: "Cannot change your own role" });
      }

      // Check permissions
      const targetUser = await storage.getUser(userId);
      if (!targetUser) {
        return res.status(404).json({ error: "User not found" });
      }

      // Only superadmins can create/remove superadmins
      if ((role === 'superadmin' || targetUser.role === 'superadmin') && currentUser.role !== 'superadmin') {
        return res.status(403).json({ error: "Only superadmins can manage superadmin roles" });
      }

      // Admins can manage users and admins
      if (currentUser.role === 'admin' && role === 'superadmin') {
        return res.status(403).json({ error: "Insufficient permissions" });
      }

      // Update the role
      await storage.updateUserRole(userId, role);

      res.json({ success: true, message: "Role updated successfully" });
    } catch (error: any) {
      console.error("Update role error:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // Get all users for assignment dropdowns
  app.get("/api/users", async (req, res) => {
    try {
      const users = await storage.getUsers();
      // Return only necessary fields for assignment dropdowns
      const userList = users.map(user => ({
        id: user.id,
        name: user.name,
        email: user.email,
        role: user.role
      }));
      res.json(userList);
    } catch (error: any) {
      console.error("Get users error:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // Initialize default company if needed
  app.post("/api/init", async (req, res) => {
    try {
      let company = await storage.getCompany(DEFAULT_COMPANY_ID);
      if (!company) {
        // Create default company
        const companyData = {
          name: "Small Giants",
          createdBy: null
        };
        company = await storage.createCompany(companyData);
      }

      // Check if roadmap exists
      let roadmap = await storage.getRoadmapByCompany(company.id);
      if (!roadmap) {
        // Create default roadmap
        const roadmapData = {
          companyId: company.id,
          companyName: company.name,
          corePurpose: "Building Brand Worth - AEC/CRE Creative Solutions",
          brandPromise: "EXCELLENCE",
          bhag: "BUILDING BRAND WORTH ACROSS THE INDUSTRY"
        };
        roadmap = await storage.createRoadmap(roadmapData);
      }

      res.json({ success: true, company, roadmap });
    } catch (error: any) {
      console.error("Init error:", error);
      res.status(500).json({ error: error.message });
    }
  });

  // Roadmap routes
  app.get("/api/roadmap/:companyId", async (req, res) => {
    try {
      const roadmap = await storage.getRoadmapWithPriorities(req.params.companyId || DEFAULT_COMPANY_ID);
      res.json(roadmap);
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  app.put("/api/roadmap/:companyId", async (req, res) => {
    try {
      const data = insertRoadmapSchema.partial().parse(req.body);
      await storage.updateRoadmapByCompany(req.params.companyId, data);
      res.json({ success: true });
    } catch (error: any) {
      res.status(400).json({ error: error.message });
    }
  });

  // Roadmap Layout routes
  app.get("/api/roadmap-layout/:companyId", async (req, res) => {
    try {
      const layout = await storage.getRoadmapLayoutByCompany(req.params.companyId);
      if (!layout) {
        // Return default empty layout if none exists
        res.json({ 
          companyId: req.params.companyId,
          sectionLayouts: {
            foundation: [],
            threeYear: [],
            oneYear: []
          }
        });
      } else {
        res.json(layout);
      }
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  app.put("/api/roadmap-layout/:companyId", async (req, res) => {
    try {
      const data = insertRoadmapLayoutSchema.partial().parse(req.body);
      const layout = await storage.upsertRoadmapLayout(req.params.companyId, data);
      res.json(layout);
    } catch (error: any) {
      res.status(400).json({ error: error.message });
    }
  });

  // Priority routes (includes capabilities)
  app.get("/api/priorities/:companyId", async (req, res) => {
    try {
      const type = req.query.type as string | undefined;
      const priorities = await storage.getPrioritiesByCompany(req.params.companyId || DEFAULT_COMPANY_ID, type);

      // Fetch sub-priorities and rocks for each priority
      const prioritiesWithDetails = await Promise.all(priorities.map(async (priority) => {
        const subPriorities = await storage.getSubPrioritiesByPriority(priority.id);
        const rocks = await storage.getRocksByPriority(priority.id);
        return { ...priority, subPriorities, rocks };
      }));

      res.json(prioritiesWithDetails);
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  app.post("/api/priorities", async (req, res) => {
    try {
      const data = insertPrioritySchema.parse({ ...req.body, companyId: req.body.companyId || DEFAULT_COMPANY_ID });
      const priority = await storage.createPriority(data);
      res.json(priority);
    } catch (error: any) {
      res.status(400).json({ error: error.message });
    }
  });

  app.put("/api/priorities/:id", async (req, res) => {
    try {
      const data = insertPrioritySchema.partial().parse(req.body);
      await storage.updatePriority(req.params.id, data);
      res.json({ success: true });
    } catch (error: any) {
      res.status(400).json({ error: error.message });
    }
  });

  app.put("/api/priorities/order/batch", async (req, res) => {
    try {
      const updates = req.body.updates as {id: string, displayOrder: number}[];
      await storage.updatePrioritiesOrder(updates);
      res.json({ success: true });
    } catch (error: any) {
      res.status(400).json({ error: error.message });
    }
  });

  app.delete("/api/priorities/:id", async (req, res) => {
    try {
      await storage.deletePriority(req.params.id);
      res.json({ success: true });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // Sub-priority routes
  app.post("/api/sub-priorities", async (req, res) => {
    try {
      const data = insertSubPrioritySchema.parse(req.body);
      const subPriority = await storage.createSubPriority(data);
      res.json(subPriority);
    } catch (error: any) {
      res.status(400).json({ error: error.message });
    }
  });

  app.put("/api/sub-priorities/:id", async (req, res) => {
    try {
      await storage.updateSubPriority(req.params.id, req.body.completed);
      res.json({ success: true });
    } catch (error: any) {
      res.status(400).json({ error: error.message });
    }
  });

  app.delete("/api/sub-priorities/:id", async (req, res) => {
    try {
      await storage.deleteSubPriority(req.params.id);
      res.json({ success: true });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // SWOT routes
  app.get("/api/swot/:companyId", async (req, res) => {
    try {
      const swot = await storage.getSwotByCompany(req.params.companyId || DEFAULT_COMPANY_ID);
      res.json(swot);
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  app.post("/api/swot", async (req, res) => {
    try {
      const data = insertSwotSchema.parse({ ...req.body, companyId: req.body.companyId || DEFAULT_COMPANY_ID });
      const swot = await storage.createSwot(data);
      res.json(swot);
    } catch (error: any) {
      res.status(400).json({ error: error.message });
    }
  });

  app.put("/api/swot/:id", async (req, res) => {
    try {
      const data = insertSwotSchema.partial().parse(req.body);
      await storage.updateSwot(req.params.id, data);
      res.json({ success: true });
    } catch (error: any) {
      res.status(400).json({ error: error.message });
    }
  });

  // Just Get It Done routes
  app.get("/api/just-get-it-done/:companyId", async (req, res) => {
    try {
      const items = await storage.getJustGetItDoneItemsByCompany(req.params.companyId || DEFAULT_COMPANY_ID);
      res.json(items);
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  app.post("/api/just-get-it-done", async (req, res) => {
    try {
      const data = insertJustGetItDoneItemSchema.parse({ 
        ...req.body, 
        companyId: req.body.companyId || DEFAULT_COMPANY_ID 
      });
      const item = await storage.createJustGetItDoneItem(data);
      res.json(item);
    } catch (error: any) {
      res.status(400).json({ error: error.message });
    }
  });

  app.put("/api/just-get-it-done/:id", async (req, res) => {
    try {
      const data = insertJustGetItDoneItemSchema.partial().parse(req.body);
      await storage.updateJustGetItDoneItem(req.params.id, data);
      res.json({ success: true });
    } catch (error: any) {
      res.status(400).json({ error: error.message });
    }
  });

  app.delete("/api/just-get-it-done/:id", async (req, res) => {
    try {
      await storage.deleteJustGetItDoneItem(req.params.id);
      res.json({ success: true });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // Rock routes
  app.get("/api/rocks", async (req, res) => {
    try {
      const { companyId, priorityId, assigneeId } = req.query;

      let rocks;
      if (priorityId) {
        rocks = await storage.getRocksByPriority(priorityId as string);
      } else if (assigneeId) {
        rocks = await storage.getRocksByAssignee(assigneeId as string);
      } else {
        rocks = await storage.getRocksByCompany(companyId as string || DEFAULT_COMPANY_ID);
      }

      res.json(rocks);
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  app.get("/api/rocks/rollup/:companyId", async (req, res) => {
    try {
      const rollup = await storage.getRocksRollup(req.params.companyId || DEFAULT_COMPANY_ID);
      res.json(rollup);
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  app.post("/api/rocks", async (req, res) => {
    try {
      const data = insertRockSchema.parse({ 
        ...req.body, 
        companyId: req.body.companyId || DEFAULT_COMPANY_ID,
        year: req.body.year || new Date().getFullYear()
      });
      const rock = await storage.createRock(data);
      res.json(rock);
    } catch (error: any) {
      res.status(400).json({ error: error.message });
    }
  });

  app.put("/api/rocks/:id", async (req, res) => {
    try {
      const data = insertRockSchema.partial().parse(req.body);
      await storage.updateRock(req.params.id, data);
      res.json({ success: true });
    } catch (error: any) {
      res.status(400).json({ error: error.message });
    }
  });

  app.delete("/api/rocks/:id", async (req, res) => {
    try {
      await storage.deleteRock(req.params.id);
      res.json({ success: true });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // Metric routes
  app.get("/api/metrics/:companyId", async (req, res) => {
    try {
      const metrics = await storage.getMetricsByCompany(req.params.companyId || DEFAULT_COMPANY_ID);
      res.json(metrics);
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  app.post("/api/metrics", async (req, res) => {
    try {
      const data = insertMetricSchema.parse({ ...req.body, companyId: req.body.companyId || DEFAULT_COMPANY_ID });
      const metric = await storage.createMetric(data);
      res.json(metric);
    } catch (error: any) {
      res.status(400).json({ error: error.message });
    }
  });

  app.put("/api/metrics/:id", async (req, res) => {
    try {
      const data = insertMetricSchema.partial().parse(req.body);
      await storage.updateMetric(req.params.id, data);
      res.json({ success: true });
    } catch (error: any) {
      res.status(400).json({ error: error.message });
    }
  });

  app.delete("/api/metrics/:id", async (req, res) => {
    try {
      await storage.deleteMetric(req.params.id);
      res.json({ success: true });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // Team Member routes
  app.get("/api/team-members/:companyId", async (req, res) => {
    try {
      const members = await storage.getTeamMembersByCompany(req.params.companyId || DEFAULT_COMPANY_ID);
      res.json(members);
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  app.post("/api/team-members", async (req, res) => {
    try {
      const data = insertTeamMemberSchema.parse({ ...req.body, companyId: req.body.companyId || DEFAULT_COMPANY_ID });
      const member = await storage.createTeamMember(data);
      res.json(member);
    } catch (error: any) {
      res.status(400).json({ error: error.message });
    }
  });

  app.put("/api/team-members/:id", async (req, res) => {
    try {
      const data = insertTeamMemberSchema.partial().parse(req.body);
      await storage.updateTeamMember(req.params.id, data);
      res.json({ success: true });
    } catch (error: any) {
      res.status(400).json({ error: error.message });
    }
  });

  app.delete("/api/team-members/:id", async (req, res) => {
    try {
      await storage.deleteTeamMember(req.params.id);
      res.json({ success: true });
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // Agile Growth Checklist routes (multi-user)

  // Get user-specific checklist items
  app.get("/api/agile-checklist/:companyId/user/:userId", async (req, res) => {
    try {
      const checklist = await storage.getChecklistItemsByUser(
        req.params.companyId || DEFAULT_COMPANY_ID,
        req.params.userId
      );
      res.json(checklist);
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // Get all checklist items for a company (all users)
  app.get("/api/agile-checklist/:companyId", async (req, res) => {
    try {
      const checklist = await storage.getChecklistItemsByCompany(req.params.companyId || DEFAULT_COMPANY_ID);
      res.json(checklist);
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // Get averaged scores by category for a company
  app.get("/api/agile-checklist/:companyId/averages", async (req, res) => {
    try {
      const averages = await storage.getChecklistAveragesByCompany(req.params.companyId || DEFAULT_COMPANY_ID);
      res.json(averages);
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // Get overall average for a company
  app.get("/api/agile-checklist/:companyId/overall-average", async (req, res) => {
    try {
      const overall = await storage.getChecklistOverallAverage(req.params.companyId || DEFAULT_COMPANY_ID);
      res.json(overall);
    } catch (error: any) {
      res.status(500).json({ error: error.message });
    }
  });

  // Initialize checklist for a specific user
  app.post("/api/agile-checklist/initialize", async (req, res) => {
    try {
      const { companyId, userId, items } = req.body;

      if (!userId) {
        return res.status(400).json({ error: "userId is required" });
      }

      if (!items || !Array.isArray(items)) {
        return res.status(400).json({ error: "items array is required" });
      }

      await storage.bulkInitializeChecklistForUser(companyId || DEFAULT_COMPANY_ID, userId, items);
      res.json({ success: true });
    } catch (error: any) {
      res.status(400).json({ error: error.message });
    }
  });

  // Update checklist item for a specific user
  app.put("/api/agile-checklist/:companyId/:itemId", async (req, res) => {
    try {
      const { score, userId } = req.body;
      if (!userId) {
        return res.status(400).json({ error: "userId is required" });
      }
      if (score && (score < 1 || score > 5)) {
        return res.status(400).json({ error: "score must be between 1 and 5" });
      }
      await storage.updateChecklistItem(
        req.params.companyId || DEFAULT_COMPANY_ID,
        userId,
        req.params.itemId,
        score
      );
      res.json({ success: true });
    } catch (error: any) {
      res.status(400).json({ error: error.message });
    }
  });

  const httpServer = createServer(app);

  return httpServer;
}

