          // Only include rocks that are linked to priorities (not capabilities)
          if (rock.priorityType === 'priority') {
            quarterlyRocks[quarter].push({
              id: rock.id,
              text: rock.text,
              assignee: rock.assigneeName || 'Unassigned',
              priorityTitle: rock.priorityTitle
            });
          }
        });
