    brandPromise: roadmap?.brandPromise || "CONFIDENCE",
    brandPromises: [
      "24/7 Support Guarantee",
      "99.9% Uptime SLA",
      "30-Day Money Back"
    ],
    xFactor: "Proprietary AI that reduces costs by 50%",
    coreCustomer: roadmap?.coreCustomer || "Q1-Q2 Clients -Private TI, Office/flex/warehouse ground-up, Regional investors, Public works/CMAR/JOC, Healthcare/assisted living, Aviation, Mission critical, Education, Higher Education, Hospitality, Retail, Infrastructure for automotive/proving grounds.",
    targets3to5: {
      revenue: "$50M ARR",
      profit: "20% EBITDA",
      cashDays: "45 days",
      other: "500+ Enterprise Customers"
    },
    targets1Year: {
      revenue: "$15M ARR",
      profit: "10% EBITDA", 
      cashDays: "60 days",
      other: "150 Enterprise Customers"
    },
    quarterlyTheme: {
      name: "Operation Scale",
      criticalNumbers: [
        { name: "Customer Acquisition", target: "50 new", actual: "42" },
        { name: "Churn Rate", target: "<2%", actual: "1.8%" },
        { name: "NPS Score", target: ">70", actual: "68" }
      ],
      rocks: [
        { name: "Launch v2.0", owner: "John D.", status: "on-track" },
        { name: "Hire 10 Engineers", owner: "Sarah M.", status: "at-risk" },
        { name: "ISO Certification", owner: "Mike R.", status: "completed" }
      ]
    },
    coreProcesses: [
      { name: "Sales Process", documented: true, followed: 85 },
      { name: "Onboarding", documented: true, followed: 92 },
      { name: "Product Development", documented: false, followed: 70 },
