  const getScoreColor = (score: number, max: number = 5) => {
    const percent = (score / max) * 100;
    if (percent >= 80) return 'bg-emerald-500';
    if (percent >= 60) return 'bg-blue-500';
    if (percent >= 40) return 'bg-amber-500';
    return 'bg-rose-500';
