          <CardHeader>
            <CardTitle className="text-cyan-300 text-sm">7 Attributes of Agile Growth®</CardTitle>
          </CardHeader>
          <CardContent className="space-y-2">
            {displayData.sevenAttributes.map((attr: any, idx: number) => (
              <div key={idx} className="flex items-center justify-between">
                <span className="text-xs text-slate-200">{attr.name}</span>
                <div className="flex items-center gap-2">
                  <div className="flex gap-1">
                    {[1,2,3,4,5].map(i => (
                      <div 
                        key={i} 
                        className={`w-2 h-2 rounded-full ${
                          i <= attr.score ? getScoreColor(attr.score) : 'bg-slate-700'
                        }`} 
                      />
                    ))}
                  </div>
                  <span className="text-xs text-cyan-400 w-8 text-right">{attr.score}/5</span>
                </div>
              </div>
            ))}
          </CardContent>
        </Card>

        <Card className="bg-card/50 border-cyan-500/20 backdrop-blur-sm">
          <CardHeader>
            <CardTitle className="text-cyan-300 text-sm">5 Dysfunctions of a Team</CardTitle>
          </CardHeader>
          <CardContent className="space-y-2">
            {displayData.fiveDysfunctions.map((item: any, idx: number) => (
              <div key={idx} className="flex items-center justify-between">
                <span className="text-xs text-slate-200">{item.name}</span>
                <div className="flex items-center gap-2">
                  <div className="w-24 h-2 bg-slate-700 rounded-full overflow-hidden">
                    <div 
                      className={`h-full ${getScoreColor(item.score, 10)}`}
                      style={{ width: `${item.score * 10}%` }}
                    />
                  </div>
                  <span className="text-xs text-cyan-400 w-8 text-right">{item.score}/10</span>
                </div>
              </div>
            ))}
          </CardContent>
        </Card>
      </div>

      {/* Footer Notes */}
      <div className="mt-8 p-4 bg-slate-800/30 rounded-lg border border-cyan-500/10">
        <p className="text-xs text-cyan-400/60 text-center">
          One-Page Strategic Plan (OPSP) - 7 Attributes of Agile Growth® Framework
        </p>
        <p className="text-xs text-cyan-400/40 text-center mt-1">
          This is a comprehensive rollup view of all strategic planning components
        </p>
      </div>
    </div>
  );
}

