client/src/components/PersonalDevelopmen.content:
import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { BookOpenIcon, VideoIcon, AwardIcon, SparklesIcon, PlusIcon, XIcon } from "lucide-react";

interface LearningItem {
  id: string;
  title: string;
  type: 'book' | 'video' | 'course';
  completed: boolean;
}

interface DevelopmentItem {
  id: string;
  title: string;
  type: 'skill' | 'habit' | 'experience';
  progress: number;
}

interface PersonalDevelopmentProps {
  learning: LearningItem[];
  development: DevelopmentItem[];
  onLearningUpdate: (items: LearningItem[]) => void;
  onDevelopmentUpdate: (items: DevelopmentItem[]) => void;
}

export default function PersonalDevelopment({ 
  learning, 
  development, 
  onLearningUpdate, 
  onDevelopmentUpdate 
}: PersonalDevelopmentProps) {
  const [newLearningTitle, setNewLearningTitle] = useState("");
  const [newLearningType, setNewLearningType] = useState<LearningItem['type']>('book');
  const [newDevTitle, setNewDevTitle] = useState("");
  const [newDevType, setNewDevType] = useState<DevelopmentItem['type']>('skill');

  const addLearning = () => {
    if (!newLearningTitle.trim()) return;
    const newItem: LearningItem = {
      id: `l_${Date.now()}`,
      title: newLearningTitle,
      type: newLearningType,
      completed: false
    };
    onLearningUpdate([...learning, newItem]);
    setNewLearningTitle("");
  };

  const toggleLearning = (id: string) => {
    onLearningUpdate(
      learning.map(item => 
        item.id === id ? { ...item, completed: !item.completed } : item
      )
    );
  };

  const removeLearning = (id: string) => {
    onLearningUpdate(learning.filter(item => item.id !== id));
  };

  const addDevelopment = () => {
    if (!newDevTitle.trim()) return;
    const newItem: DevelopmentItem = {
      id: `d_${Date.now()}`,
      title: newDevTitle,
      type: newDevType,
      progress: 0
    };
    onDevelopmentUpdate([...development, newItem]);
    setNewDevTitle("");
  };

  const updateProgress = (id: string, progress: number) => {
    onDevelopmentUpdate(
      development.map(item => 
        item.id === id ? { ...item, progress } : item
      )
    );
  };

  const removeDevelopment = (id: string) => {
    onDevelopmentUpdate(development.filter(item => item.id !== id));
  };

  const getTypeIcon = (type: LearningItem['type']) => {
    switch (type) {
      case 'book': return <BookOpenIcon className="w-3 h-3" />;
      case 'video': return <VideoIcon className="w-3 h-3" />;
      case 'course': return <AwardIcon className="w-3 h-3" />;
    }
  };

  const getDevTypeColor = (type: DevelopmentItem['type']) => {
    switch (type) {
      case 'skill': return 'bg-purple-500/20 text-purple-300 border-purple-500/30';
      case 'habit': return 'bg-green-500/20 text-green-300 border-green-500/30';
      case 'experience': return 'bg-orange-500/20 text-orange-300 border-orange-500/30';
    }
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
      {/* Personal Learning */}
      <Card className="bg-card/50 border-cyan-500/20 backdrop-blur-sm hover:border-cyan-400/40 transition-all duration-300">
        <CardHeader>
          <CardTitle className="text-cyan-300 flex items-center gap-2">
            <SparklesIcon className="w-5 h-5 text-cyan-400" />
            Personal Learning
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2">
            {learning.map((item) => (
              <div 
                key={item.id} 
                className="flex items-center gap-2 p-2 bg-background/30 rounded-lg border border-cyan-500/10 hover:border-cyan-500/30 transition-all"
              >
                <input
                  type="checkbox"
                  checked={item.completed}
                  onChange={() => toggleLearning(item.id)}
                  className="rounded border-cyan-500/30 bg-background/50"
                  data-testid={`checkbox-learning-${item.id}`}
                />
                <div className="flex items-center gap-1 text-cyan-400">
                  {getTypeIcon(item.type)}
                </div>
                <span className={`flex-1 text-sm ${
                  item.completed ? 'line-through text-cyan-300/40' : 'text-cyan-100'
                }`}>
                  {item.title}
                </span>
                <Button
                  size="sm"
                  variant="ghost"
                  onClick={() => removeLearning(item.id)}
                  className="h-6 w-6 p-0 text-cyan-400/60 hover:text-cyan-300"
                  data-testid={`button-remove-learning-${item.id}`}
                >
                  <XIcon className="w-3 h-3" />
                </Button>
              </div>
            ))}
          </div>

          <div className="flex gap-2">
            <Input
              value={newLearningTitle}
              onChange={(e) => setNewLearningTitle(e.target.value)}
              placeholder="Add learning item"
              className="flex-1 bg-background/50 border-cyan-500/30 text-cyan-100 placeholder:text-cyan-300/30"
              onKeyDown={(e) => e.key === 'Enter' && addLearning()}
              data-testid="input-new-learning"
            />
            <select
              value={newLearningType}
              onChange={(e) => setNewLearningType(e.target.value as LearningItem['type'])}
              className="px-3 py-2 bg-background/50 border border-cyan-500/30 text-cyan-100 rounded-md"
              data-testid="select-learning-type"
            >
              <option value="book">Book</option>
              <option value="video">Video</option>
              <option value="course">Course</option>
            </select>
            <Button
              onClick={addLearning}
              size="sm"
              className="bg-cyan-500/20 hover:bg-cyan-500/30 text-cyan-300 border border-cyan-500/30"
              data-testid="button-add-learning"
            >
              <PlusIcon className="w-4 h-4" />
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* Personal Development */}
      <Card className="bg-card/50 border-cyan-500/20 backdrop-blur-sm hover:border-cyan-400/40 transition-all duration-300">
        <CardHeader>
          <CardTitle className="text-cyan-300 flex items-center gap-2">
            <AwardIcon className="w-5 h-5 text-cyan-400" />
            Personal Development
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-3">
            {development.map((item) => (
              <div 
                key={item.id} 
                className="space-y-2 p-3 bg-background/30 rounded-lg border border-cyan-500/10 hover:border-cyan-500/30 transition-all"
              >
                <div className="flex items-center justify-between">
                  <span className="text-sm text-cyan-100">{item.title}</span>
                  <div className="flex items-center gap-2">
                    <Badge className={getDevTypeColor(item.type)}>
                      {item.type}
                    </Badge>
                    <Button
                      size="sm"
                      variant="ghost"
                      onClick={() => removeDevelopment(item.id)}
                      className="h-6 w-6 p-0 text-cyan-400/60 hover:text-cyan-300"
                      data-testid={`button-remove-dev-${item.id}`}
                    >
                      <XIcon className="w-3 h-3" />
                    </Button>
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  <input
                    type="range"
                    value={item.progress}
                    onChange={(e) => updateProgress(item.id, Number(e.target.value))}
                    min="0"
                    max="100"
                    className="flex-1"
                    data-testid={`slider-progress-${item.id}`}
                  />
                  <span className="text-xs text-cyan-400 w-10 text-right">
                    {item.progress}%
                  </span>
                </div>
                <div className="h-1 bg-background/50 rounded-full overflow-hidden">
                  <div 
                    className="h-full bg-gradient-to-r from-cyan-500 to-blue-500 transition-all duration-300"
                    style={{ width: `${item.progress}%` }}
                  />
                </div>
              </div>
            ))}
          </div>

          <div className="flex gap-2">
            <Input
              value={newDevTitle}
              onChange={(e) => setNewDevTitle(e.target.value)}
              placeholder="Add development goal"
              className="flex-1 bg-background/50 border-cyan-500/30 text-cyan-100 placeholder:text-cyan-300/30"
              onKeyDown={(e) => e.key === 'Enter' && addDevelopment()}
              data-testid="input-new-development"
            />
            <select
              value={newDevType}
              onChange={(e) => setNewDevType(e.target.value as DevelopmentItem['type'])}
              className="px-3 py-2 bg-background/50 border border-cyan-500/30 text-cyan-100 rounded-md"
              data-testid="select-dev-type"
            >
              <option value="skill">Skill</option>
              <option value="habit">Habit</option>
              <option value="experience">Experience</option>
            </select>
            <Button
              onClick={addDevelopment}
              size="sm"
              className="bg-cyan-500/20 hover:bg-cyan-500/30 text-cyan-300 border border-cyan-500/30"
              data-testid="button-add-development"
            >
              <PlusIcon className="w-4 h-4" />
            </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

