import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { PlusIcon, XIcon, GripVerticalIcon } from "lucide-react";
import { ActionMenu } from "@/components/ui/ActionMenu";

interface SwotItem {
  id: string;
  text: string;
}

interface SwotData {
  strengths: SwotItem[];
  weaknesses: SwotItem[];
  opportunities: SwotItem[];
  threats: SwotItem[];
}

interface SwotMatrixProps {
  data: SwotData;
  onUpdate: (data: SwotData) => void;
}

export default function SwotMatrix({ data, onUpdate }: SwotMatrixProps) {
  const [editingSection, setEditingSection] = useState<keyof SwotData | null>(null);
  const [newItemText, setNewItemText] = useState("");
  const [confirmAdd, setConfirmAdd] = useState(false);

  const addItem = (section: keyof SwotData) => {
    if (!newItemText.trim() || !confirmAdd) return;

    const newItem: SwotItem = {
      id: `${section}_${Date.now()}`,
      text: newItemText.trim()
    };

    const updatedData = {
      ...data,
      [section]: [...data[section], newItem]
    };

    onUpdate(updatedData);
    setNewItemText("");
    setConfirmAdd(false);
    setEditingSection(null);
  };

  const removeItem = (section: keyof SwotData, itemId: string) => {
    const updatedData = {
      ...data,
      [section]: data[section].filter(item => item.id !== itemId)
    };
    onUpdate(updatedData);
  };

  const getSectionConfig = (section: keyof SwotData) => {
    const configs = {
      strengths: { 
        title: "Strengths", 
        color: "bg-emerald-500/10 border-emerald-500/30 backdrop-blur-sm",
        badgeColor: "bg-emerald-500/20 text-emerald-300 border-emerald-500/30"
      },
      weaknesses: { 
        title: "Weaknesses", 
        color: "bg-rose-500/10 border-rose-500/30 backdrop-blur-sm",
        badgeColor: "bg-rose-500/20 text-rose-300 border-rose-500/30"
      },
      opportunities: { 
        title: "Opportunities", 
        color: "bg-blue-500/10 border-blue-500/30 backdrop-blur-sm",
        badgeColor: "bg-blue-500/20 text-blue-300 border-blue-500/30"
      },
      threats: { 
        title: "Threats", 
        color: "bg-amber-500/10 border-amber-500/30 backdrop-blur-sm",
        badgeColor: "bg-amber-500/20 text-amber-300 border-amber-500/30"
      }
    };
    return configs[section];
  };

  const renderSection = (section: keyof SwotData) => {
    const config = getSectionConfig(section);
    const items = data[section];

    return (
      <Card className={`${config.color} hover:border-opacity-50 transition-all duration-300`} data-testid={`card-swot-${section}`}>
        <CardHeader className="pb-3">
          <div className="flex items-center justify-between">
            <CardTitle className="text-lg text-cyan-300">{config.title}</CardTitle>
            <Badge className={config.badgeColor}>
              {items.length}
            </Badge>
          </div>
        </CardHeader>

        <CardContent className="space-y-2">
          {items.map((item) => (
            <div 
              key={item.id} 
              className="flex items-center gap-2 p-2 bg-slate-800/50 rounded-md hover:bg-slate-800/70 transition-all"
            >
              <GripVerticalIcon className="w-4 h-4 text-slate-500 cursor-move" />
              <span className="flex-1 text-sm text-slate-200">{item.text}</span>
              <Button
                size="sm"
                variant="ghost"
                onClick={() => removeItem(section, item.id)}
                className="h-6 w-6 p-0 text-slate-400 hover:text-rose-400"
                data-testid={`button-remove-${section}-${item.id}`}
              >
                <XIcon className="w-3 h-3" />
              </Button>
            </div>
          ))}

          {editingSection === section ? (
            <div className="space-y-2 mt-3">
              <div className="flex gap-2">
                <Input
                  value={newItemText}
                  onChange={(e) => setNewItemText(e.target.value)}
                  placeholder={`Add ${section.slice(0, -1)}`}
                  className="flex-1 bg-slate-800/50 border-slate-700/30 text-slate-200 placeholder:text-slate-500"
                  onKeyDown={(e) => e.key === 'Enter' && confirmAdd && addItem(section)}
                  data-testid={`input-new-${section}`}
                />
                <Button
                  size="sm"
                  onClick={() => addItem(section)}
                  disabled={!confirmAdd || !newItemText.trim()}
                  data-testid={`button-add-${section}`}
                >
                  <PlusIcon className="w-4 h-4" />
                </Button>
                <Button
                  size="sm"
                  variant="ghost"
                  onClick={() => {
                    setEditingSection(null);
                    setNewItemText("");
                    setConfirmAdd(false);
                  }}
                  data-testid={`button-cancel-${section}`}
                >
                  <XIcon className="w-4 h-4" />
                </Button>
              </div>
              <div className="flex items-center gap-2">
                <input
                  type="checkbox"
                  id={`confirm-${section}`}
                  checked={confirmAdd}
                  onChange={(e) => setConfirmAdd(e.target.checked)}
                  className="rounded border-cyan-500/30 bg-slate-800/50 text-cyan-400 focus:ring-cyan-400/50"
                  data-testid={`checkbox-confirm-${section}`}
                />
                <label htmlFor={`confirm-${section}`} className="text-xs text-cyan-400/80">
                  Confirm to add this item
                </label>
              </div>
            </div>
          ) : (
            <Button
              variant="outline"
              size="sm"
              onClick={() => setEditingSection(section)}
              className="w-full mt-3 text-cyan-400 border-cyan-500/30 hover:bg-cyan-500/10"
              data-testid={`button-edit-${section}`}
            >
              <PlusIcon className="w-4 h-4 mr-2" />
              Add {config.title.slice(0, -1)}
            </Button>
          )}
        </CardContent>
      </Card>
    );
  };

  return (
    <div className="w-full max-w-6xl mx-auto space-y-6">
      <div className="text-center">
        <h2 className="text-2xl font-bold text-cyan-300 mb-2">SWOT Analysis</h2>
        <p className="text-cyan-400/60">
          Analyze your organization's internal strengths and weaknesses, and external opportunities and threats
        </p>
        <ActionMenu
          onEdit={() => window.dispatchEvent(new CustomEvent('navigate', { detail: 'canvas' }))}
          onDelete={() => {}} // This button doesn't have delete functionality
          editLabel="Edit SWOT on Canvas"
          deleteLabel="Delete"
          testId="action-menu-swot-canvas"
          className="mt-4 border-cyan-500/30 text-cyan-400 hover:bg-cyan-500/10"
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {renderSection('strengths')}
        {renderSection('weaknesses')}
        {renderSection('opportunities')}
        {renderSection('threats')}
      </div>
    </div>
  );
}

