import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from "recharts";
import { TrendingUpIcon, TrendingDownIcon, PlusIcon, TargetIcon, PencilIcon, TrashIcon, CheckIcon, XIcon } from "lucide-react";

interface MetricDataPoint {
  date: string;
  value: number;
}

interface Metric {
  id: string;
  name: string;
  unit: string;
  currentValue: number;
  targetValue: number;
  data: MetricDataPoint[];
  trend: 'up' | 'down' | 'stable';
}

interface MetricsDashboardProps {
  metrics: Metric[];
  onMetricUpdate: (metric: Metric) => void;
  onAddMetric: (metric: Omit<Metric, 'id'>) => void;
  onDeleteMetric?: (metricId: string) => void;
}

export default function MetricsDashboard({ metrics, onMetricUpdate, onAddMetric, onDeleteMetric }: MetricsDashboardProps) {
  const [showAddForm, setShowAddForm] = useState(false);
  const [editingMetricId, setEditingMetricId] = useState<string | null>(null);
  const [editForm, setEditForm] = useState<Metric | null>(null);
  const [newMetric, setNewMetric] = useState({
    name: "",
    unit: "",
    currentValue: 0,
    targetValue: 0,
    data: [] as MetricDataPoint[],
    trend: 'stable' as const
  });

  const getProgressPercentage = (current: number, target: number) => {
    if (target === 0) return 0;
    return Math.min((current / target) * 100, 100);
  };

  const getTrendIcon = (trend: Metric['trend']) => {
    switch (trend) {
      case 'up': return <TrendingUpIcon className="w-4 h-4 text-green-600" />;
      case 'down': return <TrendingDownIcon className="w-4 h-4 text-red-600" />;
      default: return <div className="w-4 h-4" />;
    }
  };

  const getTrendColor = (trend: Metric['trend']) => {
    switch (trend) {
      case 'up': return 'text-green-600';
      case 'down': return 'text-red-600';
      default: return 'text-muted-foreground';
    }
  };

  const handleAddMetric = () => {
    if (!newMetric.name.trim()) return;
    onAddMetric(newMetric);
    setNewMetric({
      name: "",
      unit: "",
      currentValue: 0,
      targetValue: 0,
      data: [],
      trend: 'stable'
    });
    setShowAddForm(false);
  };

  const handleEditMetric = (metric: Metric) => {
    setEditingMetricId(metric.id);
    setEditForm({ ...metric });
  };

  const handleSaveEdit = () => {
    if (editForm) {
      onMetricUpdate(editForm);
      setEditingMetricId(null);
      setEditForm(null);
    }
  };

  const handleCancelEdit = () => {
    setEditingMetricId(null);
    setEditForm(null);
  };

  const handleDeleteMetric = (metricId: string) => {
    if (onDeleteMetric) {
      onDeleteMetric(metricId);
    }
  };

  return (
    <div className="w-full max-w-7xl mx-auto space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-foreground">KPI Dashboard</h2>
          <p className="text-muted-foreground">Monitor your key performance indicators</p>
        </div>
        <Button 
          onClick={() => setShowAddForm(true)}
          data-testid="button-add-metric"
        >
          <PlusIcon className="w-4 h-4 mr-2" />
          Add KPI
        </Button>
      </div>

      {showAddForm && (
        <Card className="border-2 border-dashed border-border">
          <CardHeader>
            <CardTitle>Add New KPI</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <Input
                placeholder="Metric name"
                value={newMetric.name}
                onChange={(e) => setNewMetric(prev => ({ ...prev, name: e.target.value }))}
                data-testid="input-new-metric-name"
              />
              <Input
                placeholder="Unit (e.g., $, %, users)"
                value={newMetric.unit}
                onChange={(e) => setNewMetric(prev => ({ ...prev, unit: e.target.value }))}
                data-testid="input-new-metric-unit"
              />
              <Input
                type="number"
                placeholder="Current value"
                value={newMetric.currentValue || ""}
                onChange={(e) => setNewMetric(prev => ({ ...prev, currentValue: Number(e.target.value) }))}
                data-testid="input-new-metric-current"
              />
              <Input
                type="number"
                placeholder="Target value"
                value={newMetric.targetValue || ""}
                onChange={(e) => setNewMetric(prev => ({ ...prev, targetValue: Number(e.target.value) }))}
                data-testid="input-new-metric-target"
              />
            </div>
            <div className="flex gap-2">
              <Button onClick={handleAddMetric} data-testid="button-save-new-metric">
                Save KPI
              </Button>
              <Button 
                variant="outline" 
                onClick={() => setShowAddForm(false)}
                data-testid="button-cancel-new-metric"
              >
                Cancel
              </Button>
            </div>
          </CardContent>
        </Card>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {metrics.map((metric) => (
          <Card key={metric.id} className="hover-elevate" data-testid={`card-metric-${metric.id}`}>
            <CardHeader className="pb-3">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  {editingMetricId === metric.id ? (
                    <Input
                      value={editForm?.name || ""}
                      onChange={(e) => setEditForm(prev => prev ? {...prev, name: e.target.value} : null)}
                      className="h-7 text-base font-semibold"
                      data-testid={`input-edit-metric-name-${metric.id}`}
                    />
                  ) : (
                    <CardTitle className="text-base">{metric.name}</CardTitle>
                  )}
                </div>
                <div className="flex items-center gap-1">
                  {editingMetricId === metric.id ? (
                    <>
                      <Button
                        size="icon"
                        variant="ghost"
                        onClick={handleSaveEdit}
                        className="h-6 w-6 text-green-500"
                        data-testid={`button-save-metric-${metric.id}`}
                      >
                        <CheckIcon className="h-3 w-3" />
                      </Button>
                      <Button
                        size="icon"
                        variant="ghost"
                        onClick={handleCancelEdit}
                        className="h-6 w-6 text-red-500"
                        data-testid={`button-cancel-metric-${metric.id}`}
                      >
                        <XIcon className="h-3 w-3" />
                      </Button>
                    </>
                  ) : (
                    <>
                      <Button
                        size="icon"
                        variant="ghost"
                        onClick={() => handleEditMetric(metric)}
                        className="h-6 w-6 opacity-0 group-hover:opacity-100 transition-opacity"
                        data-testid={`button-edit-metric-${metric.id}`}
                      >
                        <PencilIcon className="h-3 w-3" />
                      </Button>
                      <Button
                        size="icon"
                        variant="ghost"
                        onClick={() => handleDeleteMetric(metric.id)}
                        className="h-6 w-6 opacity-0 group-hover:opacity-100 transition-opacity text-red-500"
                        data-testid={`button-delete-metric-${metric.id}`}
                      >
                        <TrashIcon className="h-3 w-3" />
                      </Button>
                      {getTrendIcon(metric.trend)}
                    </>
                  )}
                </div>
              </div>
            </CardHeader>

            <CardContent className="space-y-4">
              <div className="space-y-2">
                <div className="flex items-end gap-2">
                  {editingMetricId === metric.id ? (
                    <>
                      <Input
                        type="number"
                        value={editForm?.currentValue || ""}
                        onChange={(e) => setEditForm(prev => prev ? {...prev, currentValue: Number(e.target.value)} : null)}
                        className="w-32 h-8 text-2xl font-bold"
                        data-testid={`input-edit-metric-current-${metric.id}`}
                      />
                      <Input
                        value={editForm?.unit || ""}
                        onChange={(e) => setEditForm(prev => prev ? {...prev, unit: e.target.value} : null)}
                        className="w-16 h-6 text-sm"
                        placeholder="unit"
                        data-testid={`input-edit-metric-unit-${metric.id}`}
                      />
                    </>
                  ) : (
                    <>
                      <span className="text-2xl font-bold text-foreground">
                        {metric.currentValue.toLocaleString()}
                      </span>
                      <span className="text-sm text-muted-foreground">{metric.unit}</span>
                    </>
                  )}
                </div>

                <div className="flex items-center justify-between text-sm">
                  <div className="flex items-center gap-1">
                    <TargetIcon className="w-3 h-3 text-muted-foreground" />
                    <span className="text-muted-foreground">Target:</span>
                    {editingMetricId === metric.id ? (
                      <Input
                        type="number"
                        value={editForm?.targetValue || ""}
                        onChange={(e) => setEditForm(prev => prev ? {...prev, targetValue: Number(e.target.value)} : null)}
                        className="w-24 h-5 text-sm"
                        data-testid={`input-edit-metric-target-${metric.id}`}
                      />
                    ) : (
                      <span>{metric.targetValue.toLocaleString()}{metric.unit}</span>
                    )}
                  </div>
                  <Badge variant="outline" className={getTrendColor(metric.trend)}>
                    {getProgressPercentage(
                      editingMetricId === metric.id ? editForm?.currentValue || 0 : metric.currentValue,
                      editingMetricId === metric.id ? editForm?.targetValue || 1 : metric.targetValue
                    ).toFixed(0)}%
                  </Badge>
                </div>

                <div className="w-full bg-muted rounded-full h-2">
                  <div 
                    className={`h-2 rounded-full transition-all ${
                      getProgressPercentage(metric.currentValue, metric.targetValue) >= 100 
                        ? 'bg-green-500' 
                        : getProgressPercentage(metric.currentValue, metric.targetValue) >= 75 
                        ? 'bg-blue-500' 
                        : 'bg-yellow-500'
                    }`}
                    style={{ 
                      width: `${Math.min(getProgressPercentage(metric.currentValue, metric.targetValue), 100)}%` 
                    }}
                  />
                </div>
              </div>

              {metric.data.length > 0 && (
                <div className="h-24">
                  <ResponsiveContainer width="100%" height="100%">
                    <LineChart data={metric.data}>
                      <Line 
                        type="monotone" 
                        dataKey="value" 
                        stroke="hsl(var(--chart-2))" 
                        strokeWidth={2}
                        dot={false}
                      />
                      <XAxis dataKey="date" hide />
                      <YAxis hide />
                      <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" />
                      <Tooltip 
                        labelFormatter={(value) => `Date: ${value}`}
                        formatter={(value: number) => [`${value.toLocaleString()}${metric.unit}`, metric.name]}
                      />
                    </LineChart>
                  </ResponsiveContainer>
                </div>
              )}
            </CardContent>
          </Card>
        ))}
      </div>
    </div>
  );
}

client/src/components/NavigationSidebar..content:
import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { useToast } from "@/hooks/use-toast";
import { 
  HomeIcon, 
  TargetIcon, 
  BarChart3Icon, 
  ClipboardListIcon, 
  TrendingUpIcon,
  FileTextIcon,
  SettingsIcon,
  HelpCircleIcon,
  ChevronLeftIcon,
  ChevronRightIcon,
  UserIcon,
  ActivityIcon,
  BookOpenIcon,
  BuildingIcon,
  CalendarIcon,
  Clock3Icon,
  ShieldIcon,
  MailIcon,
  CopyIcon
} from "lucide-react";

interface NavigationItem {
  id: string;
  label: string;
  icon: React.ReactNode;
  count?: number;
  active?: boolean;
  disabled?: boolean;
}

interface NavigationSidebarProps {
  currentUser?: {
    name: string;
    email: string;
    avatar?: string;
    role: string;
  };
  onNavigate: (itemId: string) => void;
}

export default function NavigationSidebar({ currentUser, onNavigate }: NavigationSidebarProps) {
  const [isCollapsed, setIsCollapsed] = useState(false);
  const [activeItem, setActiveItem] = useState('canvas');
  const [showHelpDialog, setShowHelpDialog] = useState(false);
  const { toast } = useToast();

  const supportEmail = "brennan@smallgiantsonline.com";

  const handleCopyEmail = () => {
    navigator.clipboard.writeText(supportEmail);
    toast({
      title: "Email copied",
      description: "Email address copied to clipboard.",
    });
  };

  const navigationItems: NavigationItem[] = [
    {
      id: 'canvas',
      label: 'Roadmap Canvas',
      icon: <HomeIcon className="w-4 h-4" />,
      active: activeItem === 'canvas'
    },
    {
      id: 'foundation',
      label: 'Foundation',
      icon: <BuildingIcon className="w-4 h-4" />,
      active: activeItem === 'foundation'
    },
    {
      id: 'three-year',
      label: 'Three Year',
      icon: <CalendarIcon className="w-4 h-4" />,
      active: activeItem === 'three-year'
    },
    {
      id: 'one-year',
      label: 'One Year',
      icon: <Clock3Icon className="w-4 h-4" />,
      active: activeItem === 'one-year'
    },
    {
      id: 'priority-management',
      label: 'Priority Management',
      icon: <SettingsIcon className="w-4 h-4" />,
      active: activeItem === 'priority-management'
    },
    {
      id: 'swot',
      label: 'SWOT Analysis',
      icon: <TrendingUpIcon className="w-4 h-4" />,
      active: activeItem === 'swot'
    },
    {
      id: 'just-get-it-done',
      label: 'Just Get It Done',
      icon: <ClipboardListIcon className="w-4 h-4" />,
      active: activeItem === 'just-get-it-done'
    },
    {
      id: 'metrics',
      label: 'KPI Dashboard',
      icon: <BarChart3Icon className="w-4 h-4" />,
      count: 8,
      active: activeItem === 'metrics'
    }
  ];

  const secondaryItems: NavigationItem[] = [
    {
      id: 'assessments',
      label: 'Agile Growth Checklist',
      icon: <ClipboardListIcon className="w-4 h-4" />,
      active: activeItem === 'assessments'
    },
    {
      id: 'rocks',
      label: 'My Rocks',
      icon: <TargetIcon className="w-4 h-4" />,
      active: activeItem === 'rocks',
      disabled: true
    },
    {
      id: 'personal',
      label: 'Personal Development',
      icon: <BookOpenIcon className="w-4 h-4" />,
      active: activeItem === 'personal',
      disabled: true
    },
    // Add admin panel for admin users
    ...(currentUser && (currentUser.role === 'admin' || currentUser.role === 'superadmin') ? [{
      id: 'admin',
      label: 'Admin Panel',
      icon: <ShieldIcon className="w-4 h-4" />,
      active: activeItem === 'admin'
    }] : [])
  ];

  const handleItemClick = (itemId: string) => {
    setActiveItem(itemId);
    onNavigate(itemId);
  };

  return (
    <div className={`h-screen bg-slate-900/90 border-r border-cyan-500/20 flex flex-col transition-all duration-300 backdrop-blur-xl ${
      isCollapsed ? 'w-16' : 'w-64'
    }`}>
      {/* Header */}
      <div className="p-4 border-b border-cyan-500/20">
        <div className="flex items-center justify-between">
          {!isCollapsed && (
            <div className="flex-1">
              <h1 className="text-lg font-bold text-cyan-300">Scalability Roadmap</h1>
              <p className="text-xs text-cyan-400/60">Strategic Planning Tool</p>
            </div>
          )}
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setIsCollapsed(!isCollapsed)}
            className="text-cyan-400 hover:bg-cyan-500/10"
            data-testid="button-toggle-sidebar"
          >
            {isCollapsed ? (
              <ChevronRightIcon className="w-4 h-4" />
            ) : (
              <ChevronLeftIcon className="w-4 h-4" />
            )}
          </Button>
        </div>
      </div>

      {/* Navigation Items */}
      <div className="flex-1 p-2 space-y-1">
        {navigationItems.map((item) => (
          <Button
            key={item.id}
            variant={item.active ? "default" : "ghost"}
            size="sm"
            onClick={() => handleItemClick(item.id)}
            className={`w-full justify-start gap-3 transition-all ${
              item.active 
                ? 'bg-cyan-500/20 text-cyan-300 border-l-2 border-cyan-400' 
                : 'text-cyan-400/70 hover:bg-cyan-500/10 hover:text-cyan-300 border-l-2 border-transparent'
            }`}
            data-testid={`nav-item-${item.id}`}
          >
            {item.icon}
            {!isCollapsed && (
              <>
                <span className="flex-1 text-left">{item.label}</span>
                {item.count && (
                  <Badge className="ml-auto bg-cyan-500/20 text-cyan-300 border-cyan-500/30">
                    {item.count}
                  </Badge>
                )}
              </>
            )}
          </Button>
        ))}

        {/* Separator line */}
        <div className="my-2 border-t border-cyan-500/20"></div>

        {/* Secondary Items */}
        {secondaryItems.map((item) => {
          const buttonContent = (
            <Button
              key={item.id}
              variant={item.active ? "default" : "ghost"}
              size="sm"
              onClick={() => !item.disabled && handleItemClick(item.id)}
              disabled={item.disabled}
              className={`w-full justify-start gap-3 transition-all ${
                item.disabled
                  ? 'opacity-40 cursor-not-allowed text-cyan-400/40 border-l-2 border-transparent'
                  : item.active 
                    ? 'bg-cyan-500/20 text-cyan-300 border-l-2 border-cyan-400' 
                    : 'text-cyan-400/70 hover:bg-cyan-500/10 hover:text-cyan-300 border-l-2 border-transparent'
              }`}
              data-testid={`nav-item-${item.id}`}
            >
              {item.icon}
              {!isCollapsed && (
                <>
                  <span className="flex-1 text-left">{item.label}</span>
                  {item.count && (
                    <Badge className="ml-auto bg-cyan-500/20 text-cyan-300 border-cyan-500/30">
                      {item.count}
                    </Badge>
                  )}
                </>
              )}
            </Button>
          );

          if (item.disabled) {
            return (
              <Tooltip key={item.id}>
                <TooltipTrigger asChild>
                  {buttonContent}
                </TooltipTrigger>
                <TooltipContent side="right">
                  <p>Coming soon</p>
                </TooltipContent>
              </Tooltip>
            );
          }

          return buttonContent;
        })}
      </div>

      {/* Settings Section */}
      <div className="p-2 space-y-1 border-t border-cyan-500/20">
        <Button
          variant="ghost"
          size="sm"
          onClick={() => handleItemClick('settings')}
          className="w-full justify-start gap-3 text-cyan-400/70 hover:bg-cyan-500/10 hover:text-cyan-300"
          data-testid="nav-item-settings"
        >
          <SettingsIcon className="w-4 h-4" />
          {!isCollapsed && <span>Settings</span>}
        </Button>

        <Button
          variant="ghost"
          size="sm"
          onClick={() => setShowHelpDialog(true)}
          className="w-full justify-start gap-3 text-cyan-400/70 hover:bg-cyan-500/10 hover:text-cyan-300"
          data-testid="nav-item-help"
        >
          <HelpCircleIcon className="w-4 h-4" />
          {!isCollapsed && <span>Help & Support</span>}
        </Button>
      </div>

      {/* User Profile */}
      {currentUser && (
        <div className="p-4 border-t border-cyan-500/20">
          <div className={`flex items-center gap-3 ${isCollapsed ? 'justify-center' : ''}`}>
            <Avatar className="h-8 w-8">
              <AvatarImage src={currentUser.avatar} alt={currentUser.name} />
              <AvatarFallback>
                <UserIcon className="h-4 w-4" />
              </AvatarFallback>
            </Avatar>
            {!isCollapsed && (
              <div className="flex-1 min-w-0">
                <p className="text-sm font-medium text-cyan-300 truncate">
                  {currentUser.name}
                </p>
                <p className="text-xs text-cyan-400/60 truncate">
                  {currentUser.role}
                </p>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Help & Support Dialog */}
      <Dialog open={showHelpDialog} onOpenChange={setShowHelpDialog}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <HelpCircleIcon className="h-5 w-5" />
              Help & Support
            </DialogTitle>
            <DialogDescription>
              Need assistance? Reach out to us via email.
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div className="flex items-center gap-3 p-4 bg-muted rounded-lg">
              <MailIcon className="h-5 w-5 text-muted-foreground" />
              <div className="flex-1">
                <p className="text-sm font-medium">Email Address</p>
                <p className="text-lg font-mono text-primary">{supportEmail}</p>
              </div>
            </div>
            <div className="flex gap-2">
              <Button
                onClick={handleCopyEmail}
                variant="outline"
                className="flex-1"
              >
                <CopyIcon className="h-4 w-4 mr-2" />
                Copy Email
              </Button>
              <Button
                onClick={() => window.location.href = `mailto:${supportEmail}`}
                className="flex-1"
              >
                <MailIcon className="h-4 w-4 mr-2" />
                Open Email
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

