import { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useQuery, useMutation } from "@tanstack/react-query";
import { queryClient, apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import { 
  CalendarIcon,
  TrendingUpIcon,
  DollarSignIcon,
  TargetIcon,
  BarChartIcon,
  FlameIcon,
  PlusIcon,
  PencilIcon,
  XIcon,
  CheckIcon,
  TrashIcon,
  ChevronDownIcon,
  ChevronRightIcon,
  ZapIcon,
  ActivityIcon
} from "lucide-react";
import { ActionMenu } from "@/components/ui/ActionMenu";

export default function OneYear() {
  const { toast } = useToast();
  const DEFAULT_COMPANY_ID = "200c32ef-28fe-4fa7-995d-96386671e89e";

  // Fetch roadmap data
  const { data: roadmapFromDB, isLoading: roadmapLoading } = useQuery({
    queryKey: ['/api/roadmap', DEFAULT_COMPANY_ID],
    queryFn: async () => {
      const response = await fetch(`/api/roadmap/${DEFAULT_COMPANY_ID}`);
      if (!response.ok) throw new Error('Failed to fetch roadmap');
      return response.json();
    }
  });

  // Fetch priorities (annual priorities) - same as Priority Management
  const { data: priorities = [], isLoading: prioritiesLoading } = useQuery({
    queryKey: ['/api/priorities', DEFAULT_COMPANY_ID],
    queryFn: async () => {
      const response = await fetch(`/api/priorities/${DEFAULT_COMPANY_ID}`);
      if (!response.ok) throw new Error('Failed to fetch priorities');
      return response.json();
    }
  });

  // Fetch users for rock editing
  const { data: users = [] } = useQuery({
    queryKey: ['/api/users'],
    queryFn: async () => {
      const response = await fetch('/api/users');
      if (!response.ok) throw new Error('Failed to fetch users');
      return response.json();
    }
  });

  // One Year data state
  const [oneYearData, setOneYearData] = useState<{
    onePhraseStrategy: string;
    oneYearGoals: {
      revenue: { label: string; value: string; };
      grossProfit: { label: string; value: string; };
      netProfit: { label: string; value: string; };
      cash: { label: string; value: string; };
      nps: { label: string; value: string; };
      enps: { label: string; value: string; };
      bptw: { label: string; value: string; };
      emr: { label: string; value: string; };
      bhag: { label: string; value: string; };
      gainFade: { label: string; value: string; };
      entryExit: { label: string; value: string; };
    };
    criticalNumbers: {
      profitPerX: { label: string; value: string; };
      nps: { label: string; value: string; };
      enps: { label: string; value: string; };
      laborEfficiencyRatio: { label: string; value: string; };
      builderProtectorRatio: { label: string; value: string; };
    };
  }>({
    onePhraseStrategy: "",
    oneYearGoals: {
      revenue: { label: "Revenue", value: "" },
      grossProfit: { label: "Gross Profit", value: "" },
      netProfit: { label: "Net Profit", value: "" },
      cash: { label: "Cash", value: "" },
      nps: { label: "NPS", value: "" },
      enps: { label: "eNPS", value: "" },
      bptw: { label: "BPTW", value: "" },
      emr: { label: "EMR", value: "" },
      bhag: { label: "BHAG", value: "" },
      gainFade: { label: "Gain/Fade", value: "" },
      entryExit: { label: "Entry/Exit", value: "" }
    },
    criticalNumbers: {
      profitPerX: { label: "Profit per X", value: "" },
      nps: { label: "NPS", value: "" },
      enps: { label: "eNPS", value: "" },
      laborEfficiencyRatio: { label: "Labor Efficiency Ratio", value: "" },
      builderProtectorRatio: { label: "Builder Protector Ratio", value: "" }
    }
  });

  // State for managing editing
  const [editingField, setEditingField] = useState<string | null>(null);
  const [editValue, setEditValue] = useState("");

  // State for rock management - same as Priority Management
  const [expandedPriority, setExpandedPriority] = useState<string | null>(null);
  const [addingRockTo, setAddingRockTo] = useState<string | null>(null);
  const [newRockForm, setNewRockForm] = useState({ text: "", assigneeId: "", assigneeName: "", quarter: "Q1", year: 2025, priority: false });
  const [editingRock, setEditingRock] = useState<string | null>(null);
  const [editRockForm, setEditRockForm] = useState({ text: "", assigneeId: "", assigneeName: "", quarter: "Q1", year: 2025, priority: false });

  // Update local state when database data is fetched
  useEffect(() => {
    if (roadmapFromDB && roadmapFromDB.roadmap) {
      const roadmap = roadmapFromDB.roadmap;
      setOneYearData(prev => {
        // Parse oneYearGoal JSON if it exists
        let parsedGoals = prev.oneYearGoals;
        if (roadmap.oneYearGoal) {
          try {
            const goalData = JSON.parse(roadmap.oneYearGoal);
            parsedGoals = { ...prev.oneYearGoals, ...goalData };
          } catch (e) {
            console.warn('Failed to parse oneYearGoal JSON:', e);
          }
        }

        return {
          ...prev,
          onePhraseStrategy: roadmap.onePhraseStrategy || "",
          oneYearGoals: parsedGoals,
          criticalNumbers: (roadmap.criticalNumbers && typeof roadmap.criticalNumbers === 'object') 
            ? { ...prev.criticalNumbers, ...roadmap.criticalNumbers } 
            : prev.criticalNumbers
        };
      });
    }
  }, [roadmapFromDB]);

  // Mutation to update roadmap data
  const updateRoadmapMutation = useMutation({
    mutationFn: async (data: any) => {
      return apiRequest(`/api/roadmap/${DEFAULT_COMPANY_ID}`, 'PUT', data);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/roadmap', DEFAULT_COMPANY_ID] });
      toast({
        title: "Success",
        description: "Goals have been saved",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: "Failed to save goals",
        variant: "destructive"
      });
    }
  });

  // Create rock mutation - same as Priority Management
  const createRockMutation = useMutation({
    mutationFn: async (data: any) => {
      return apiRequest('/api/rocks', 'POST', data);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/priorities', DEFAULT_COMPANY_ID] });
      queryClient.invalidateQueries({ queryKey: ['/api/rocks', DEFAULT_COMPANY_ID] });
      queryClient.invalidateQueries({ queryKey: ['/api/rocks/rollup', DEFAULT_COMPANY_ID] });
      setAddingRockTo(null);
      setNewRockForm({ text: "", assigneeId: "", assigneeName: "", quarter: "Q1", year: 2025, priority: false });
      toast({
        title: "Rock created",
        description: "The rock has been successfully created.",
      });
    }
  });

  // Update rock mutation - same as Priority Management
  const updateRockMutation = useMutation({
    mutationFn: async ({ id, data }: any) => {
      return apiRequest(`/api/rocks/${id}`, 'PUT', data);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/priorities', DEFAULT_COMPANY_ID] });
      queryClient.invalidateQueries({ queryKey: ['/api/rocks', DEFAULT_COMPANY_ID] });
      queryClient.invalidateQueries({ queryKey: ['/api/rocks/rollup', DEFAULT_COMPANY_ID] });
      setEditingRock(null);
      setEditRockForm({ text: "", assigneeId: "", assigneeName: "", quarter: "Q1", year: 2025, priority: false });
      toast({
        title: "Rock updated",
        description: "The rock has been successfully updated.",
      });
    }
  });

  // Delete rock mutation - same as Priority Management
  const deleteRockMutation = useMutation({
    mutationFn: async (id: string) => {
      return apiRequest(`/api/rocks/${id}`, 'DELETE');
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/priorities', DEFAULT_COMPANY_ID] });
      queryClient.invalidateQueries({ queryKey: ['/api/rocks', DEFAULT_COMPANY_ID] });
      queryClient.invalidateQueries({ queryKey: ['/api/rocks/rollup', DEFAULT_COMPANY_ID] });
      toast({
        title: "Rock deleted",
        description: "The rock has been successfully deleted.",
      });
    }
  });

  // Handle simple field editing
  const handleEdit = (fieldPath: string, currentValue: string) => {
    setEditingField(fieldPath);
    setEditValue(currentValue);
  };

  const handleSave = (fieldPath: string) => {
    // Normalize field path to match actual state structure (camelCase)
    let normalizedPath = fieldPath;
    if (fieldPath.startsWith('oneyeargoals.')) {
      normalizedPath = 'oneYearGoals.' + fieldPath.substring('oneyeargoals.'.length);
    } else if (fieldPath.startsWith('criticalnumbers.')) {
      normalizedPath = 'criticalNumbers.' + fieldPath.substring('criticalnumbers.'.length);
    }

    // Update state and capture the new data
    setOneYearData(prev => {
      let newData: any;

      if (normalizedPath.includes('.')) {
        // Handle nested objects like oneYearGoals.revenue.value
        const pathParts = normalizedPath.split('.');
        newData = JSON.parse(JSON.stringify(prev)); // Deep clone to avoid mutations
        let current: any = newData;

        for (let i = 0; i < pathParts.length - 1; i++) {
          if (!current[pathParts[i]] || typeof current[pathParts[i]] !== 'object') {
            current[pathParts[i]] = {};
          } else {
            // Clone the nested object to avoid mutations
            current[pathParts[i]] = { ...current[pathParts[i]] };
          }
          current = current[pathParts[i]];
        }

        current[pathParts[pathParts.length - 1]] = editValue;
      } else {
        newData = {
          ...prev,
          [normalizedPath]: editValue
        };
      }

      // Save to database
      const dataToSave: any = {};

      if (normalizedPath === 'onePhraseStrategy') {
        dataToSave.onePhraseStrategy = editValue;
      } else if (normalizedPath.startsWith('oneYearGoals.')) {
        // Save the entire oneYearGoals object as JSON
        dataToSave.oneYearGoal = JSON.stringify(newData.oneYearGoals);
      } else if (normalizedPath.startsWith('criticalNumbers.')) {
        // Save critical numbers
        dataToSave.criticalNumbers = JSON.stringify(newData.criticalNumbers);
      }

      if (Object.keys(dataToSave).length > 0) {
        updateRoadmapMutation.mutate(dataToSave, {
          onSuccess: () => {
            toast({
              title: "Saved",
              description: "Goals have been saved successfully",
            });
          }
        });
      }

      return newData;
    });

    setEditingField(null);
    setEditValue("");
  };

  const handleCancel = () => {
    setEditingField(null);
    setEditValue("");
  };

  // Rock management handlers - same as Priority Management
  const handleAddRock = (priorityId: string) => {
    if (!newRockForm.text.trim()) {
      toast({
        title: "Error",
        description: "Rock text is required",
        variant: "destructive"
      });
      return;
    }

    const assignee = users.find((u: any) => u.id === newRockForm.assigneeId);

    createRockMutation.mutate({
      companyId: DEFAULT_COMPANY_ID,
      priorityId: priorityId,
      text: newRockForm.text,
      quarter: newRockForm.quarter,
      year: newRockForm.year,
      assigneeId: newRockForm.assigneeId || null,
      assigneeName: assignee?.name || null,
      status: 'not_started',
      priority: newRockForm.priority
    });
  };

  const handleEditRock = (rock: any) => {
    setEditingRock(rock.id);
    setEditRockForm({
      text: rock.text,
      assigneeId: rock.assigneeId || "",
      assigneeName: rock.assigneeName || "",
      quarter: rock.quarter || "Q1",
      year: rock.year || 2025,
      priority: rock.priority || false
    });
  };

  const handleSaveRock = () => {
    const assignee = users.find((u: any) => u.id === editRockForm.assigneeId);

    updateRockMutation.mutate({
      id: editingRock,
      data: {
        text: editRockForm.text,
        quarter: editRockForm.quarter,
        year: editRockForm.year,
        assigneeId: editRockForm.assigneeId || null,
        assigneeName: assignee?.name || null,
        priority: editRockForm.priority
      }
    });
  };

  const handleCancelRockEdit = () => {
    setEditingRock(null);
    setEditRockForm({ text: "", assigneeId: "", assigneeName: "", quarter: "Q1", year: 2025, priority: false });
  };

  // Render editable field
  const renderEditableField = (fieldPath: string, value: string, multiline = false) => {
    const isEditing = editingField === fieldPath;

    const handleKeyDown = (e: React.KeyboardEvent) => {
      if (e.key === 'Enter' && !multiline) {
        e.preventDefault();
        handleSave(fieldPath);
      }
    };

    if (isEditing) {
      return (
        <div className="flex gap-2 items-start">
          {multiline ? (
            <Textarea
              value={editValue}
              onChange={(e) => setEditValue(e.target.value)}
              className="flex-1 bg-slate-800/50 border-cyan-500/30 text-slate-300"
              autoFocus
              rows={3}
            />
          ) : (
            <Input
              value={editValue}
              onChange={(e) => setEditValue(e.target.value)}
              onKeyDown={handleKeyDown}
              className="flex-1 bg-slate-800/50 border-cyan-500/30 text-slate-300"
              autoFocus
            />
          )}
          <Button
            size="icon"
            variant="ghost"
            onClick={() => handleSave(fieldPath)}
            className="h-8 w-8 text-green-400 hover:text-green-300"
            data-testid={`button-save-${fieldPath}`}
          >
            <CheckIcon className="h-4 w-4" />
          </Button>
          <Button
            size="icon"
            variant="ghost"
            onClick={handleCancel}
            className="h-8 w-8 text-red-400 hover:text-red-300"
            data-testid={`button-cancel-${fieldPath}`}
          >
            <XIcon className="h-4 w-4" />
          </Button>
        </div>
      );
    }

    return (
      <div className="flex gap-2 items-start group">
        <p className={`flex-1 ${multiline ? 'text-sm leading-relaxed' : 'text-lg font-medium'} text-slate-300`}>
          {value || "-"}
        </p>
        <Button
          size="icon"
          variant="ghost"
          onClick={() => handleEdit(fieldPath, value)}
          className="h-6 w-6 text-cyan-400 hover:text-cyan-300 opacity-0 group-hover:opacity-100 transition-opacity"
          data-testid={`button-edit-${fieldPath}`}
        >
          <PencilIcon className="h-3 w-3" />
        </Button>
      </div>
    );
  };

  // Render metric grid
  const renderMetricGrid = (metrics: any, title: string, columns = 3) => {
    if (!metrics || typeof metrics !== 'object') {
      return <div className="text-center text-slate-400">No metrics data available</div>;
    }

    const metricEntries = Object.entries(metrics);

    return (
      <div className={`grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-${columns} gap-4`}>
        {metricEntries.map(([key, metric]: [string, any]) => {
          if (!metric || typeof metric !== 'object') {
            return null;
          }
          return (
            <div key={key} className="border border-cyan-500/20 rounded-lg p-4 bg-slate-800/30 hover:bg-slate-800/40 transition-colors">
              <div className="text-center">
                <h4 className="text-cyan-300 text-sm font-medium mb-2">{metric.label || key}</h4>
                {renderEditableField(`${title.toLowerCase().replace(' ', '')}.${key}.value`, metric.value || "")}
              </div>
            </div>
          );
        })}
      </div>
    );
  };

  // Group rocks by quarter
  const groupRocksByQuarter = (rocks: any[]) => {
    const grouped: { [key: string]: any[] } = { Q1: [], Q2: [], Q3: [], Q4: [] };
    rocks.forEach((rock) => {
      const quarter = rock.quarter || 'Q1';
      if (grouped[quarter]) {
        grouped[quarter].push(rock);
      }
    });
    return grouped;
  };

  // Filter annual priorities
  const annualPriorities = priorities.filter((p: any) => p.type === 'priority');

  if (roadmapLoading || prioritiesLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-center">
          <CalendarIcon className="w-8 h-8 animate-pulse text-cyan-400 mx-auto mb-2" />
          <p className="text-cyan-400/60">Loading one year data...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Page Header */}
      <div className="border-b border-cyan-500/20 pb-4">
        <div className="flex items-center gap-3 mb-2">
          <CalendarIcon className="w-6 h-6 text-cyan-400" />
          <h1 className="text-2xl font-bold text-cyan-300">One Year</h1>
        </div>
        <p className="text-sm text-cyan-400/60">
          Define your one-year strategy, goals, priorities, and quarterly execution plan
        </p>
      </div>

      {/* One Year Cards */}
      <div className="grid grid-cols-1 gap-6">
        {/* One Phrase Strategy */}
        <Card className="bg-card/50 border-cyan-500/20">
          <CardHeader className="pb-3">
            <CardTitle className="flex items-center gap-2 text-lg text-cyan-300">
              <ZapIcon className="w-5 h-5" />
              One Phrase Strategy
            </CardTitle>
          </CardHeader>
          <CardContent>
            {renderEditableField("onePhraseStrategy", oneYearData.onePhraseStrategy, true)}
          </CardContent>
        </Card>

        {/* One Year Goals */}
        <Card className="bg-card/50 border-cyan-500/20">
          <CardHeader className="pb-3">
            <CardTitle className="flex items-center gap-2 text-lg text-cyan-300">
              <TargetIcon className="w-5 h-5" />
              One Year Goals
            </CardTitle>
          </CardHeader>
          <CardContent>
            {renderMetricGrid(oneYearData.oneYearGoals, "oneYearGoals", 3)}
          </CardContent>
        </Card>

        {/* Annual Priorities with Quarterly Rocks - using same structure as Priority Management */}
        <Card className="bg-card/50 border-cyan-500/20">
          <CardHeader className="pb-3">
            <CardTitle className="flex items-center gap-2 text-lg text-cyan-300">
              <TrendingUpIcon className="w-5 h-5" />
              Annual Priorities
              <Badge className="ml-auto bg-cyan-500/20 text-cyan-300 border-cyan-500/30">
                {annualPriorities.length}
              </Badge>
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              {annualPriorities.length === 0 ? (
                <div className="text-slate-400 text-sm py-4 text-center">
                  No annual priorities added yet. Add priorities from the Priority Management page.
                </div>
              ) : (
                annualPriorities.map((priority: any, idx: number) => {
                  const rocksByQuarter = groupRocksByQuarter(priority.rocks || []);
                  const totalRocks = (priority.rocks || []).length;

                  return (
                    <div key={priority.id} className="group border border-cyan-500/20 rounded-lg p-3 bg-slate-800/30">
                      <div className="flex items-start justify-between mb-3">
                        <div className="flex-1">
                          <div className="flex items-center gap-2 mb-1">
                            <span className="text-cyan-400/60 font-medium">{idx + 1}:</span>
                            <h4 className="font-medium text-cyan-300">{priority.title}</h4>
                            <Badge variant="secondary" className="text-xs">
                              Priority
                            </Badge>
                          </div>
                          {priority.description && (
                            <p className="text-sm text-slate-400 mb-2">{priority.description}</p>
                          )}
                          <div className="flex items-center gap-2 mt-2">
                            {totalRocks > 0 ? (
                              <Button
                                variant="ghost"
                                size="sm"
                                onClick={() => setExpandedPriority(
                                  expandedPriority === priority.id ? null : priority.id
                                )}
                                className="text-xs p-0 h-auto hover:bg-transparent text-cyan-400"
                                data-testid={`button-expand-rocks-${priority.id}`}
                              >
                                {expandedPriority === priority.id ? (
                                  <ChevronDownIcon className="h-4 w-4 mr-1" />
                                ) : (
                                  <ChevronRightIcon className="h-4 w-4 mr-1" />
                                )}
                                <span className="text-muted-foreground">
                                  {totalRocks} rocks
                                </span>
                              </Button>
                            ) : (
                              <span className="text-xs text-slate-500">No rocks yet</span>
                            )}
                            <Button
                              variant="outline"
                              size="sm"
                              onClick={() => {
                                setAddingRockTo(priority.id);
                                setExpandedPriority(priority.id);
                              }}
                              className="text-xs h-6 px-2 border-dashed border-cyan-500/30 text-cyan-400 hover:bg-cyan-500/10"
                              data-testid={`button-add-rock-to-priority-${priority.id}`}
                            >
                              <PlusIcon className="h-3 w-3 mr-1" />
                              Add Rock
                            </Button>
                          </div>
                        </div>
                      </div>

                      {/* Expanded rocks section - same as Priority Management */}
                      {expandedPriority === priority.id && (
                        <div className="mt-4 pl-4 border-l-2 border-cyan-500/20 space-y-3">
                          {/* Rocks grouped by quarter */}
                          {(['Q1', 'Q2', 'Q3', 'Q4'] as const).map((quarter) => {
                            const quarterRocks = rocksByQuarter[quarter] || [];
                            if (quarterRocks.length === 0 && addingRockTo !== priority.id) return null;

                            return (
                              <div key={quarter} className="space-y-2">
                                <div className="flex items-center gap-2">
                                  <Badge className="bg-cyan-500/30 text-cyan-300 text-[10px] px-2 py-0 h-5">
                                    {quarter}
                                  </Badge>
                                  <span className="text-xs text-slate-400">{quarterRocks.length} {quarterRocks.length === 1 ? 'rock' : 'rocks'}</span>
                                </div>

                                {quarterRocks.map((rock: any) => (
                                  <div key={rock.id} className="flex items-start justify-between gap-2 p-2 rounded bg-slate-800/20">
                                    {editingRock === rock.id ? (
                                      <div className="flex-1 space-y-2">
                                        <Input
                                          value={editRockForm.text}
                                          onChange={(e) => setEditRockForm({ ...editRockForm, text: e.target.value })}
                                          placeholder="Rock text"
                                          className="bg-slate-800/50 border-cyan-500/30 text-slate-300 text-sm"
                                          data-testid={`input-edit-rock-text-${rock.id}`}
                                        />
                                        <Select
                                          value={editRockForm.assigneeId || "unassigned"}
                                          onValueChange={(value) => setEditRockForm({ ...editRockForm, assigneeId: value === "unassigned" ? "" : value })}
                                        >
                                          <SelectTrigger className="bg-slate-800/50 border-cyan-500/30 text-slate-300 text-sm" data-testid={`select-edit-rock-assignee-${rock.id}`}>
                                            <SelectValue placeholder="Select assignee" />
                                          </SelectTrigger>
                                          <SelectContent>
                                            <SelectItem value="unassigned">Unassigned</SelectItem>
                                            {users.map((user: any) => (
                                              <SelectItem key={user.id} value={user.id}>
                                                {user.name || user.email}
                                              </SelectItem>
                                            ))}
                                          </SelectContent>
                                        </Select>
                                        <div className="grid grid-cols-2 gap-2">
                                          <Select
                                            value={editRockForm.quarter}
                                            onValueChange={(value) => setEditRockForm({ ...editRockForm, quarter: value })}
                                          >
                                            <SelectTrigger className="bg-slate-800/50 border-cyan-500/30 text-slate-300 text-sm" data-testid={`select-edit-rock-quarter-${rock.id}`}>
                                              <SelectValue placeholder="Quarter" />
                                            </SelectTrigger>
                                            <SelectContent>
                                              <SelectItem value="Q1">Q1</SelectItem>
                                              <SelectItem value="Q2">Q2</SelectItem>
                                              <SelectItem value="Q3">Q3</SelectItem>
                                              <SelectItem value="Q4">Q4</SelectItem>
                                            </SelectContent>
                                          </Select>
                                          <Select
                                            value={editRockForm.year.toString()}
                                            onValueChange={(value) => setEditRockForm({ ...editRockForm, year: parseInt(value) })}
                                          >
                                            <SelectTrigger className="bg-slate-800/50 border-cyan-500/30 text-slate-300 text-sm" data-testid={`select-edit-rock-year-${rock.id}`}>
                                              <SelectValue placeholder="Year" />
                                            </SelectTrigger>
                                            <SelectContent>
                                              <SelectItem value="2025">2025</SelectItem>
                                              <SelectItem value="2026">2026</SelectItem>
                                            </SelectContent>
                                          </Select>
                                        </div>
                                        <div className="flex items-center space-x-2">
                                          <input
                                            type="checkbox"
                                            checked={editRockForm.priority}
                                            onChange={(e) => setEditRockForm({ ...editRockForm, priority: e.target.checked })}
                                            className="h-4 w-4 rounded border-input"
                                            data-testid={`checkbox-edit-rock-priority-${rock.id}`}
                                          />
                                          <label className="text-sm text-slate-400">High Priority (Move to Top)</label>
                                        </div>
                                        <div className="flex gap-2">
                                          <Button
                                            variant="default"
                                            size="sm"
                                            onClick={handleSaveRock}
                                            className="bg-cyan-500/20 text-cyan-300 hover:bg-cyan-500/30"
                                            data-testid={`button-save-rock-${rock.id}`}
                                          >
                                            <CheckIcon className="h-3 w-3 mr-1" />
                                            Save
                                          </Button>
                                          <Button
                                            variant="ghost"
                                            size="sm"
                                            onClick={handleCancelRockEdit}
                                            className="text-slate-400 hover:text-slate-300"
                                            data-testid={`button-cancel-edit-rock-${rock.id}`}
                                          >
                                            <XIcon className="h-3 w-3 mr-1" />
                                            Cancel
                                          </Button>
                                        </div>
                                      </div>
                                    ) : (
                                      <>
                                        <div className="flex-1">
                                          <p className="text-sm text-slate-300">{rock.text}</p>
                                          <div className="flex gap-3 mt-1 text-xs text-slate-500">
                                            <span>{rock.quarter} {rock.year}</span>
                                            {rock.assigneeName && (
                                              <span>• {rock.assigneeName}</span>
                                            )}
                                          </div>
                                        </div>
                                        <ActionMenu
                                          onEdit={() => handleEditRock(rock)}
                                          onDelete={() => deleteRockMutation.mutate(rock.id)}
                                          testId={`action-menu-rock-${rock.id}`}
                                          className="text-cyan-400 hover:text-cyan-300"
                                        />
                                      </>
                                    )}
                                  </div>
                                ))}

                                {/* Add new rock form for this quarter */}
                                {addingRockTo === priority.id && quarter === newRockForm.quarter && (
                                  <div className="p-2 rounded bg-slate-800/30 space-y-2 border border-cyan-500/20">
                                    <Input
                                      value={newRockForm.text}
                                      onChange={(e) => setNewRockForm({ ...newRockForm, text: e.target.value })}
                                      placeholder="Enter rock text..."
                                      className="bg-slate-800/50 border-cyan-500/30 text-slate-300 text-sm"
                                      autoFocus
                                      data-testid={`input-new-rock-text-${priority.id}`}
                                    />
                                    <Select
                                      value={newRockForm.assigneeId || "unassigned"}
                                      onValueChange={(value) => setNewRockForm({ ...newRockForm, assigneeId: value === "unassigned" ? "" : value })}
                                    >
                                      <SelectTrigger className="bg-slate-800/50 border-cyan-500/30 text-slate-300 text-sm" data-testid={`select-new-rock-assignee-${priority.id}`}>
                                        <SelectValue placeholder="Select assignee (optional)" />
                                      </SelectTrigger>
                                      <SelectContent>
                                        <SelectItem value="unassigned">Unassigned</SelectItem>
                                        {users.map((user: any) => (
                                          <SelectItem key={user.id} value={user.id}>
                                            {user.name || user.email}
                                          </SelectItem>
                                        ))}
                                      </SelectContent>
                                    </Select>
                                    <div className="grid grid-cols-2 gap-2">
                                      <Select
                                        value={newRockForm.quarter}
                                        onValueChange={(value) => setNewRockForm({ ...newRockForm, quarter: value })}
                                      >
                                        <SelectTrigger className="bg-slate-800/50 border-cyan-500/30 text-slate-300 text-sm" data-testid={`select-new-rock-quarter-${priority.id}`}>
                                          <SelectValue placeholder="Quarter" />
                                        </SelectTrigger>
                                        <SelectContent>
                                          <SelectItem value="Q1">Q1</SelectItem>
                                          <SelectItem value="Q2">Q2</SelectItem>
                                          <SelectItem value="Q3">Q3</SelectItem>
                                          <SelectItem value="Q4">Q4</SelectItem>
                                        </SelectContent>
                                      </Select>
                                      <Select
                                        value={newRockForm.year.toString()}
                                        onValueChange={(value) => setNewRockForm({ ...newRockForm, year: parseInt(value) })}
                                      >
                                        <SelectTrigger className="bg-slate-800/50 border-cyan-500/30 text-slate-300 text-sm" data-testid={`select-new-rock-year-${priority.id}`}>
                                          <SelectValue placeholder="Year" />
                                        </SelectTrigger>
                                        <SelectContent>
                                          <SelectItem value="2025">2025</SelectItem>
                                          <SelectItem value="2026">2026</SelectItem>
                                        </SelectContent>
                                      </Select>
                                    </div>
                                    <div className="flex items-center space-x-2">
                                      <input
                                        type="checkbox"
                                        checked={newRockForm.priority}
                                        onChange={(e) => setNewRockForm({ ...newRockForm, priority: e.target.checked })}
                                        className="h-4 w-4 rounded border-input"
                                        data-testid={`checkbox-new-rock-priority-${priority.id}`}
                                      />
                                      <label className="text-sm text-slate-400">High Priority (Move to Top)</label>
                                    </div>
                                    <div className="flex gap-2">
                                      <Button
                                        variant="default"
                                        size="sm"
                                        onClick={() => handleAddRock(priority.id)}
                                        className="bg-cyan-500/20 text-cyan-300 hover:bg-cyan-500/30"
                                        data-testid={`button-save-new-rock-${priority.id}`}
                                      >
                                        <CheckIcon className="h-3 w-3 mr-1" />
                                        Add
                                      </Button>
                                      <Button
                                        variant="ghost"
                                        size="sm"
                                        onClick={() => {
                                          setAddingRockTo(null);
                                          setNewRockForm({ text: "", assigneeId: "", assigneeName: "", quarter: "Q1", year: 2025, priority: false });
                                        }}
                                        className="text-slate-400 hover:text-slate-300"
                                        data-testid={`button-cancel-new-rock-${priority.id}`}
                                      >
                                        <XIcon className="h-3 w-3 mr-1" />
                                        Cancel
                                      </Button>
                                    </div>
                                  </div>
                                )}
                              </div>
                            );
                          })}

                          {/* Show add rock button if no rocks exist */}
                          {totalRocks === 0 && addingRockTo !== priority.id && (
                            <div className="text-center py-4 text-slate-500 text-sm">
                              No rocks yet. Click "Add Rock" to get started.
                            </div>
                          )}

                          {/* Add rock button when not adding */}
                          {addingRockTo !== priority.id && (
                            <Button
                              variant="outline"
                              size="sm"
                              onClick={() => {
                                setAddingRockTo(priority.id);
                                setNewRockForm({ ...newRockForm, quarter: "Q1" });
                              }}
                              className="w-full text-xs border-dashed border-cyan-500/30 text-cyan-400 hover:bg-cyan-500/10"
                              data-testid={`button-add-rock-${priority.id}`}
                            >
                              <PlusIcon className="h-3 w-3 mr-1" />
                              Add Rock
                            </Button>
                          )}
                        </div>
                      )}
                    </div>
                  );
                })
              )}
            </div>
          </CardContent>
        </Card>

        {/* Critical Numbers */}
        <Card className="bg-card/50 border-cyan-500/20">
          <CardHeader className="pb-3">
            <CardTitle className="flex items-center gap-2 text-lg text-cyan-300">
              <BarChartIcon className="w-5 h-5" />
              Critical Numbers
            </CardTitle>
          </CardHeader>
          <CardContent>
            {renderMetricGrid(oneYearData.criticalNumbers, "criticalNumbers", 2)}
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

