import { ActionMenu } from "@/components/ui/ActionMenu";

interface ScalabilityRoadmapProps {
  data?: any; // Will be typed properly when connected to real data
}

export default function ScalabilityRoadmap({ data }: ScalabilityRoadmapProps) {
  const DEFAULT_COMPANY_ID = "200c32ef-28fe-4fa7-995d-96386671e89e"; // Using the initialized company ID

  // Fetch roadmap data with priorities
  const { data: roadmapFromDB, isLoading: roadmapLoading } = useQuery({
    queryKey: ['/api/roadmap', DEFAULT_COMPANY_ID],
    queryFn: async () => {
      const response = await fetch(`/api/roadmap/${DEFAULT_COMPANY_ID}`);
      if (!response.ok) throw new Error('Failed to fetch roadmap');
      return response.json();
    }
  });

  // Fetch priorities (capabilities)
  const { data: priorities, isLoading: prioritiesLoading } = useQuery({
    queryKey: ['/api/priorities', DEFAULT_COMPANY_ID],
    queryFn: async () => {
      const response = await fetch(`/api/priorities/${DEFAULT_COMPANY_ID}`);
      if (!response.ok) throw new Error('Failed to fetch priorities');
      return response.json();
    }
  });

  // Fetch SWOT data
  const { data: swot, isLoading: swotLoading } = useQuery({
    queryKey: ['/api/swot', DEFAULT_COMPANY_ID],
    queryFn: async () => {
      const response = await fetch(`/api/swot/${DEFAULT_COMPANY_ID}`);
      if (!response.ok) throw new Error('Failed to fetch SWOT');
      return response.json();
    }
  });

  // Fetch rocks with rollup
  const { data: rocksRollup, isLoading: rocksLoading } = useQuery({
    queryKey: ['/api/rocks/rollup', DEFAULT_COMPANY_ID],
    queryFn: async () => {
      const response = await fetch(`/api/rocks/rollup/${DEFAULT_COMPANY_ID}`);
      if (!response.ok) throw new Error('Failed to fetch rocks rollup');
      return response.json();
    }
  });

  // Fetch agile checklist averages
  const { data: checklistAverages, isLoading: checklistAveragesLoading } = useQuery({
    queryKey: ['/api/agile-checklist', DEFAULT_COMPANY_ID, 'averages'],
    queryFn: async () => {
      const response = await fetch(`/api/agile-checklist/${DEFAULT_COMPANY_ID}/averages`);
      if (!response.ok) throw new Error('Failed to fetch checklist averages');
      return response.json();
    }
  });

  // Fetch overall agile checklist average
  const { data: checklistOverall, isLoading: checklistOverallLoading } = useQuery({
    queryKey: ['/api/agile-checklist', DEFAULT_COMPANY_ID, 'overall-average'],
    queryFn: async () => {
      const response = await fetch(`/api/agile-checklist/${DEFAULT_COMPANY_ID}/overall-average`);
      if (!response.ok) throw new Error('Failed to fetch checklist overall average');
      return response.json();
    }
  });

  // State for managing roadmap data - start with empty values
  const [roadmapData, setRoadmapData] = useState({
    companyName: "Small Giants",
    threeHagDate: "",
    oneYearDate: "",

    // Foundation Section
    foundation: {
      corePurpose: "",
      mission: "",
      coreValues: [] as Array<{ id: string; name: string; description: string }>,
      strategicAnchors: [] as Array<{ id: string; text: string }>,
      coreCustomer: "",
      brandPromise: ""
    },

    // Three Year Section
    threeYear: {
      bhag: "",
      threeHagStatement: "",
      knownFor: "",
      capabilities: [] as Array<{ id: string; text: string }>,
      strengths: [] as Array<{ id: string; text: string }>,
      weaknesses: [] as Array<{ id: string; text: string }>,
      opportunities: [] as Array<{ id: string; text: string }>,
      threats: [] as Array<{ id: string; text: string }>
    },

    // One Year Section
    oneYear: {
      onePhraseStrategy: "",
      criticalNumbers: {
        profitPerX: { label: "Profit per X", value: "" },
        nps: { label: "NPS", value: "" },
        enps: { label: "eNPS", value: "" },
        ler: { label: "Labor Efficiency Ratio", value: "" },
        bpr: { label: "Builder Protector Ratio", value: "" }
      },
      annualPriorities: [] as Array<{ id: string; text: string }>
    },

    // One Year Goals
    oneYearGoals: {
      revenue: { label: "Revenue", value: "" },
      grossProfit: { label: "Gross Profit", value: "" },
      netProfit: { label: "Net Profit", value: "" },
      cash: { label: "Cash", value: "" },
      nps: { label: "NPS", value: "" },
      enps: { label: "eNPS", value: "" },
      bptw: { label: "BPTW", value: "" },
      emr: { label: "EMR", value: "" },
      bhag: { label: "BHAG", value: "" },
      gainFade: { label: "Gain/Fade", value: "" },
      entryExit: { label: "Entry/Exit", value: "" }
    },

    // Quarterly Rocks
    quarterlyRocks: {
      capabilities: { Q1: [], Q2: [], Q3: [], Q4: [] },
      priorities: { Q1: [], Q2: [], Q3: [], Q4: [] },
      department: { Q1: [], Q2: [], Q3: [], Q4: [] }
    },

    // List of team members for assigning rocks
    teamMembers: [
      { id: '1', name: 'John Smith' },
      { id: '2', name: 'Sarah Johnson' },
      { id: '3', name: 'Mike Davis' },
      { id: '4', name: 'Emily Chen' }
    ]
  });

  // State for collapsible sections
  const [sectionsExpanded, setSectionsExpanded] = useState({
    foundation: true,
    threeYear: true,
    oneYear: true
  });

  // State for quarter expansion in rocks
  const [quartersExpanded, setQuartersExpanded] = useState({
    Q1: true,
    Q2: true,
    Q3: true,
    Q4: true
  });

  // State for rock filters
  const [rockFilters, setRockFilters] = useState({
    quarter: 'all',
    assignee: 'all',
    status: 'all'
  });

  // Fetch users for assignee filter
  const { data: users = [] } = useQuery({
    queryKey: ['/api/users'],
    queryFn: async () => {
      const response = await fetch('/api/users');
      if (!response.ok) throw new Error('Failed to fetch users');
      return response.json();
    }
  });

  // Update local state when database data is fetched
  useEffect(() => {
    if (roadmapFromDB && roadmapFromDB.roadmap) {
      const roadmap = roadmapFromDB.roadmap;

      // Parse oneYearGoal JSON if it exists
      let parsedGoals = {};
      if (roadmap.oneYearGoal) {
        try {
          parsedGoals = JSON.parse(roadmap.oneYearGoal);
        } catch (e) {
          console.warn('Failed to parse oneYearGoal JSON:', e);
        }
      }

      // Parse critical numbers JSON if it exists
      let parsedCriticalNumbers = {};
      if (roadmap.criticalNumbers) {
        try {
          if (typeof roadmap.criticalNumbers === 'string') {
            parsedCriticalNumbers = JSON.parse(roadmap.criticalNumbers);
          } else {
            parsedCriticalNumbers = roadmap.criticalNumbers;
          }
        } catch (e) {
          console.warn('Failed to parse criticalNumbers JSON:', e);
        }
      }

      setRoadmapData(prev => ({
        ...prev,
        companyName: roadmap.companyName || "Small Giants",
        threeHagDate: roadmap.threeHagDate || "",
        oneYearDate: roadmap.oneYearDate || "",
        foundation: {
          ...prev.foundation,
          corePurpose: roadmap.corePurpose || "",
          mission: roadmap.mission || "",
          brandPromise: roadmap.brandPromise || "",
          coreCustomer: roadmap.coreCustomer || "",
          coreValues: roadmap.coreValues || [],
          strategicAnchors: roadmap.strategicAnchors || []
        },
        threeYear: {
          ...prev.threeYear,
          bhag: roadmap.bhag || "",
          threeHagStatement: roadmap.threeHagStatement || "",
          knownFor: roadmap.knownFor || ""
        },
        oneYear: {
          ...prev.oneYear,
          onePhraseStrategy: roadmap.onePhraseStrategy || "",
          criticalNumbers: { ...prev.oneYear.criticalNumbers, ...parsedCriticalNumbers }
        },
        oneYearGoals: { ...prev.oneYearGoals, ...parsedGoals }
      }));
    }
  }, [roadmapFromDB]);

  // Update SWOT data when fetched
  useEffect(() => {
    if (swot) {
      setRoadmapData(prev => ({
        ...prev,
        threeYear: {
          ...prev.threeYear,
          strengths: (swot.strengths || []).map((text: string, index: number) => ({
            id: `s${index + 1}`,
            text
          })),
          weaknesses: (swot.weaknesses || []).map((text: string, index: number) => ({
            id: `w${index + 1}`,
            text
          })),
          opportunities: (swot.opportunities || []).map((text: string, index: number) => ({
            id: `o${index + 1}`,
            text
          })),
          threats: (swot.threats || []).map((text: string, index: number) => ({
            id: `t${index + 1}`,
            text
          }))
        }
      }));
    }
  }, [swot]);

  // Update priorities and capabilities when fetched
  useEffect(() => {
    if (priorities && Array.isArray(priorities)) {
      const capabilities = priorities.filter((p: any) => p.type === 'capability');
      const annualPriorities = priorities.filter((p: any) => p.type === 'priority');

      setRoadmapData(prev => ({
        ...prev,
        threeYear: {
          ...prev.threeYear,
          capabilities: capabilities.map((c: any) => ({
            id: c.id,
            text: c.title || c.description
          }))
        },
        oneYear: {
          ...prev.oneYear,
          annualPriorities: annualPriorities.map((p: any) => ({
            id: p.id,
            text: p.title || p.description
          }))
        }
      }));
    }
  }, [priorities]);

  // Update rocks rollup when fetched
  useEffect(() => {
    if (rocksRollup && typeof rocksRollup === 'object') {
      const quarterlyRocks: any = {
        capabilities: { Q1: [], Q2: [], Q3: [], Q4: [] },
        priorities: { Q1: [], Q2: [], Q3: [], Q4: [] },
        department: { Q1: [], Q2: [], Q3: [], Q4: [] }
      };

      // rocksRollup is grouped by "YYYY-Q#" keys like "2025-Q1"
      Object.entries(rocksRollup).forEach(([key, rocks]: [string, any]) => {
        // Extract quarter from key (e.g., "2025-Q1" -> "Q1")
        const quarter = key.split('-')[1];

        if (Array.isArray(rocks)) {
          rocks.forEach((rock: any) => {
            const rockData = {
              id: rock.id,
              text: rock.text,
              assignee: rock.assigneeId,
              assigneeName: rock.assigneeName || 'Unassigned',
              capabilityTitle: rock.priorityTitle
            };

            // Filter rocks consistently - only show priority rocks in the main quarterly view
            if (rock.priorityType === 'priority' && quarterlyRocks.priorities[quarter]) {
              quarterlyRocks.priorities[quarter].push(rockData);
            }
            // Keep capability rocks separate for capability-specific views
            else if (rock.priorityType === 'capability' && quarterlyRocks.capabilities[quarter]) {
              quarterlyRocks.capabilities[quarter].push(rockData);
            }
          });
        }
      });

      setRoadmapData(prev => ({
        ...prev,
        quarterlyRocks
      }));
    }
  }, [rocksRollup]);

  // Render read-only field
  const renderField = (value: string, multiline = false) => {
    return (
      <p className={`${multiline ? 'text-xs' : 'text-sm'} text-slate-300`}>{value}</p>
    );
  };

  // Render read-only list
  const renderList = (items: any[], useNumbering?: boolean) => {
    const numberWords = ['One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine', 'Ten'];

    return (
      <div className="space-y-2">
        {items.map((item, idx) => (
          <div key={item.id} className="flex items-start gap-2 py-1">
            <span className="text-cyan-400 text-xs mt-0.5">
              {useNumbering ? `${numberWords[idx] || `${idx + 1}`}:` : '•'}
            </span>
            <span className="flex-1 text-xs text-slate-300 leading-relaxed">{item.text || item.name}</span>
          </div>
        ))}
      </div>
    );
  };

  // Render quarterly rocks for a specific type (capabilities or priorities) - ORGANIZED BY QUARTER
  const renderQuarterlyRocks = (type: 'capabilities' | 'priorities') => {
    const rocks = roadmapData.quarterlyRocks[type];
    if (!rocks || Object.keys(rocks).length === 0) return null;

    // Collect all rocks from all quarters with their quarter info
    const allRocks: any[] = [];
    (['Q1', 'Q2', 'Q3', 'Q4'] as const).forEach((quarter) => {
      const quarterKey = quarter as keyof typeof rocks;
      const quarterRocks = rocks[quarterKey] || [];
      quarterRocks.forEach((rock: any) => {
        allRocks.push({ ...rock, quarter });
      });
    });

    if (allRocks.length === 0) return null;

    // Apply filters and group by quarter
    const rocksByQuarter: Record<string, any[]> = { Q1: [], Q2: [], Q3: [], Q4: [] };

    allRocks.forEach((rock) => {
      // Apply filters
      let passesFilter = true;

      // Filter by quarter
      if (rockFilters.quarter !== 'all' && rock.quarter !== rockFilters.quarter) {
        passesFilter = false;
      }

      // Filter by assignee
      if (rockFilters.assignee !== 'all') {
        const assigneeMatch = rockFilters.assignee === 'unassigned' 
          ? (!rock.assigneeName || rock.assigneeName === 'Unassigned')
          : rock.assigneeId === rockFilters.assignee;
        if (!assigneeMatch) passesFilter = false;
      }

      // Filter by status (if available)
      if (rockFilters.status !== 'all' && rock.status && rock.status !== rockFilters.status) {
        passesFilter = false;
      }

      if (passesFilter) {
        rocksByQuarter[rock.quarter].push(rock);
      }
    });

    // Check if any rocks passed filters
    const totalFilteredRocks = Object.values(rocksByQuarter).flat().length;

    if (totalFilteredRocks === 0) {
      return (
        <div className="mt-3 p-3 bg-slate-800/10 rounded border border-cyan-500/5 text-center">
          <p className="text-xs text-slate-400">No rocks match the current filters</p>
        </div>
      );
    }

    return (
      <div className="mt-3 space-y-2">
        <div className="flex items-center gap-2 mb-2">
          <h4 className="text-xs font-bold text-cyan-400 uppercase tracking-wider">
            Quarterly Rocks
          </h4>
          <Badge variant="secondary" className="text-[9px]">
            {totalFilteredRocks}
          </Badge>
        </div>

        {/* Render rocks organized by quarter */}
        {(['Q1', 'Q2', 'Q3', 'Q4'] as const).map((quarter) => {
          const quarterRocks = rocksByQuarter[quarter];
          if (quarterRocks.length === 0) return null;

          return (
            <div key={quarter} className="bg-slate-800/10 rounded border border-cyan-500/10">
              {/* Quarter Header - Collapsible */}
              <button
                onClick={() => setQuartersExpanded({ ...quartersExpanded, [quarter]: !quartersExpanded[quarter] })}
                className="w-full flex items-center justify-between p-2 hover-elevate active-elevate-2 rounded"
                data-testid={`button-toggle-${quarter}`}
              >
                <div className="flex items-center gap-2">
                  {quartersExpanded[quarter] ? (
                    <ChevronUp className="w-3 h-3 text-cyan-400" />
                  ) : (
                    <ChevronDown className="w-3 h-3 text-cyan-400" />
                  )}
                  <Badge className="bg-cyan-500/30 text-cyan-300 text-[10px] px-2 py-0 h-5">
                    {quarter}
                  </Badge>
                  <span className="text-xs font-semibold text-cyan-300">{quarterRocks.length} {quarterRocks.length === 1 ? 'Rock' : 'Rocks'}</span>
                </div>
              </button>

              {/* Quarter Rocks List */}
              {quartersExpanded[quarter] && (
                <div className="px-2 pb-2 space-y-1">
                  {quarterRocks.map((rock: any, idx: number) => (
                    <div key={rock.id || idx} className="flex items-start gap-2 p-2 bg-slate-800/20 rounded border border-cyan-500/5">
                      <div className="flex-1 min-w-0">
                        <span className="text-xs text-slate-300 block">{rock.text}</span>
                        <div className="flex flex-wrap gap-1 items-center mt-1">
                          {rock.capabilityTitle && (
                            <Badge variant="secondary" className="text-[9px] px-1 py-0 h-3.5">
                              {rock.capabilityTitle}
                            </Badge>
                          )}
                          {rock.priorityTitle && (
                            <Badge variant="secondary" className="text-[9px] px-1 py-0 h-3.5">
                              {rock.priorityTitle}
                            </Badge>
                          )}
                          <span className="text-[9px] text-cyan-400/70">
                            • Assignee: {rock.assigneeName || 'Unassigned'}
                          </span>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          );
        })}
      </div>
    );
  };

  return (
    <div className="w-full p-6 space-y-6 bg-gradient-to-br from-slate-950 via-blue-950 to-slate-900 min-h-screen">
      {/* Header */}
      <div className="text-center mb-8">
        <h1 className="text-3xl font-bold text-cyan-300 mb-2">{roadmapData.companyName}</h1>
        <p className="text-sm text-cyan-400/60">SCALABILITY ROADMAP</p>
      </div>

      {/* FOUNDATION Section - Full Width */}
      <div className="mb-8">
        <div className="flex items-center justify-center gap-4 mb-6 group">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setSectionsExpanded({ ...sectionsExpanded, foundation: !sectionsExpanded.foundation })}
            className="text-cyan-400 hover:text-cyan-300"
            data-testid="button-toggle-foundation"
          >
            {sectionsExpanded.foundation ? <ChevronUp className="w-5 h-5" /> : <ChevronDown className="w-5 h-5" />}
          </Button>
          <h2 className="text-xl font-bold text-cyan-400">FOUNDATION</h2>
          <ActionMenu
            onEdit={() => window.dispatchEvent(new CustomEvent('navigate', { detail: 'foundation' }))}
            onDelete={() => {}} // Foundation doesn't have delete functionality
            testId="action-menu-foundation"
            className="opacity-0 group-hover:opacity-100 transition-opacity"
          />
        </div>

        {sectionsExpanded.foundation && (
        <>
        {/* First Row: Core Purpose (1/4), Mission (1/4), Brand Promise (1/4), Core Customer (1/4) */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-4">
          {/* Core Purpose - 1/4 width */}
          <Card className="bg-card/50 border-cyan-500/20 backdrop-blur-sm">
            <CardHeader className="bg-slate-800/50 border-b border-cyan-500/20">
              <div className="flex items-center justify-between">
                <CardTitle className="text-sm text-cyan-300 font-semibold">
                  {roadmapFromDB?.roadmap?.corePurposeTitle || "Core Purpose"}
                </CardTitle>
              </div>
            </CardHeader>
            <CardContent className="pt-4">
              {renderField(roadmapData.foundation.corePurpose, true)}
            </CardContent>
          </Card>

          {/* Mission - 1/4 width */}
          <Card className="bg-card/50 border-cyan-500/20 backdrop-blur-sm">
            <CardHeader className="bg-slate-800/50 border-b border-cyan-500/20">
              <CardTitle className="text-sm text-cyan-300 font-semibold">
                {roadmapFromDB?.roadmap?.missionTitle || "Mission"}
              </CardTitle>
            </CardHeader>
            <CardContent className="pt-4">
              {renderField(roadmapData.foundation.mission, true)}
            </CardContent>
          </Card>

          {/* Brand Promise - 1/4 width */}
          <Card className="bg-card/50 border-cyan-500/20 backdrop-blur-sm">
            <CardHeader className="bg-slate-800/50 border-b border-cyan-500/20">
              <CardTitle className="text-sm text-cyan-300 font-semibold">
                {roadmapFromDB?.roadmap?.brandPromiseTitle || "Brand Promise"}
              </CardTitle>
            </CardHeader>
            <CardContent className="pt-4">
              {renderField(roadmapData.foundation.brandPromise)}
            </CardContent>
          </Card>

          {/* Core Customer - 1/4 width */}
          <Card className="bg-card/50 border-cyan-500/20 backdrop-blur-sm">
            <CardHeader className="bg-slate-800/50 border-b border-cyan-500/20">
              <CardTitle className="text-sm text-cyan-300 font-semibold">
                {roadmapFromDB?.roadmap?.coreCustomerTitle || "Core Customer"}
              </CardTitle>
            </CardHeader>
            <CardContent className="pt-4">
              {renderField(roadmapData.foundation.coreCustomer, true)}
            </CardContent>
          </Card>
        </div>

        {/* Second Row: Strategic Anchors (50%) | Core Values (50%) */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">

          {/* Strategic Anchors */}
          <Card className="bg-card/50 border-cyan-500/20 backdrop-blur-sm">
            <CardHeader className="bg-slate-800/50 border-b border-cyan-500/20">
              <CardTitle className="text-sm text-cyan-300 font-semibold">
                {roadmapFromDB?.roadmap?.strategicAnchorsTitle || "Strategic Anchors"}
              </CardTitle>
            </CardHeader>
            <CardContent className="pt-4">
              {renderList(roadmapData.foundation.strategicAnchors)}
            </CardContent>
          </Card>

          {/* Core Values */}
          <Card className="bg-card/50 border-cyan-500/20 backdrop-blur-sm">
            <CardHeader className="bg-slate-800/50 border-b border-cyan-500/20">
              <CardTitle className="text-sm text-cyan-300 font-semibold">
                {roadmapFromDB?.roadmap?.coreValuesTitle || "Core Values"}
              </CardTitle>
            </CardHeader>
            <CardContent className="pt-4">
              <div className="space-y-3">
                {roadmapData.foundation.coreValues.map((value) => (
                  <div key={value.id} className="border-l-2 border-cyan-500/30 pl-3 py-1">
                    <div>
                      <div className="flex items-center gap-2 mb-1">
                        <span className="text-sm font-bold text-cyan-400">{value.name}</span>
                      </div>
                      <p className="text-xs text-slate-300 leading-relaxed">{value.description}</p>
                    </div>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        </div>
        </>
        )}
      </div>

      {/* Three Year and One Year Sections - 50/50 Split */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">

        {/* THREE YEAR Column - Left Half */}
        <div className="space-y-4">
          <div className="flex items-center justify-center gap-4 mb-4 group">
            <Button
              variant="ghost"
              size="sm"
              onClick={() => setSectionsExpanded({ ...sectionsExpanded, threeYear: !sectionsExpanded.threeYear })}
              className="text-cyan-400 hover:text-cyan-300"
              data-testid="button-toggle-three-year"
            >
              {sectionsExpanded.threeYear ? <ChevronUp className="w-5 h-5" /> : <ChevronDown className="w-5 h-5" />}
            </Button>
            <h2 className="text-xl font-bold text-cyan-400">THREE YEAR</h2>
            <ActionMenu
              onEdit={() => window.dispatchEvent(new CustomEvent('navigate', { detail: 'three-year' }))}
              onDelete={() => {}} // Three Year doesn't have delete functionality
              testId="action-menu-three-year"
              className="opacity-0 group-hover:opacity-100 transition-opacity"
            />
          </div>

          {sectionsExpanded.threeYear && (
          <>

          {/* BHAG */}
          <Card className="bg-card/50 border-cyan-500/20 backdrop-blur-sm">
            <CardHeader className="bg-slate-800/50 border-b border-cyan-500/20">
              <CardTitle className="text-sm text-cyan-300 font-semibold">BHAG</CardTitle>
            </CardHeader>
            <CardContent className="pt-4">
              {renderField(roadmapData.threeYear.bhag)}
            </CardContent>
          </Card>

          {/* 3HAG Statement */}
          <Card className="bg-card/50 border-cyan-500/20 backdrop-blur-sm">
            <CardHeader className="bg-slate-800/50 border-b border-cyan-500/20">
              <CardTitle className="text-sm text-cyan-300 font-semibold">3HAG Statement</CardTitle>
            </CardHeader>
            <CardContent className="pt-4">
              {renderField(roadmapData.threeYear.threeHagStatement, true)}
            </CardContent>
          </Card>

          {/* Known For */}
          <Card className="bg-card/50 border-cyan-500/20 backdrop-blur-sm">
            <CardHeader className="bg-slate-800/50 border-b border-cyan-500/20">
              <CardTitle className="text-sm text-cyan-300 font-semibold">Known For</CardTitle>
            </CardHeader>
            <CardContent className="pt-4">
              {renderField(roadmapData.threeYear.knownFor, true)}
            </CardContent>
          </Card>

          {/* Capabilities */}
