import { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Checkbox } from "@/components/ui/checkbox";
import { useQuery, useMutation } from "@tanstack/react-query";
import { queryClient, apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import { 
  PlusIcon, 
  XIcon, 
  CheckIcon,
  PencilIcon,
  TrashIcon,
  ListTodoIcon
} from "lucide-react";

interface JustGetItDoneItem {
  id: string;
  text: string;
  completed: boolean;
  companyId: string;
  createdAt: Date;
}

export default function JustGetItDone() {
  const { toast } = useToast();
  const DEFAULT_COMPANY_ID = "200c32ef-28fe-4fa7-995d-96386671e89e";

  const [newItemText, setNewItemText] = useState("");
  const [editingItemId, setEditingItemId] = useState<string | null>(null);
  const [editingText, setEditingText] = useState("");

  const { data: items = [], isLoading } = useQuery<JustGetItDoneItem[]>({
    queryKey: ['/api/just-get-it-done', DEFAULT_COMPANY_ID],
    queryFn: async () => {
      const response = await fetch(`/api/just-get-it-done/${DEFAULT_COMPANY_ID}`);
      if (!response.ok) throw new Error('Failed to fetch items');
      return response.json();
    }
  });

  const createMutation = useMutation({
    mutationFn: async (text: string) => {
      return apiRequest('/api/just-get-it-done', 'POST', {
        companyId: DEFAULT_COMPANY_ID,
        text
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/just-get-it-done', DEFAULT_COMPANY_ID] });
      setNewItemText("");
      toast({
        title: "Success",
        description: "Item added successfully",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Failed to add item",
        variant: "destructive",
      });
    }
  });

  const updateMutation = useMutation({
    mutationFn: async ({ id, updates }: { id: string; updates: Partial<JustGetItDoneItem> }) => {
      return apiRequest(`/api/just-get-it-done/${id}`, 'PUT', updates);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/just-get-it-done', DEFAULT_COMPANY_ID] });
      setEditingItemId(null);
      setEditingText("");
      toast({
        title: "Success",
        description: "Item updated successfully",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Failed to update item",
        variant: "destructive",
      });
    }
  });

  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      return apiRequest(`/api/just-get-it-done/${id}`, 'DELETE');
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/just-get-it-done', DEFAULT_COMPANY_ID] });
      toast({
        title: "Success",
        description: "Item deleted successfully",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Failed to delete item",
        variant: "destructive",
      });
    }
  });

  const handleAddItem = () => {
    if (!newItemText.trim()) return;
    createMutation.mutate(newItemText.trim());
  };

  const handleToggleComplete = (item: JustGetItDoneItem) => {
    updateMutation.mutate({
      id: item.id,
      updates: { completed: !item.completed }
    });
  };

  const handleStartEdit = (item: JustGetItDoneItem) => {
    setEditingItemId(item.id);
    setEditingText(item.text);
  };

  const handleSaveEdit = (id: string) => {
    if (!editingText.trim()) return;
    updateMutation.mutate({
      id,
      updates: { text: editingText.trim() }
    });
  };

  const handleCancelEdit = () => {
    setEditingItemId(null);
    setEditingText("");
  };

  const handleDelete = (id: string) => {
    deleteMutation.mutate(id);
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-center">
          <ListTodoIcon className="w-8 h-8 animate-pulse text-cyan-400 mx-auto mb-2" />
          <p className="text-cyan-400/60">Loading items...</p>
        </div>
      </div>
    );
  }

  const sortedItems = [...items].sort((a, b) => {
    if (a.completed !== b.completed) {
      return a.completed ? 1 : -1;
    }
    return new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime();
  });

  return (
    <div className="space-y-6">
      <div className="border-b border-cyan-500/20 pb-4">
        <div className="flex items-center gap-3 mb-2">
          <ListTodoIcon className="w-6 h-6 text-cyan-400" />
          <h1 className="text-2xl font-bold text-cyan-300">Just Get It Done</h1>
        </div>
        <p className="text-sm text-cyan-400/60">
          Quick action items that need to be completed
        </p>
      </div>

      <Card className="bg-card/50 border-cyan-500/20">
        <CardHeader className="pb-3">
          <div className="flex gap-2">
            <Input
              value={newItemText}
              onChange={(e) => setNewItemText(e.target.value)}
              placeholder="Add a new item..."
              className="flex-1 bg-slate-800/50 border-cyan-500/30 text-slate-300"
              onKeyDown={(e) => e.key === 'Enter' && handleAddItem()}
              data-testid="input-new-item"
            />
            <Button
              onClick={handleAddItem}
              disabled={!newItemText.trim() || createMutation.isPending}
              className="bg-cyan-500/20 text-cyan-300 hover:bg-cyan-500/30"
              data-testid="button-add-item"
            >
              <PlusIcon className="w-4 h-4 mr-2" />
              Add
            </Button>
          </div>
        </CardHeader>

        <CardContent className="space-y-2">
          {sortedItems.length === 0 ? (
            <div className="text-center py-8 text-slate-400">
              <ListTodoIcon className="w-12 h-12 mx-auto mb-3 opacity-30" />
              <p>No items yet. Add your first item above.</p>
            </div>
          ) : (
            sortedItems.map((item) => (
              <div
                key={item.id}
                className={`group border rounded-lg p-3 transition-all ${
                  item.completed
                    ? 'bg-slate-800/30 border-cyan-500/10'
                    : 'bg-slate-800/50 border-cyan-500/20'
                }`}
                data-testid={`item-${item.id}`}
              >
                {editingItemId === item.id ? (
                  <div className="flex gap-2">
                    <Input
                      value={editingText}
                      onChange={(e) => setEditingText(e.target.value)}
                      className="flex-1 bg-slate-800/50 border-cyan-500/30 text-slate-300"
                      autoFocus
                      onKeyDown={(e) => {
                        if (e.key === 'Enter') handleSaveEdit(item.id);
                        if (e.key === 'Escape') handleCancelEdit();
                      }}
                      data-testid={`input-edit-${item.id}`}
                    />
                    <Button
                      size="icon"
                      variant="ghost"
                      onClick={() => handleSaveEdit(item.id)}
                      className="h-8 w-8 text-green-400 hover:text-green-300"
                      data-testid={`button-save-${item.id}`}
                    >
                      <CheckIcon className="h-4 w-4" />
                    </Button>
                    <Button
                      size="icon"
                      variant="ghost"
                      onClick={handleCancelEdit}
                      className="h-8 w-8 text-red-400 hover:text-red-300"
                      data-testid={`button-cancel-edit-${item.id}`}
                    >
                      <XIcon className="h-4 w-4" />
                    </Button>
                  </div>
                ) : (
                  <div className="flex items-center gap-3">
                    <Checkbox
                      checked={item.completed}
                      onCheckedChange={() => handleToggleComplete(item)}
                      className="border-cyan-500/30 data-[state=checked]:bg-cyan-500/20 data-[state=checked]:border-cyan-500/50"
                      data-testid={`checkbox-complete-${item.id}`}
                    />
                    <span
                      className={`flex-1 ${
                        item.completed
                          ? 'text-slate-400 line-through'
                          : 'text-slate-200'
                      }`}
                      data-testid={`text-${item.id}`}
                    >
                      {item.text}
                    </span>
                    <div className="opacity-0 group-hover:opacity-100 transition-opacity flex gap-1">
                      <Button
                        size="icon"
                        variant="ghost"
                        onClick={() => handleStartEdit(item)}
                        className="h-6 w-6 text-cyan-400 hover:text-cyan-300"
                        data-testid={`button-edit-${item.id}`}
                      >
                        <PencilIcon className="h-3 w-3" />
                      </Button>
                      <Button
                        size="icon"
                        variant="ghost"
                        onClick={() => handleDelete(item.id)}
                        className="h-6 w-6 text-red-400 hover:text-red-300"
                        data-testid={`button-delete-${item.id}`}
                      >
                        <TrashIcon className="h-3 w-3" />
                      </Button>
                    </div>
                  </div>
                )}
              </div>
            ))
          )}
        </CardContent>
      </Card>
    </div>
  );
}

