import { db } from '../server/db';
import { agileChecklistItems, users } from '../shared/schema';
import { eq, and } from 'drizzle-orm';
import { writeFileSync } from 'fs';
import { join } from 'path';

const COMPANY_ID = '200c32ef-28fe-4fa7-995d-96386671e89e';
const USER_ID = 'demo-user-1';

// Helper to convert camelCase to snake_case
function toSnakeCase(str: string): string {
  return str.replace(/[A-Z]/g, letter => `_${letter.toLowerCase()}`);
}

// Helper to escape SQL values properly
function escapeSqlValue(value: any): string {
  if (value === null || value === undefined) {
    return 'NULL';
  }
  if (typeof value === 'boolean') {
    return value ? 'true' : 'false';
  }
  if (typeof value === 'number') {
    return String(value);
  }
  if (value instanceof Date) {
    return `'${value.toISOString()}'`;
  }
  if (Array.isArray(value) || (typeof value === 'object' && value.constructor === Object)) {
    return `'${JSON.stringify(value).replace(/'/g, "''")}'::jsonb`;
  }
  return `'${String(value).replace(/'/g, "''")}'`;
}

async function exportAgileChecklist() {
  console.log('Starting Agile Checklist export...');

  const sqlStatements: string[] = [];

  // Header
  sqlStatements.push(`-- ============================================`);
  sqlStatements.push(`-- AGILE GROWTH CHECKLIST EXPORT`);
  sqlStatements.push(`-- Company: Small Giants (${COMPANY_ID})`);
  sqlStatements.push(`-- User: ${USER_ID}`);
  sqlStatements.push(`-- Generated: ${new Date().toISOString()}`);
  sqlStatements.push(`-- ============================================`);
  sqlStatements.push(``);
  sqlStatements.push(`-- INSTRUCTIONS:`);
  sqlStatements.push(`-- 1. Open Replit Database pane`);
  sqlStatements.push(`-- 2. Switch to PRODUCTION database`);
  sqlStatements.push(`-- 3. Select all statements below and run`);
  sqlStatements.push(`-- 4. Refresh the Agile Checklist page`);
  sqlStatements.push(``);

  // Check if demo user exists, if not create one
  const demoUser = await db.select().from(users).where(eq(users.id, USER_ID)).limit(1);

  if (demoUser.length === 0) {
    sqlStatements.push(`-- ============================================`);
    sqlStatements.push(`-- CREATE DEMO USER`);
    sqlStatements.push(`-- ============================================`);
    sqlStatements.push(``);
    sqlStatements.push(`INSERT INTO users (id, name, email, password, role)`);
    sqlStatements.push(`VALUES ('demo-user-1', 'Demo User', 'demo@smallgiantsonline.com', '$2a$10$dummyhash', 'user');`);
    sqlStatements.push(``);
  }

  // Export Agile Checklist Items
  console.log('Exporting agile checklist items...');
  const checklistItems = await db.select()
    .from(agileChecklistItems)
    .where(
      and(
        eq(agileChecklistItems.companyId, COMPANY_ID),
        eq(agileChecklistItems.userId, USER_ID)
      )
    );

  console.log(`Found ${checklistItems.length} checklist item(s)`);

  if (checklistItems.length > 0) {
    sqlStatements.push(`-- ============================================`);
    sqlStatements.push(`-- AGILE CHECKLIST ITEMS (${checklistItems.length} records)`);
    sqlStatements.push(`-- ============================================`);
    sqlStatements.push(``);

    // Group by category for better organization
    const categories = ['leadership', 'talent', 'strategy', 'execution', 'cash', 'customer', 'systems'];

    for (const category of categories) {
      const categoryItems = checklistItems.filter(item => item.category === category);
      if (categoryItems.length > 0) {
        sqlStatements.push(`-- ${category.charAt(0).toUpperCase() + category.slice(1)} (${categoryItems.length} items)`);

        for (const record of categoryItems) {
          const entries = Object.entries(record).filter(([_, value]) => value !== undefined);
          const columns = entries.map(([key, _]) => toSnakeCase(key));
          const values = entries.map(([_, value]) => escapeSqlValue(value));

          sqlStatements.push(`INSERT INTO agile_checklist_items (${columns.join(', ')})`);
          sqlStatements.push(`VALUES (${values.join(', ')});`);
        }
        sqlStatements.push(``);
      }
    }
  }

  // Footer
  sqlStatements.push(`-- ============================================`);
  sqlStatements.push(`-- EXPORT COMPLETE`);
  sqlStatements.push(`-- Total Items: ${checklistItems.length}`);
  sqlStatements.push(`-- ============================================`);

  // Write to file
  const outputPath = join(process.cwd(), 'exports', 'agile-checklist-export.sql');
  writeFileSync(outputPath, sqlStatements.join('\n'), 'utf-8');

  console.log('\n✅ Agile Checklist export complete!');
  console.log(`📄 File saved to: ${outputPath}`);
  console.log(`   Total Items: ${checklistItems.length}`);

  process.exit(0);
}

exportAgileChecklist().catch((error) => {
  console.error('Export failed:', error);
  process.exit(1);
});

