import { db } from '../server/db';
import { rocks } from '../shared/schema';
import { eq } from 'drizzle-orm';
import { writeFileSync } from 'fs';
import { join } from 'path';

const COMPANY_ID = '200c32ef-28fe-4fa7-995d-96386671e89e';

// Helper to convert camelCase to snake_case
function toSnakeCase(str: string): string {
  return str.replace(/[A-Z]/g, letter => `_${letter.toLowerCase()}`);
}

// Helper to escape SQL values properly
function escapeSqlValue(value: any): string {
  // Handle null/undefined
  if (value === null || value === undefined) {
    return 'NULL';
  }

  // Handle booleans
  if (typeof value === 'boolean') {
    return value ? 'true' : 'false';
  }

  // Handle numbers
  if (typeof value === 'number') {
    return String(value);
  }

  // Handle Date objects
  if (value instanceof Date) {
    return `'${value.toISOString()}'`;
  }

  // Handle arrays or objects (JSON)
  if (Array.isArray(value) || (typeof value === 'object' && value.constructor === Object)) {
    return `'${JSON.stringify(value).replace(/'/g, "''")}'::jsonb`;
  }

  // Handle strings - escape single quotes
  return `'${String(value).replace(/'/g, "''")}'`;
}

async function exportRocks() {
  console.log('Starting rocks export for company:', COMPANY_ID);

  const sqlStatements: string[] = [];

  // Header
  sqlStatements.push(`-- ============================================`);
  sqlStatements.push(`-- ROCKS DATA EXPORT - Development to Production`);
  sqlStatements.push(`-- Company: Small Giants (${COMPANY_ID})`);
  sqlStatements.push(`-- Generated: ${new Date().toISOString()}`);
  sqlStatements.push(`-- ============================================`);
  sqlStatements.push(``);
  sqlStatements.push(`-- INSTRUCTIONS:`);
  sqlStatements.push(`-- 1. Open Replit Database pane`);
  sqlStatements.push(`-- 2. Switch to PRODUCTION database`);
  sqlStatements.push(`-- 3. Select all INSERT statements below`);
  sqlStatements.push(`-- 4. Run them in the SQL Console`);
  sqlStatements.push(`-- 5. Verify rocks appear in production`);
  sqlStatements.push(``);

  // Export Rocks
  console.log('Exporting rocks...');
  const rocksData = await db.select().from(rocks).where(eq(rocks.companyId, COMPANY_ID));
  console.log(`Found ${rocksData.length} rock(s)`);

  if (rocksData.length > 0) {
    sqlStatements.push(`-- ============================================`);
    sqlStatements.push(`-- ROCKS (${rocksData.length} records)`);
    sqlStatements.push(`-- ============================================`);
    sqlStatements.push(``);

    for (const record of rocksData) {
      // Get all columns that have values
      const entries = Object.entries(record).filter(([_, value]) => value !== undefined);
      const columns = entries.map(([key, _]) => toSnakeCase(key));
      const values = entries.map(([_, value]) => escapeSqlValue(value));

      sqlStatements.push(`INSERT INTO rocks (${columns.join(', ')})`);
      sqlStatements.push(`VALUES (${values.join(', ')});`);
      sqlStatements.push(``);
    }
  }

  // Footer
  sqlStatements.push(`-- ============================================`);
  sqlStatements.push(`-- EXPORT COMPLETE`);
  sqlStatements.push(`-- Total Rocks Exported: ${rocksData.length}`);
  sqlStatements.push(`-- ============================================`);

  // Write to file
  const outputPath = join(process.cwd(), 'exports', 'rocks-only-export.sql');
  writeFileSync(outputPath, sqlStatements.join('\n'), 'utf-8');

  console.log('\n✅ Rocks export complete!');
  console.log(`📄 File saved to: ${outputPath}`);
  console.log(`   Total Rocks: ${rocksData.length}`);

  process.exit(0);
}

exportRocks().catch((error) => {
  console.error('Export failed:', error);
  process.exit(1);
});

