import { db } from '../server/db';
import { roadmaps, priorities, rocks, justGetItDoneItems } from '../shared/schema';
import { eq } from 'drizzle-orm';
import { writeFileSync } from 'fs';
import { join } from 'path';

const COMPANY_ID = '200c32ef-28fe-4fa7-995d-96386671e89e';

// Helper to convert camelCase to snake_case
function toSnakeCase(str: string): string {
  return str.replace(/[A-Z]/g, letter => `_${letter.toLowerCase()}`);
}

// Helper to escape SQL strings
function escapeSqlString(value: any): string {
  if (value === null || value === undefined) {
    return 'NULL';
  }
  if (typeof value === 'boolean') {
    return value ? 'true' : 'false';
  }
  if (typeof value === 'number') {
    return String(value);
  }
  if (value instanceof Date) {
    // Handle Date objects as timestamps
    return `'${value.toISOString()}'`;
  }
  if (typeof value === 'object') {
    // JSON field
    return `'${JSON.stringify(value).replace(/'/g, "''")}'::jsonb`;
  }
  // String - escape single quotes
  return `'${String(value).replace(/'/g, "''")}'`;
}

async function exportData() {
  console.log('Starting data export for company:', COMPANY_ID);

  const sqlStatements: string[] = [];

  // Header
  sqlStatements.push(`-- ============================================`);
  sqlStatements.push(`-- OPSP STRATEGY APP - PRODUCTION DATA EXPORT`);
  sqlStatements.push(`-- Company: Small Giants (${COMPANY_ID})`);
  sqlStatements.push(`-- Generated: ${new Date().toISOString()}`);
  sqlStatements.push(`-- ============================================`);
  sqlStatements.push(``);
  sqlStatements.push(`-- INSTRUCTIONS:`);
  sqlStatements.push(`-- 1. Open Replit Database pane`);
  sqlStatements.push(`-- 2. Switch to PRODUCTION database`);
  sqlStatements.push(`-- 3. Select all INSERT statements and run`);
  sqlStatements.push(`-- 4. Verify your data appears correctly`);
  sqlStatements.push(``);

  // Export Roadmaps
  console.log('Exporting roadmaps...');
  const roadmapData = await db.select().from(roadmaps).where(eq(roadmaps.companyId, COMPANY_ID));
  console.log(`Found ${roadmapData.length} roadmap(s)`);

  if (roadmapData.length > 0) {
    sqlStatements.push(`-- ============================================`);
    sqlStatements.push(`-- ROADMAPS (${roadmapData.length} record${roadmapData.length !== 1 ? 's' : ''})`);
    sqlStatements.push(`-- ============================================`);

    for (const record of roadmapData) {
      const columns = Object.keys(record).filter(k => record[k as keyof typeof record] !== undefined);
      const snakeColumns = columns.map(toSnakeCase);
      const values = columns.map(col => escapeSqlString(record[col as keyof typeof record]));

      sqlStatements.push(`INSERT INTO roadmaps (${snakeColumns.join(', ')})`);
      sqlStatements.push(`VALUES (${values.join(', ')});`);
      sqlStatements.push(``);
    }
  }

  // Export Priorities
  console.log('Exporting priorities...');
  const priorityData = await db.select().from(priorities).where(eq(priorities.companyId, COMPANY_ID));
  console.log(`Found ${priorityData.length} priority/priorities`);

  if (priorityData.length > 0) {
    sqlStatements.push(`-- ============================================`);
    sqlStatements.push(`-- PRIORITIES (${priorityData.length} record${priorityData.length !== 1 ? 's' : ''})`);
    sqlStatements.push(`-- ============================================`);

    for (const record of priorityData) {
      const columns = Object.keys(record).filter(k => record[k as keyof typeof record] !== undefined);
      const snakeColumns = columns.map(toSnakeCase);
      const values = columns.map(col => escapeSqlString(record[col as keyof typeof record]));

      sqlStatements.push(`INSERT INTO priorities (${snakeColumns.join(', ')})`);
      sqlStatements.push(`VALUES (${values.join(', ')});`);
      sqlStatements.push(``);
    }
  }

  // Export Rocks
  console.log('Exporting rocks...');
  const rocksData = await db.select().from(rocks).where(eq(rocks.companyId, COMPANY_ID));
  console.log(`Found ${rocksData.length} rock(s)`);

  if (rocksData.length > 0) {
    sqlStatements.push(`-- ============================================`);
    sqlStatements.push(`-- ROCKS (${rocksData.length} record${rocksData.length !== 1 ? 's' : ''})`);
    sqlStatements.push(`-- ============================================`);

    for (const record of rocksData) {
      const columns = Object.keys(record).filter(k => record[k as keyof typeof record] !== undefined);
      const snakeColumns = columns.map(toSnakeCase);
      const values = columns.map(col => escapeSqlString(record[col as keyof typeof record]));

      sqlStatements.push(`INSERT INTO rocks (${snakeColumns.join(', ')})`);
      sqlStatements.push(`VALUES (${values.join(', ')});`);
      sqlStatements.push(``);
    }
  }

  // Export Just Get It Done Items
  console.log('Exporting just get it done items...');
  const jgidData = await db.select().from(justGetItDoneItems).where(eq(justGetItDoneItems.companyId, COMPANY_ID));
  console.log(`Found ${jgidData.length} just get it done item(s)`);

  if (jgidData.length > 0) {
    sqlStatements.push(`-- ============================================`);
    sqlStatements.push(`-- JUST GET IT DONE ITEMS (${jgidData.length} record${jgidData.length !== 1 ? 's' : ''})`);
    sqlStatements.push(`-- ============================================`);

    for (const record of jgidData) {
      const columns = Object.keys(record).filter(k => record[k as keyof typeof record] !== undefined);
      const snakeColumns = columns.map(toSnakeCase);
      const values = columns.map(col => escapeSqlString(record[col as keyof typeof record]));

      sqlStatements.push(`INSERT INTO just_get_it_done_items (${snakeColumns.join(', ')})`);
      sqlStatements.push(`VALUES (${values.join(', ')});`);
      sqlStatements.push(``);
    }
  }

  // Footer
  sqlStatements.push(`-- ============================================`);
  sqlStatements.push(`-- EXPORT COMPLETE`);
  sqlStatements.push(`-- Total Records Exported:`);
  sqlStatements.push(`--   Roadmaps: ${roadmapData.length}`);
  sqlStatements.push(`--   Priorities: ${priorityData.length}`);
  sqlStatements.push(`--   Rocks: ${rocksData.length}`);
  sqlStatements.push(`--   Just Get It Done: ${jgidData.length}`);
  sqlStatements.push(`-- ============================================`);

  // Write to file
  const outputPath = join(process.cwd(), 'exports', 'smallgiants-production-export.sql');
  writeFileSync(outputPath, sqlStatements.join('\n'), 'utf-8');

  console.log('\n✅ Export complete!');
  console.log(`📄 File saved to: ${outputPath}`);
  console.log(`\nSummary:`);
  console.log(`  - Roadmaps: ${roadmapData.length}`);
  console.log(`  - Priorities: ${priorityData.length}`);
  console.log(`  - Rocks: ${rocksData.length}`);
  console.log(`  - Just Get It Done: ${jgidData.length}`);
  console.log(`  - Total: ${roadmapData.length + priorityData.length + rocksData.length + jgidData.length} records`);

  process.exit(0);
}

exportData().catch((error) => {
  console.error('Export failed:', error);
  process.exit(1);
});

