import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { useAuth } from "@/contexts/AuthContext";
import { useToast } from "@/hooks/use-toast";
import { SettingsIcon, UserIcon, LogOutIcon, CheckIcon, XIcon } from "lucide-react";
import { apiRequest } from "@/lib/queryClient";

export default function Settings() {
  const { user, logout } = useAuth();
  const { toast } = useToast();
  const [isEditing, setIsEditing] = useState(false);
  const [name, setName] = useState(user?.name || "");
  const [isSaving, setIsSaving] = useState(false);

  const handleSave = async () => {
    if (!user) return;

    setIsSaving(true);
    try {
      await apiRequest(`/api/users/${user.id}`, 'PUT', { name });
      toast({
        title: "Success",
        description: "Your name has been updated",
      });
      setIsEditing(false);
      // Refresh the page to update the user context
      window.location.reload();
    } catch (error: any) {
      toast({
        title: "Error",
        description: error.message || "Failed to update name",
        variant: "destructive",
      });
    } finally {
      setIsSaving(false);
    }
  };

  const handleCancel = () => {
    setName(user?.name || "");
    setIsEditing(false);
  };

  const handleLogout = async () => {
    try {
      await logout();
    } catch (error: any) {
      toast({
        title: "Error",
        description: "Failed to logout",
        variant: "destructive",
      });
    }
  };

  return (
    <div className="space-y-6 p-6">
      {/* Page Header */}
      <div className="border-b border-cyan-500/20 pb-4">
        <div className="flex items-center gap-3 mb-2">
          <SettingsIcon className="w-6 h-6 text-cyan-400" />
          <h1 className="text-2xl font-bold text-cyan-300">Settings</h1>
        </div>
        <p className="text-sm text-cyan-400/60">
          Manage your account settings and preferences
        </p>
      </div>

      {/* Account Settings Card */}
      <Card className="bg-card/50 border-cyan-500/20">
        <CardHeader className="pb-3">
          <CardTitle className="flex items-center gap-2 text-lg text-cyan-300">
            <UserIcon className="w-5 h-5" />
            Account Information
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          {/* Email (read-only) */}
          <div>
            <label className="text-sm font-medium text-cyan-300 mb-2 block">
              Email
            </label>
            <Input
              value={user?.email || ""}
              disabled
              className="bg-slate-800/50 border-cyan-500/30 text-slate-400 cursor-not-allowed"
            />
            <p className="text-xs text-slate-500 mt-1">
              Email cannot be changed
            </p>
          </div>

          {/* Name (editable) */}
          <div>
            <label className="text-sm font-medium text-cyan-300 mb-2 block">
              Name
            </label>
            {isEditing ? (
              <div className="flex gap-2">
                <Input
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  className="flex-1 bg-slate-800/50 border-cyan-500/30 text-slate-300"
                  placeholder="Enter your name"
                  autoFocus
                  disabled={isSaving}
                />
                <Button
                  size="icon"
                  variant="ghost"
                  onClick={handleSave}
                  className="h-10 w-10 text-green-400 hover:text-green-300"
                  disabled={isSaving}
                >
                  <CheckIcon className="h-4 w-4" />
                </Button>
                <Button
                  size="icon"
                  variant="ghost"
                  onClick={handleCancel}
                  className="h-10 w-10 text-red-400 hover:text-red-300"
                  disabled={isSaving}
                >
                  <XIcon className="h-4 w-4" />
                </Button>
              </div>
            ) : (
              <div className="flex gap-2">
                <Input
                  value={user?.name || "Not set"}
                  disabled
                  className="flex-1 bg-slate-800/50 border-cyan-500/30 text-slate-400"
                />
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => setIsEditing(true)}
                  className="border-cyan-500/30 text-cyan-400 hover:bg-cyan-500/10"
                >
                  Edit
                </Button>
              </div>
            )}
          </div>

          {/* Role (read-only) */}
          <div>
            <label className="text-sm font-medium text-cyan-300 mb-2 block">
              Role
            </label>
            <Input
              value={user?.role || ""}
              disabled
              className="bg-slate-800/50 border-cyan-500/30 text-slate-400 cursor-not-allowed capitalize"
            />
          </div>
        </CardContent>
      </Card>

      {/* Actions Card */}
      <Card className="bg-card/50 border-cyan-500/20">
        <CardHeader className="pb-3">
          <CardTitle className="text-lg text-cyan-300">Actions</CardTitle>
        </CardHeader>
        <CardContent>
          <Button
            variant="outline"
            onClick={handleLogout}
            className="w-full border-red-500/30 text-red-400 hover:bg-red-500/10 hover:text-red-300"
          >
            <LogOutIcon className="w-4 h-4 mr-2" />
            Logout
          </Button>
        </CardContent>
      </Card>
    </div>
  );
}
